/* 由 tools/build_lib.js 从 tools/lib_notes/shijingf/*.json 组装，请勿手改。 */
LIT.addLibNotes({"shijingf_taoyao":{"intro":"《周南·桃夭》是一首贺新娘出嫁的歌，三章只换了几个字：花换成果、果换成叶，室家换成家室、家人。读它要抓两件事：起兴的那棵桃树怎样跟着新娘的一生在变；每章反复的“宜”字，夸的究竟是什么样的好。","focus":["三章起兴依次写桃花（灼灼其华）、桃实（有蕡其实）、桃叶（其叶蓁蓁），从开花到结果再到枝叶繁茂，正好对应出嫁、生育、持家的一生期待。比兴在这里不是开头的装饰，而是整首诗的时间线。","每章末句都落在“宜”字上：宜其室家、宜其家室、宜其家人。“宜”是和顺、相称，夸的不是容貌，而是能让一个家安稳兴旺，这是周人婚礼祝词的价值重心。","“夭夭”“灼灼”“蓁蓁”三组叠字声音明亮，每章只换两三个字，是《国风》重章叠句的典型写法，便于众人在婚礼上反复合唱，祝福的意思也在重复中一层层加深。"],"notes":[["夭夭","茂盛而美好的样子"],["灼灼","花色鲜明，像火一样"],["华","同“花”"],["之子","这位女子"],["于归","出嫁。古人称女子出嫁为“归”"],["宜","和顺，使……和睦"],["室家","夫妇、家庭"],["蕡","果实硕大饱满的样子"],["蓁蓁","叶子茂密"],["家人","一家人"]],"think":["这首诗只夸新娘“宜其室家”，几乎不写她的容貌和心情。你怎么看这种“好妻子”的标准？","可以从两面看：一面，婚礼祝词代表家族和乡邻的期待，“宜”是对新家庭和睦兴旺的祝福，并不贬低个人；另一面，全诗没有新娘自己的声音，个人感受让位给了家庭功能。判断时要分清“诗在当时的用途”和“今天的价值标准”。"],"quiz":[["诗中“之子于归”的“归”是什么意思？",["女子出嫁","回娘家","归顺"],"古人称女子出嫁为“归”，意思是到了真正的归宿；回娘家另称“归宁”。"],["三章起兴依次写了桃树的什么？",["花、果实、叶子","花、枝条、根","叶子、花、果实"],"灼灼其华（花）、有蕡其实（果实）、其叶蓁蓁（叶子），从开花到结果到繁茂。"],["每章末句反复出现的“宜”字，主要称赞新娘什么？",["能使家庭和顺兴旺","容貌美丽","出身高贵"],"宜其室家、宜其家室、宜其家人，都说她能让夫家和睦安稳，重心在德行与家庭，不在容貌。"]],"cards":[["桃之夭夭，灼灼其华。下两句是？","之子于归，宜其室家。"],["《桃夭》三章起兴的变化有什么用意？","花→果→叶，对应出嫁、生育、持家，比兴就是全诗的时间线。"]],"line":["桃之夭夭，灼灼其华","给同事的婚礼贺卡上写：桃之夭夭，灼灼其华——祝你们的新家像这棵桃树，花开、结果、枝繁叶茂。"],"tags":["婚嫁","比兴","重章叠句"]},"shijingf_gedan":{"intro":"《周南·葛覃》写一个女子在家等待归宁：先看山谷里葛藤蔓延，再写她采葛、煮葛、织成粗细布，最后落到洗衣、告假、回娘家。全诗平实如叙事，没有一句议论，读它要看清“葛”怎样从野草变成衣服，又怎样把一个人的日常心思带出来。","focus":["首章以葛草蔓延中谷、黄鸟集于灌木起兴，叶子萋萋，鸟声喈喈，是一幅夏日山谷的声景。次章“是刈是濩，为絺为绤”紧接着把草写成工序：割、煮、织，细布与粗布都做出来，起兴之物与劳动之物是同一株葛，起兴不是闲笔。","“服之无斁”一句容易读过：做成的衣服穿着不嫌厌。它说明这位女子对自己亲手织的东西很满意，诗里的劳动不是苦役，是带着自得的家务，这在后面的《国风》劳动诗里并不常见。","末章换成人物对话的口气：“言告师氏，言告言归”，先向师氏告假，再说回家。“薄污我私，薄浣我衣。害浣害否”像一边收拾一边自语，哪件要洗、哪件不用，琐碎得真实。结句“归宁父母”才揭出整首诗的目的。"],"notes":[["覃","延长，蔓延"],["施","延伸，蔓延"],["萋萋","草木茂盛"],["莫莫","茂密的样子"],["刈","割"],["濩","煮"],["絺","细葛布"],["绤","粗葛布"],["斁","厌倦"],["师氏","女师，教导女子的人，此处指向她告假的对象"],["归宁","出嫁女子回娘家探望父母"]],"think":["这首诗没有写新妇的婆家，也没有写丈夫，只写出嫁女子准备回娘家。你觉得为什么古人愿意把这样一件小事写进诗里？","归宁是出嫁女子与娘家保持感情的正式机会，在宗法社会里是需要“告”（请示）才能成行的事，所以告师氏、备衣服才会被认真写下。可以读成当时女性生活节点的一个切片；但全诗到底是出嫁前还是出嫁后，传统与后人说法不一，要承认这一点存疑。"],"quiz":[["“为絺为绤”里，絺和绤分别指什么？",["细葛布和粗葛布","丝绸和麻布","夏衣和冬衣"],"絺是细葛布，绤是粗葛布，同一种葛草织出精粗两种布。"],["第三章的“害浣害否”大意是？",["哪件要洗，哪件不用洗","为什么要洗衣服","洗不洗都害怕"],"害同“曷”，意思是哪个、什么；“浣”洗，“否”不洗，是一边挑拣一边自语。"]],"cards":[["“葛之覃兮，施于中谷”写的是什么？","葛藤在山谷中蔓延生长，是全诗起兴，也是后文割葛织布的原料。"],["《葛覃》全诗最终的目的是什么？","出嫁女子准备好衣服，向师氏告假，回娘家探望父母（归宁）。"]],"line":["言告师氏，言告言归","团队里要出差回老家，先向领导报备再动身，可以引一句“言告师氏，言告言归”，说明凡事先告知再行动。"],"tags":["劳动","归宁","赋"]},"shijingf_juaner":{"intro":"《周南·卷耳》开头写女子采卷耳，采了半天筐也不满，因为心里想着远人；后三章却突然转到那个远行者的路上：登高冈、马疲、仆病。一首诗里两处场景、两个人，是《诗经》中思念诗最早的“对写”结构。","focus":["首章“采采卷耳，不盈顷筐”是整首诗的心理底色：手在采，心不在，筐总不满。“嗟我怀人，置彼周行”，把筐放在大路边，思念已使她放弃了手头的活，这是用动作写心思。","后三章每章第一句都是“陟彼”，崔嵬、高冈、砠依次递进，马的状态也依次加重：虺隤、玄黄、瘏，到第四章连仆人都病了。每登一层，路更险，人更疲，节奏上像一步一步爬坡。","传统多把后三章读成女子想象丈夫在路上的情形，也有读成同一个人（征夫或思妇）的自述，存疑。无论怎么读，“我姑酌彼金罍，维以不永怀”是一种以酒自解的无奈，而末章“云何吁矣”以一个长叹收住，不给出路。"],"notes":[["卷耳","一种野菜，苍耳"],["顷筐","斜口浅筐，容易装满的筐"],["周行","大路"],["崔嵬","高而不平的山"],["虺隤","马疲病无力"],["金罍","青铜酒器"],["兕觥","犀牛角做的酒器，泛指大酒杯"],["玄黄","马病得毛色变了"],["砠","有土的石山"],["瘏","马病累"],["痡","人病累"],["吁","忧叹"]],"think":["全诗到底是谁在说话？分别读作“女子想象丈夫”与“同一人自述”，会读出什么不同？","读作女子想象，诗的重心在“我想象你受苦”，是替对方担忧，感情更深一层；读作自述，重心在自己路上的疲惫与借酒自解。哪个更合理难以定论，但“嗟我怀人”“云何吁矣”都出现在第一人称语气里，所以两种读法都说得通，依据只有全诗句式的切换。"],"quiz":[["首章“不盈顷筐”说明什么？",["采者心不在焉，思念使她无心劳作","卷耳很稀少","筐子太大"],"顷筐本来容易装满，仍然装不满，是心不在焉的写法。"],["后三章“我马虺隤”“我马玄黄”“我马瘏矣”的变化说明什么？",["马的疲病逐章加重，路越走越难","马换了三匹","马越走越快"],"从“虺隤”到“玄黄”到“瘏”，对应崔嵬、高冈、砠，一步比一步险。"]],"cards":[["“采采卷耳，不盈顷筐”体现什么手法？","以动作写心理：手在采，心在远处，筐总是不满。"],["《卷耳》结构上的特别之处？","前章写女子在家，后三章转到远行者在路，视角切换，思念成为双向。"]],"line":["采采卷耳，不盈顷筐","项目收尾的前一周，大家都心不在焉，可以说这是“采采卷耳，不盈顷筐”，活在做，心没有收回来。"],"tags":["思念","对写","酒"]},"shijingf_jiumu":{"intro":"《周南·樛木》三章只有几个动词在变：葛藟“累”之、“荒”之、“萦”之；福履“绥”之、“将”之、“成”之。读它要看清这种“只换一字”的递进怎样让祝福一步步加码，也要知道这首诗最常被后世引用的就是“福履绥之”。","focus":["起兴是下垂的樛木与缠绕其上的葛藟：“累”“荒”“萦”三个动词，从缠绕到覆盖再到环绕，藤越攀越密，写的是依附与相助。以藤依树，意思是君子能庇荫人，这是兴而比的写法。","后一句每章换一个“福履”的动词：绥是安，将是扶助，成是成就。从使人心安，到有所扶持，再到事有所成，是一个从内心到外事的递进，三章读完，祝福已走完一个完整的人生期待。","“乐只君子”是三章不变的受颂对象。诗里没交代他是谁，婚礼、宴会、对地位较高者的颂祝都有解释，这里存疑，不必强落具体场合；它的价值在于句子结构简单而祝福感饱满。"],"notes":[["樛木","向下弯曲的树"],["葛藟","一种蔓生藤本"],["累","缠绕"],["荒","覆盖"],["萦","环绕"],["乐只","快乐啊（只是语助词）"],["君子","这里指受祝颂的贵人"],["福履","福禄"],["绥","安抚，使安"],["将","扶助"],["成","成就"]],"think":["同样是祝福诗，《桃夭》祝新娘，《樛木》祝君子，你能看出两种祝福重心的不同吗？","《桃夭》落在“宜其室家”，期待的是一个家庭的和顺；《樛木》落在“福履”，期待的是一个人的福禄与事业成功。前者向内，后者向外。可以比较二者起兴：桃是自身的花果叶，藤是依附于树，一个是生命周期，一个是互相成就的关系。"],"quiz":[["三章“累之、荒之、萦之”描写的是？",["葛藟缠绕樛木的不同情态","樛木生长的三个阶段","葛藟被风吹倒"],"都是写藤蔓依附树木，是兴句，不是写树的变化。"],["“福履绥之”的“绥”是什么意思？",["安，使人心安","砍断","送走"],"绥是安抚、使安，与将（扶助）、成（成就）构成递进。"]],"cards":[["《樛木》三章里随章变的是哪两处？","起兴的葛藟动词（累、荒、萦）和祝福的动词（绥、将、成）。"],["“福履绥之”意思？","福禄使他安稳。"]],"line":["南有樛木，葛藟累之","谈到好团队互相托举，可以引“南有樛木，葛藟累之”，一棵树把枝条垂下来，藤才攀得上去。"],"tags":["祝福","比兴","重章叠句"]},"shijingf_tuju":{"intro":"《周南·兔罝》没有写战争，只写一个人在林中设网捕兔：网子扎得整齐，木桩敲得叮当响，然后话头一转，这个人是“赳赳武夫”，是“公侯干城”。读它要看到：一个体力劳动的场景怎样被抬到了国家的高度。","focus":["开头“肃肃兔罝，椓之丁丁”声色并具：肃肃是网的整饬，丁丁是钉桩的声音，画面与声音都很干净利落。以捕兔这种细小的活计写武夫，说明这个人做事一丝不苟。","后一句每章换一个称谓：干城（防卫的盾牌与城墙）、好仇（好伙伴）、腹心（心腹之人）。从外围防御，到平起平坐，再到内心依赖，逐章拉近，与场地由“丁丁”到“中逵”“中林”的由近及远，方向恰好相反，一外一内形成张力。","诗里的“赳赳”是魁伟勇武的样子，而全篇并没有武打，反而是捕兔，这是周人对武士的一种颂扬方式：勇武要落在日常的勤谨上。读者要警惕后人加上的政教解释，直接读句子就够了。"],"notes":[["肃肃","整饬严谨的样子"],["罝","捕兔的网"],["椓","敲击，打桩"],["丁丁","敲击木桩的声音"],["赳赳","雄健威武的样子"],["武夫","武士"],["干城","盾牌和城墙，比喻保卫者"],["中逵","四通八达的大路"],["好仇","好伴侣，仇同“逑”"],["中林","林中"],["腹心","心腹"]],"think":["“公侯干城”“公侯好仇”“公侯腹心”三者，是同一个意思的重复，还是层层推进？","推进。干城是被依靠的外在防线，好仇是身份相当的搭档，腹心是内里相托的亲信。从“用他”到“并肩”再到“托付”，是信任的升级，这在管理里相当于从岗位胜任到团队伙伴再到核心骨干。但也要承认，这样读有现代解读成分，古人未必这样分层。"],"quiz":[["“公侯干城”中“干城”的比喻义是？",["保卫者","叛乱者","使者"],"干是盾牌，城是城墙，合起来指保卫国家的人。"],["诗以什么活计来写武夫？",["设网捕兔","耕田","狩猎大兽"],"诗以“肃肃兔罝，椓之丁丁”这种设网钉桩的细致活计，来衬武夫的严整与稳。"]],"cards":[["“赳赳武夫，公侯干城”的意思？","勇武的武士，是公侯可以依靠的屏障。"],["《兔罝》三章不变的前半，变的后半是什么？","前半写设网，后半换成干城、好仇、腹心，逐步升级对武夫的评价。"]],"line":["赳赳武夫，公侯干城","年终总结里夸一位执行力很强的业务骨干：真正的“赳赳武夫，公侯干城”，关键时刻靠得住。"],"tags":["武士","赞美","重章叠句"]},"shijingf_fuyi":{"intro":"《周南·芣苡》只有二十四个字的变化：“采采芣苡”重复六遍，每章只换后一句里的一个动词，有、掇、捋、袺、襭。没有人物，没有感叹，也没有任何比兴，却是《诗经》里被后人谈得最多的一首。读它要抓住：一连串动作怎样替代了抒情。","focus":["全诗每章只换第二句的动词：采、有，掇、捋，袺、襭，是从采到有，再到装满。“有”是拿到手，“掇”是拾取，“捋”是顺着茎摘下，“袺”是提起衣襟兜着，“襭”是把兜起的衣襟掖在腰带上，装多了才需要这一步。六个动词合起来就是一次采集的完整过程。","动作由简到繁、由少到多，节奏随之越来越满。读者不需要被告知“采得很多”，从“襭”这一个动作，就知道收获已满。这是以最少的字写出过程的典型。","“采采”二字重复，既有采了又采，又有茂盛的含义。整首诗等于一段劳动号子，无情节，重在节拍。古人看重它，是因为在不加任何说教的情况下，诗仍然成立，这是最小的诗。"],"notes":[["采采","采了又采，一说茂盛"],["芣苡","车前草，一说此名"],["薄言","语助词，没有实义"],["有","取得"],["掇","拾取"],["捋","顺着摘取"],["袺","提起衣襟兜着"],["襭","把衣襟掖在腰带上兜着"]],"think":["这首诗几乎没有任何语义信息，今天读来它的价值在哪里？","价值在节奏和过程：它示范了不靠比喻与抒情，只靠动词的更替就能写出一件事的完整进程。也可以看成是一种声音的艺术，原本是唱的，重复和换字让集体合唱容易跟进。要避免把它读成“妇人祈求生育”之类的说法，后世确有此解，但原文没有任何支撑，只能当存疑的传统说法。"],"quiz":[["《芣苡》六章中，什么在变化？",["每章第二句的动词","采集的对象","采集的地点"],"六句只换“有、掇、捋、袺、襭”等动词，其余不变。"],["“袺之”“襭之”的动作分别是？",["提起衣襟兜着，再掖在腰带上","割草，捆草","晒干，收藏"],"袺是提襟，襭是把襟角掖进腰带，两个动作都是装满之后的“兜”。"]],"cards":[["《芣苡》的核心艺术手法？","重章叠句，只换动词，用动作的递进代替抒情。"],["“薄言”是什么意思？","没有实义的语助词。"]],"line":["采采芣苡，薄言采之","做一件繁琐而重复的事，可以用一句“采采芣苡，薄言采之”，提醒自己：一件一件做，装满自然会看见。"],"tags":["劳动","重章叠句","动词"]},"shijingf_hanguang":{"intro":"《周南·汉广》写一个樵夫爱上汉水边出游的女子，却求之不得。三章末尾的叠句“汉之广矣，不可泳思；江之永矣，不可方思”，把求而不得写成汉水宽、江水长，是《诗经》里最早的“可望不可即”。读它要看清两层：对象的不可及，与愿望的卑微而真切。","focus":["首章“南有乔木，不可休息。汉有游女，不可求思”把乔木与游女并列：高树不可歇，游女不可求，都是够不着的东西。一个物象一个人，用类比暗示这份感情的无望。","叠句“汉之广矣，不可泳思。江之永矣，不可方思”共出现三次，每次都是一样的话。反复本身就是主题：不是一次碰壁，而是想一次碰一次。“泳”是游过去，“方”是用筏渡，一游一渡，把能想到的办法一一否定。","中间的“之子于归，言秣其马”最动人：假如她出嫁，我愿意为她的马添草。注意“于归”这个词在《桃夭》里是祝福新娘，在这里却是别人娶走了她；他没有怨，只愿意去做最卑微的服侍，这是爱情诗里极含蓄的一笔。"],"notes":[["乔木","高大的树"],["游女","出游的女子，一说汉水女神，存疑"],["汉","汉水"],["泳","游水渡过"],["江","长江"],["永","长，长远"],["方","用筏子渡过"],["翘翘","高出的样子"],["错薪","杂乱的柴草"],["刈","割"],["楚","一种灌木，荆条"],["秣","喂马"],["蒌","蒌蒿"]],"think":["为什么全诗同一个叠句要重复三次，且一字不改？","因为主题是“无法逾越”。如果每章换一种说法，就有“尝试不同办法”的意味，一字不改则像是一次次撞在同一堵墙上。它是形式服务内容的例子。反例可以看《桃夭》的换字，那里是递进，这里是停滞，两种重章手法目的不同。"],"quiz":[["“汉之广矣，不可泳思”中的“泳”指什么？",["游水渡过","漂浮","洗澡"],"泳是游水渡河，与“方”（乘筏）配对，说明游、渡两种办法都行不通。"],["“言秣其马”表现男子怎样的态度？",["愿为对方的婚礼服务，毫无怨言","要抢走马匹","阻止婚礼"],"秣是喂马，表示假如她出嫁，他愿意为她喂马，含蓄而卑微的深情。"]],"cards":[["“汉之广矣，不可泳思”比喻什么？","对方可望而不可即，像汉水宽到游不过去。"],["《汉广》里“之子于归，言秣其马”的含义？","假如她出嫁，我也愿意给她的马喂草，是无望爱情中的卑微深情。"]],"line":["汉之广矣，不可泳思","面对短期内无法跨越的行业壁垒，可以说“汉之广矣，不可泳思”，换一条思路，或者先去造一只筏子。"],"tags":["求爱","叠句","汉水"]},"shijingf_rufen":{"intro":"《周南·汝坟》写的是一个妇人沿汝水大堤砍柴，心里念着出远门的丈夫。第一章饥渴般的思念，第二章“既见君子”的释然，第三章忽然转入“王室如毁”的时局，又拉回“父母孔迩”的现实。读它要看清情感怎样从个人的相思落到家国和孝养的重量。","focus":["首章“未见君子，惄如调饥”用饥来写思念，调饥是早晨空腹的饥饿感，身体的真实感觉被用来写情感。次章“既见君子，不我遐弃”紧接着写重逢，两章前后对照，思念的苦与相见的安都落在“君子”一个人身上。","第三章“鲂鱼赪尾，王室如毁”转得突然：鲂鱼尾巴发红，是劳累过度，用来象征人民疲惫；王室如毁，是政局紧迫。这一笔让前面的私人感情放进了时代背景，也解释了丈夫为何远行。","末句“虽则如毁，父母孔迩”是全诗最耐读的转折：虽然时局如火烧，但父母就在身边，需要奉养。她从担心丈夫转到劝自己、也劝丈夫：别逃离。这一句既含劝慰，也含无奈，对象存疑，可以读成妻子对丈夫的话，也可读作自语。"],"notes":[["遵","沿着"],["汝坟","汝水的大堤"],["条枚","树的枝干"],["惄","忧思，如饥饿般难受"],["调饥","早晨的饥饿，一说“朝饥”"],["条肄","砍后重新长出的嫩枝"],["遐弃","远弃，抛弃"],["鲂鱼","一种鱼，即鳊鱼"],["赪尾","尾巴红了"],["王室如毁","王室局势危急如烈火"],["孔迩","很近"]],"think":["“虽则如毁，父母孔迩”是在劝丈夫留下，还是在劝自己忍耐？","两种读法并存。劝丈夫，是说别为国事去冒险，父母还要人养；劝自己，是说时局再坏，我也得把眼前的日子过好。关键证据是“既见君子，不我遐弃”，说明君子已经回来，所以更像是对他说。但如果把这当成劝慰，那是对“王室如毁”的一种个人化回应，值得多读几遍。"],"quiz":[["“惄如调饥”用什么来比思念？",["早晨空腹的饥饿感","口渴","寒冷"],"调饥是早饥，用身体感觉来比思念的难受。"],["第三章为什么忽然写“王室如毁”？",["交代时局动荡的背景","描写战争场面","赞美君主"],"这一笔把个人的思念放进大局，说明丈夫远行、妻子忧心的根源。"]],"cards":[["“未见君子，惄如调饥”的意思？","没见到丈夫，心里像空着肚子一样难受。"],["《汝坟》结尾为何落到父母？","虽然国事艰难，仍要顾念父母，由相思转入孝养与现实。"]],"line":["未见君子，惄如调饥","长期出差，想念家人时可以说“未见君子，惄如调饥”，不是修辞，是真的有点饿。"],"tags":["思妇","汝水","家国"]},"shijingf_quechao":{"intro":"《召南·鹊巢》写的是一场迎亲：新娘的车队有百辆，用来迎、送、成礼。比喻是鸠居鹊巢，这是姑娘嫁入夫家的意象。读它要注意：这个意象在后世变成成语“鸠占鹊巢”，意思完全反过来，而原诗用它是祝福。","focus":["起兴“维鹊有巢，维鸠居之”：鹊筑巢，鸠来居住。三章动词随之变化：居之、方之、盈之，从住下到占据，再到住满，对应新娘入住夫家的三步。","后一句“之子于归，百两御之”对应迎、将、成：御是迎接，将是护送，成是成礼。“百两”是百辆车，极言场面之盛，周代婚礼用车以示隆重。从迎到送到成，三章就是一场婚礼的完整流程。","原诗没有半点贬义，后世成语“鸠占鹊巢”是另一种读法：强占他人的居所。可见比喻的意思不由本体决定，而由语境赋予。读古诗时要避免被后来的成语带偏。"],"notes":[["维","语助词"],["鹊","喜鹊"],["鸠","鸤鸠，一说斑鸠"],["之子于归","这位女子出嫁"],["百两","百辆车，两通“辆”"],["御","迎接"],["方","占有，居住"],["将","护送"],["盈","住满"],["成","完成婚礼"]],"think":["“鸠占鹊巢”今天是贬义，原诗却是祝福，这个转变对我们读古诗意味着什么？","意味着不能拿后世成语的义项倒推古诗。成语源于对“鸠不会筑巢”这一习性的观察，转为占别人东西的意思；而诗里的比喻点是“居所有了主人”，即新娘入住夫家。读诗要先看本文语境，再看成语演变。"],"quiz":[["“百两御之”的“两”是什么？",["车辆","重量","一双"],"两通“辆”，百两即百辆车。"],["原诗里“维鹊有巢，维鸠居之”的比喻含义是？",["新娘入住夫家","强占他人住所","鸟类迁徙"],"诗是迎亲颂歌，没有贬义，后来成语才变成强占之意。"]],"cards":[["《鹊巢》三章里“御之、将之、成之”分别对应？","迎接、护送、成礼，是婚礼的三个步骤。"],["原诗与成语“鸠占鹊巢”的区别？","诗里是祝福的比喻，成语变成了强占的贬义。"]],"line":["维鹊有巢，维鸠居之","新人入住新居，可以写“维鹊有巢，维鸠居之”，本意是祝福安居。"],"tags":["婚嫁","比兴","成语"]},"shijingf_caochong":{"intro":"《召南·草虫》写一个女子在秋天思念未归的丈夫：草虫鸣叫，蚱蜢跳跃，她上山采蕨、采薇。三章结构完全对应：“未见君子”的忧，“亦既见止，亦既觏止”的假想，“我心则降”的放下。读它要看心理怎样一层层从忧到安。","focus":["起兴“喓喓草虫，趯趯阜螽”是秋声：草虫喓喓，阜螽趯趯，成对跳跃，女子见了更想念人。以动物成双映衬自己的孤单，这是《诗经》常用的“反衬”。","三章的忧愁用词递进：忡忡、惙惙、伤悲。忡忡是心神不宁，惙惙是忧而疲惫，伤悲则是悲伤到底。对应的释然也递进：降（放下）、说（喜悦）、夷（平静）。同一首诗中情绪走了一个完整的弧线，且是在想象中完成的。","“亦既见止，亦既觏止”是假设：如果见到了，如果遇上了。诗里没有重逢，只有重逢的想象，而这一想象足以让心安定。思念的诗常用现实写忧、用假想写安，使读者看到希望，也看到眼前仍然未见的现实。"],"notes":[["喓喓","草虫的鸣声"],["趯趯","跳跃的样子"],["阜螽","蚱蜢一类的虫"],["忡忡","心神不安"],["惙惙","忧愁疲惫"],["觏","遇见"],["降","放下，平息"],["蕨","一种野菜"],["薇","一种野菜，即野豌豆"],["夷","平静"]],"think":["全诗的重逢只是想象，为何情绪能够“降”“说”“夷”？这种心理机制你怎么看？","想象重逢，等于预演了不确定性的消失，焦虑因而降低。这在现代心理上有类似的“预期的慰藉”。但诗人不说重逢是否实现，因此慰藉始终悬着，诗的张力也在这里：希望是真的，等待也是真的。"],"quiz":[["“我心则降”的“降”大意是？",["放下，平息","降落","投降"],"“降”这里是心中的忧愁放下、平息。"],["三章“忧心忡忡、惙惙、伤悲”的变化是？",["忧愁逐渐加深","忧愁逐渐消失","情绪毫无变化"],"忡忡到惙惙到伤悲，每章忧的程度更深，与后半的降、说、夷形成对照。"]],"cards":[["《草虫》里“亦既见止，亦既觏止”表示什么？","想象与丈夫相见，并非真的见到，以假想的重逢安慰自己。"],["起兴的草虫阜螽有什么作用？","秋声与成对的跳跃映衬孤单，勾起思念。"]],"line":["未见君子，忧心忡忡","出差半个月没见家人，发消息时写“未见君子，忧心忡忡”，总比“想你”显得有分寸。"],"tags":["思妇","秋","心理"]},"shijingf_gantang":{"intro":"《召南·甘棠》的主角是一棵树：召伯曾在这棵甘棠下歇过脚、住过宿，后人就嘱咐“别剪它，别砍它”。全诗没有一句夸召伯，却是对他最深的怀念。读它要体会由物及人、以保护代替颂扬的写法。","focus":["三章前半句“蔽芾甘棠，勿翦勿伐”“勿翦勿败”“勿翦勿拜”，动词层层加重：翦（剪枝）、伐（砍倒）、败（毁坏）、拜（拔，一般读作“拔”）。写的是对树的不同伤害，防的是各种可能，语气像在叮嘱孩子。","后半句“召伯所茇”“所憩”“所说”写的是召伯的行止：搭草棚住宿、休息、解下车驾歇脚。三个动词都是日常的停留，没有政绩和功德，但让一个人以“曾坐在这棵树下”的形象留在民间记忆里。","召伯是谁，传统多认为是召公奭，也有人另指他人，存疑。无论如何，诗的方法很清楚：怀念不靠言辞颂扬，而靠保护一件小事物。这在今天也是一个常见的纪念方式，比如保护故居。"],"notes":[["蔽芾","树叶小而茂盛的样子"],["甘棠","棠梨树"],["翦","剪，修剪"],["伐","砍伐"],["败","毁坏"],["拜","拔，一般读作“拔”"],["召伯","召公，传统多指召公奭，存疑"],["茇","在草地上搭棚居住"],["憩","休息"],["说","通“税”，解驾休息"]],"think":["这首诗既然没有夸召伯，为什么被认为是对他的赞美？","因为“勿翦勿伐”这一禁令本身就是一种评价：能让百姓为一棵树设禁，说明那个人在人们心里有分量。这是以行动代替评语的写法。反过来想，如果一个人离开后没人愿意保护他留下的东西，这就是另一种评价。"],"quiz":[["“勿翦勿败”的“败”指什么？",["毁坏树木","打败","失败"],"“败”指毁坏，与“翦（剪）、伐（砍）、拜（拔）”共同构成对树的伤害。"],["全诗用什么方式表达对召伯的怀念？",["保护他停留过的甘棠树","描写他的功绩","赞美他的容貌"],"诗不夸人，只写保护他休息过的树，是由物及人。"]],"cards":[["“蔽芾甘棠，勿翦勿伐”的意思？","那棵枝叶茂盛的甘棠树，不要剪也不要砍。"],["《甘棠》体现什么写作思路？","由物及人，以保护一棵树表达对一个人的怀念。"]],"line":["蔽芾甘棠，勿翦勿伐","老同事离职后留下的办公桌，大家舍不得换，可以引“蔽芾甘棠，勿翦勿伐”。"],"tags":["纪念","召伯","由物及人"]},"shijingf_xinglu":{"intro":"《召南·行露》是《诗经》里少见的“对簿公堂”之作：一个女子被强逼婚事，闹到打官司，她在诉讼中把话说得斩钉截铁：“虽速我讼，亦不女从。”读它要注意起句的路上露水、后两章的两个反问，以及末句的坚决。","focus":["首章“厌浥行露，岂不夙夜，谓行多露”：露水湿润，难道我不想早起赶路，是怕路上露多。这里的“行多露”是借口，也是比喻，暗示拒绝与对方来往的原因，不愿沾污自己。","次章“谁谓雀无角？何以穿我屋”用生活常识反问：麻雀没有角怎么穿透我的屋；“谁谓女无家？何以速我狱”：你说我没有婚家（没有礼聘），怎么招来官司。两个类比句拆穿对方：雀能穿屋靠的是喙，你能告我却是没有道理。","末章把“鼠”换“雀”，把“狱”换“讼”，句式一字不差，语气却越来越硬：“虽速我狱，室家不足”“虽速我讼，亦不女从”。最后一句“亦不女从”，不论你诉讼到哪里，我都不顺从。这是《国风》中女性对强权的明确回绝。"],"notes":[["厌浥","潮湿的样子"],["行露","道路上的露水"],["夙夜","早晚，早起夜行"],["谓","通“畏”，怕"],["雀","麻雀"],["角","喙，一说兽角"],["穿","穿透"],["速","招致"],["狱","诉讼，官司"],["墉","墙"],["讼","打官司"],["室家不足","婚姻礼数不足，存疑"]],"think":["全诗为什么要先写“行露”，再写“雀”和“鼠”？","首章是比，说明她不愿让名声沾污；二、三章是类比，反问对方的逻辑。顺序是先立场（我不走露多的路），再辩论（你的理由站不住），最后表态（我不从）。这是一个说理结构，可以看到《诗经》诗不全是抒情，也有近乎诉状的论证。"],"quiz":[["“谁谓雀无角？何以穿我屋”的论证方式是？",["以雀有喙反问，揭示对方并非无理由地诉讼","夸耀麻雀","描写房屋"],"用雀能穿屋必有喙的常识，类推出对方告我必有所图，是一种类比反问。"],["末句“亦不女从”的“女”是？",["你，通“汝”","女子","女儿"],"“女”通“汝”，你的意思，“亦不女从”即也不顺从你。"]],"cards":[["《行露》最后一句的态度？","即使被告上公堂，也绝不顺从。"],["“谁谓雀无角”的修辞？","反问兼类比，以事实反驳对方的无理。"]],"line":["虽速我讼，亦不女从","面对不合理的条款，可以引“虽速我讼，亦不女从”，意思是即使走到谈判桌外，也不会签字。"],"tags":["女性","反问","诉讼"]},"shijingf_gaoyang":{"intro":"《召南·羔羊》描写一个官员穿着羊羔皮袍，下班回家吃饭，“委蛇委蛇”。全诗三章换字不换意，只写衣着与步态，却留下一个难解的问题：它是赞美官员的从容正直，还是暗讽他的闲适？读它要看衣、步、时三者怎样组合成一个形象。","focus":["每章前两句写衣：羔羊之皮、之革、之缝，素丝五紽、五緎、五总。“皮”“革”“缝”是同一件袍子的不同部位，“紽”“緎”“总”是缝饰的丝线数量。三章都在写袍子的工整，而且是素丝，不奢华。","后两句“退食自公，委蛇委蛇”写人：从公门回来吃饭，神态从容。第二、三章倒装成“委蛇委蛇，自公退食”“退食自公”，是《国风》里常见的回环写法，连语序的变化都带着舒缓的节奏。","古来有颂有讽两种读法：颂其节俭正直，讽其享受俸禄、闲适有余。诗里没有明说，要看“素丝”的“素”与“委蛇”的从容，究竟读作清廉还是安逸，存疑。能确定的是，一首诗只写衣与步，也能勾勒出一个人的气质。"],"notes":[["羔羊","小羊"],["革","去毛的皮"],["素丝","白丝"],["紽","缝饰的丝线数，一种计量"],["退食","退朝回家吃饭"],["自公","从公门出来"],["委蛇","从容自得的样子"],["缝","皮袍的缝合处"],["緎","同“紽”，缝线的计量"],["总","同“紽”，缝线的计量"]],"think":["同一首诗，既可读作赞美，又可读作讽刺，你怎么判断？","只能看证据：诗里“素丝”暗含朴素，“退食自公”暗含勤于公务，这支持赞美；“委蛇委蛇”的悠闲、反复的从容，则为讽刺留下余地。没有上下文旁证时，宜两说并存。读古诗不要强求一个标准答案，而要知道每一种读法的依据。"],"quiz":[["“退食自公”是什么意思？",["从公门出来回家吃饭","退还食物","退出公职"],"退食，指退朝（或下班）回家用餐，自公指从公门出来。"],["三章中“皮、革、缝”指什么？",["同一件袍子的不同部位","三种不同的动物","三种官职"],"都指羔羊皮袍，是对衣着不同部位的描写。"]],"cards":[["“委蛇”是什么意思？","从容自得、舒缓走路的样子。"],["《羔羊》的读法争议在哪？","是赞美官员节俭正直，还是讽刺其安逸，需要看上下文，存疑。"]],"line":["退食自公，委蛇委蛇","下班后不急不忙走出办公楼，可以说一句“退食自公，委蛇委蛇”，既有点打趣，也是自得。"],"tags":["官员","衣着","回环"]},"shijingf_yinqilei":{"intro":"《召南·殷其雷》是妻子对远行丈夫的呼唤：南山传来雷声，她问：你为什么离开这里？没有一刻能闲下来？末句每章都是同样的呼喊：“归哉归哉！”读它要听出雷声里的催促，与三章“遑”字的变化。","focus":["起兴是“殷其雷，在南山之阳”：雷声隆隆，从山南到山侧再到山下，位置逐章移动，声音像在靠近，也像在催促。雷声本是风雨之兆，在这里暗示丈夫出行的辛劳。","“何斯违斯”是问句，翻译成现代话就是：这个人怎么在这里离开了。三章的后半句改字：“莫敢或遑”“莫敢遑息”“莫或遑处”，遑是闲暇，息是休息，处是安居，从没有空闲，到不敢休息，再到不能安居，困苦逐层加深。","“振振君子”的“振振”是诚实仁厚的样子，妻子在抱怨中依然称赞丈夫。末尾“归哉归哉”重复而不加修饰，是呼喊也是祈愿。整首诗没有写任何战事与职责，只写等待，使得这份怨与爱更纯粹。"],"notes":[["殷","雷声"],["阳","山的南面"],["违","离开"],["斯","这个，此处"],["遑","闲暇"],["莫敢或遑","不敢有一点闲暇"],["息","休息"],["处","安居"],["振振","诚实厚道的样子"],["君子","这里指丈夫"]],"think":["妻子一边埋怨丈夫离家，一边称他“振振君子”，这种矛盾说明什么？","说明怨的对象是处境而不是人。她理解丈夫是因公务不得已，因此怨而不怒。这类“怨而不怒”的情绪表达，是《国风》中大量思妇诗的共同底色，也是后人所说“温柔敦厚”的实例之一。"],"quiz":[["“莫敢或遑”“莫敢遑息”“莫或遑处”的层层加深体现在？",["从无暇、无法休息到无法安居","丈夫逐渐回家","丈夫愈发悠闲"],"遑、息、处分别指闲暇、休息、安居，困苦一层深过一层。"],["“殷其雷”起兴的作用？",["以雷声烘托催促与辛劳","描写天气预报","赞美南山"],"雷声作为背景声，既有催促之感，也象征丈夫奔波的辛劳。"]],"cards":[["“何斯违斯”的口吻？","妻子的追问：你为什么离开这里？"],["每章结尾“归哉归哉”表达什么？","对丈夫早日回家的呼唤。"]],"line":["殷其雷，在南山之阳","远程办公的伙伴突然被调走，可以写“殷其雷，在南山之阳”，不动声色地抱怨一下。"],"tags":["思妇","呼唤","雷声"]},"shijingf_biaoyoumei":{"intro":"《召南·摽有梅》是一首待嫁女子的歌：树上的梅子落下来，起初还剩七成，后来只剩三成，最后装进筐里。她对“庶士”喊：趁吉日来求我，趁今日，哪怕只要一句话。读它要看时间怎样压迫成情感。","focus":["三章的梅子从“其实七兮”到“其实三兮”，再到“顷筐塈之”，一路是数量递减、最后落尽。这是以物候写年华：梅子落了，女子的青春也在流逝。时间焦虑并没有出现“老”字，仅靠数字就让人感觉到。","对应的呼声是：“迨其吉兮”“迨其今兮”“迨其谓之”。迨是趁着，吉是吉日，今是今天，谓之是开个口说一声。从选择良辰，到不等良辰，再到只要一句话，求婚的门槛一层层降低，她的焦急也一层层升高。","这首诗之所以被称道，是因为女子主动发声，直接说出对婚嫁的期待，毫不扭捏。后世的说教往往强调“礼”，但原诗没有提礼，只写时间。读它宜还原成民间节令的歌，不必拔高。"],"notes":[["摽","落下"],["其实七兮","树上的梅子还剩七成"],["庶士","众位男子"],["迨","趁着"],["吉","吉日"],["顷筐","斜口浅筐"],["塈","取，一说拾取"],["谓之","开口说一声"]],"think":["三章中“迨”后面的词不断降低要求，这对读者有什么感受上的作用？","降低要求等于增加急迫。第一章还强调吉日，第二章只要今天，第三章只要一句话：每一步的让步都是在说“我没有更多时间了”。这是用条件的退让写心理的紧迫，比直接说“我很着急”更有力。"],"quiz":[["三章梅子数量的变化表现什么？",["青春年华的流逝","梅子的收成","树木的生长"],"梅子由七到三到落尽，象征时间流逝，女子青春渐逝。"],["“迨其谓之”的意思？",["趁着你开口说一句","趁着吉日","趁着梅子"],"“谓”是说，“谓之”即开口提出，是最低的门槛。"]],"cards":[["“摽有梅”的比兴含义？","梅子落下，比喻青春流逝，引出求婚的急切。"],["三章“迨其”后面的词语变化？","吉日、今日、一句话，逐步降低要求，催促加深。"]],"line":["摽有梅，其实七兮","看到日历一页页减少，可以说“摽有梅，其实七兮”，提醒自己别拖到最后。"],"tags":["待嫁","时间","物候"]},"shijingf_yeyousijun":{"intro":"《召南·野有死麕》三章：野外有死獐，白茅包着；有位少女正怀春，青年来追求；最后一句是女子的低语：“无感我帨兮，无使尨也吠。”读它要看一个小场面：礼物、少女、狗、佩巾，没有一句话说出“爱”，却把情意、紧张与羞涩全摆出来了。","focus":["首章“野有死麕，白茅包之”，把猎物用白茅包好，是求爱的礼物；“有女怀春，吉士诱之”点明场景。二章“林有朴樕，野有死鹿。白茅纯束，有女如玉”再写一遍，以“如玉”赞美女子。礼物、洁净的白茅与玉，三者形成一个干净的意象。","末章三句短促急促：“舒而脱脱兮，无感我帨兮，无使尨也吠。”舒而脱脱是缓缓地、轻轻地；不要动我的佩巾；不要惊动狗。一连串“不要”把现场拉紧，又透出羞怯里的默许。","这首诗的解释分歧很大：有人读作求爱的野外情诗，有人读作暗含强迫的场景。判断的关键是“怀春”和“舒而脱脱”：前者说她心有所动，后者说她要求对方温柔，更接近前者。仍要保留存疑。"],"notes":[["麕","獐子"],["白茅","一种草，洁净，用来包礼物"],["怀春","春心萌动，思慕异性"],["吉士","好男子"],["诱","引诱，这里指追求"],["朴樕","小树"],["纯束","捆扎"],["舒而脱脱兮","舒缓而轻柔的样子"],["帨","佩巾"],["尨","多毛的狗"]],"think":["读这首诗时，为什么说“无使尨也吠”这一句最关键？","因为这一句露出女子的态度：她担心被人发现，却没有叫人，反而叮嘱对方别惊动狗。这是默许的暗示。同时，“无感我帨”又说明她要求对方分寸，不是毫无防备。两句合起来，写的是一场被约束的亲近，而不是简单的顺从或抗拒。"],"quiz":[["“白茅包之”的作用是？",["包裹礼物，表示郑重","防止野兽","盖住尸体"],"白茅洁净，用来包裹猎物作为求爱的礼物。"],["“无感我帨兮”是谁对谁说？",["女子对男子","男子对女子","旁人对男子"],"“帨”是女子的佩巾，女子请对方别动她的佩巾，轻声而羞涩。"]],"cards":[["“有女怀春，吉士诱之”写的是什么？","少女春心萌动，青年上前追求。"],["末章三句的情感特点？","短促、轻声、羞怯，既含默许，也含克制。"]],"line":["有女如玉","夸一位人品清洁的同事，可以轻声说一句“有女如玉”，带着欣赏而不轻佻。"],"tags":["情诗","礼物","存疑"]},"shijingf_beizhoubei":{"intro":"《邶风·柏舟》是一个心里压着事、夜里睡不着的人在自述：向兄弟诉苦碰壁，被小人欺侮，想飞走又飞不起来。最著名的是中段“我心匪石，不可转也；我心匪席，不可卷也”。读它要看清怨愤怎样靠一连串否定句撑住，以及末章“不能奋飞”的无力。","focus":["起句“泛彼柏舟，亦泛其流”：柏木船随水漂流，没有方向。接着是“耿耿不寐，如有隐忧”，把漂泊感转成内心的失眠。随后“微我无酒，以敖以游”，不是没有酒与游乐，而是这些都解不了忧，反写法。","“我心匪鉴，不可以茹”是说心不是镜子，不能什么都容纳；“我心匪石”“匪席”则是说心不是石头可以转、不是席子可以卷。三个“匪”字句，把自己的心写成既不能被随意映照，也不肯被改变，是全诗的筋骨。","诗末“静言思之，不能奋飞”，由刚强落到无力：心既不肯转，人又飞不走。“如匪浣衣”写忧愁像没洗的脏衣紧贴身上。这类仁人不遇之作，传统多指向有才德者受谗；具体作者与背景，存疑。"],"notes":[["泛","漂浮"],["耿耿","心中不安的样子"],["隐忧","深藏的忧愁"],["以敖以游","出外游玩"],["匪鉴","不是镜子"],["茹","容纳，包容"],["匪石","不是石头"],["棣棣","富丽闲雅的样子"],["愠","怨恨，恼怒"],["觏闵","遭遇忧患"],["寤辟有摽","醒来捶胸"],["日居月诸","日月，感叹语"],["浣衣","洗衣"]],"think":["“我心匪石，不可转也”后世常被引来表达坚定，但全诗的主人公并没有因坚定而得救，这一点如何理解？","坚定与处境是两回事。这首诗把一个有原则的人放在没有出路的环境里：心不转，但也飞不走。后世引用时常只截取前半，忽略末章的无力，其实后半才是全诗的真实：坚持原则的代价。读古诗不要只摘名句，要看句子在整篇中的位置。"],"quiz":[["“我心匪石，不可转也”的意思是？",["石头尚可转动，我的心却不可转移","我的心像石头一样冰冷","我的心像石头一样沉重"],"“匪石”是“不是石头”，句式意在“石头尚可转，我心不可转”，强调坚定。"],["末章“不能奋飞”表现了什么？",["想离开却无法离开的无力","展翅高飞","向往自由，如愿以偿"],"诗中人心志坚定，却无法摆脱困境，以不能奋飞收尾，转为无力。"]],"cards":[["柏舟里的“匪鉴”“匪石”“匪席”有什么共同点？","都是否定比喻，强调心不被映照、不被转移、不被卷起。"],["“如匪浣衣”写什么？","忧愁像没洗的脏衣，紧贴在身，摆脱不掉。"]],"line":["我心匪石，不可转也","在原则问题上，可以用“我心匪石，不可转也”表明态度，但别忘了给自己留一条路。"],"tags":["忧愤","否定句","仁人不遇"]},"shijingf_lvyi":{"intro":"《邶风·绿衣》从一件绿衣开始：绿衣黄裹，绿衣黄裳。衣色颠倒，心里的忧愁也没有尽头。这首诗在传统里有两种读法：妻室失位的怨，或睹衣怀念亡人的哀思。读它要抓住“衣”如何一路牵出“丝”、牵出“女所治”、牵出“古人”。","focus":["前两章“绿兮衣兮，绿衣黄裹”“绿衣黄裳”写的是衣色错位：绿是间色，黄是正色，按古人的穿着标准，正色应该在外、在上。说颠倒，是说地位或秩序颠倒，所以“心之忧矣，曷维其已”，忧愁不能停。","第三章转入“绿兮丝兮，女所治兮”：这丝是你亲手所织。这一转，使衣服从“颜色的错位”变成了“人的痕迹”，读者可以顺势将全诗读成悼亡：睹物思人，物还在，人不在。“我思古人”的“古人”一说是故人，一说是古代贤人，存疑。","末章“絺兮绤兮，凄其以风”：夏天的细布粗布，遇到秋风觉得凄冷，是季节错位，也是情感错位。“实获我心”是说“古人”的做法正合我心，也是自我宽慰。诗里没有一处说明“你是谁”，所以后世两种读法都留得下来。"],"notes":[["绿衣黄裹","绿色的外衣，黄色的里子（裹同里）"],["黄裳","黄色的下衣"],["曷维其已","什么时候才能停止"],["曷维其亡","什么时候才能忘记，一说停止"],["女所治兮","你亲手织的"],["古人","故人，一说古代贤人，存疑"],["俾无訧兮","使我没有过失"],["絺","细葛布"],["绤","粗葛布"],["凄其以风","凄凉，因为风吹"]],"think":["同一首诗被读作“嫡妻失位”与“悼亡”两种，你更倾向哪一种，依据是什么？","第三章“女所治兮”和“实获我心”更容易支持悼亡或怀人读法：衣物成为亡者的遗物。而第一、二章的“黄里”“黄裳”强调颜色秩序，更容易支持地位失序读法。两种读法对应的文本部分不同，没有一个能解释全诗，所以要承认存疑，也可以分章读。"],"quiz":[["“绿衣黄裹”之所以让人忧，是因为？",["色彩错位，象征秩序颠倒","衣服太旧","衣服太贵"],"按古人观念，黄是正色，绿是间色，绿外黄里是正间颠倒。"],["“女所治兮”的“女”指？",["你，通“汝”","女子","女儿"],"“女”通“汝”，“你所织的”，说明衣出自亲人之手。"]],"cards":[["“绿衣黄裹”的象征意义？","颜色错位，象征秩序颠倒或处境不顺。"],["《绿衣》后两章的转折？","由衣转到丝，再转到织衣的人，睹物生情，读成悼亡也说得通。"]],"line":["心之忧矣，曷维其已","遇到长期没有解决的问题，可以说“心之忧矣，曷维其已”，带着一点自嘲。"],"tags":["悼亡","睹物","存疑"]},"shijingf_yanyan":{"intro":"《邶风·燕燕》写送别：前三章写送行路上的眼见与泪水，“瞻望弗及，泣涕如雨”，末章忽然转入对远行者品德的追忆与嘱托。传统认为是卫庄姜送归妾戴妫，存疑。读它要看自然景物（燕）怎样伴着情感，最后一章为何改变语气。","focus":["起兴“燕燕于飞，差池其羽”：燕子飞时翅膀参差，“颉之颃之”写上下翻飞，“下上其音”写鸣声。三章写燕子从形到动再到声，同时人在送行：“远送于野”“远于将之”“远送于南”，送行的路越走越远。","三章结尾“瞻望弗及”是整首诗的核心动作：站在原地看，却看不见了。“泣涕如雨”“伫立以泣”“实劳我心”，感情由眼泪到站定再到心上的疲累，没有一句喊叫，哀伤在慢慢下沉。","末章“仲氏任只，其心塞渊。终温且惠，淑慎其身”忽然变成赞颂，又说“先君之思，以勖寡人”：想起先君，你要勉励我。这一转，使离别从私人的哀伤变成共同的责任感，情绪有了抑制，也有了份量。"],"notes":[["燕燕","燕子"],["差池","参差不齐"],["颉之颃之","飞上飞下"],["将","送"],["瞻望","远望"],["泣涕","眼泪"],["伫立","久立"],["仲氏","排行第二的人"],["任只","信实啊"],["塞渊","诚实深远"],["淑慎","善良谨慎"],["勖","勉励"]],"think":["为何末章不再写离别，而写对方的美德与先君？","因为前三章已经把情感推到顶点，再写只会重复。转到美德，是把私人的悲伤转成公共的意义：送别的人不仅是为失去一个亲人，也是在重申一份共同的期许与责任。这也是中国送别诗里常见的“情后以德”结构。"],"quiz":[["“瞻望弗及”的意思是？",["远望已经看不见了","望得见","没有望"],"弗及是追不上、看不到，写目送至尽头。"],["末章与前三章的主要区别是？",["由送别场景转入对人品的赞颂与嘱托","继续描写燕子","抱怨路途遥远"],"末章写“终温且惠，淑慎其身”，并以先君之思相勉，转为赞颂与嘱托。"]],"cards":[["《燕燕》三章反复出现的动作？","瞻望弗及，站着看远行者直到看不见。"],["“燕燕于飞，差池其羽”的作用？","以燕子飞翔起兴，烘托送别的情景与离去的人。"]],"line":["瞻望弗及，泣涕如雨","送同事离职，车已远去，在朋友圈只写一句“瞻望弗及”，比任何长篇都更到位。"],"tags":["送别","起兴","哀伤"]},"shijingf_jigu":{"intro":"《邶风·击鼓》是一个随军出征的人在远方写下的诗。最后一章的“死生契阔，与子成说。执子之手，与子偕老”后来成为爱情的名句，但在原诗里，这是一个被战争拆散的人对当初誓约的回忆，紧接着是对“不我活”“不我信”的哀叹。读它要看名句怎样回到它的原处。","focus":["开头“击鼓其镗，踊跃用兵”鼓声作响，士兵跃跃出战；“土国城漕，我独南行”写别人在国内筑城，我却独自南征。一个“独”字，写出被选中的不幸与孤独。","第三章“爰居爰处？爰丧其马？于以求之？于林之下”写行军中的失落：到哪里停下？马丢了，到树林下去找。三个问句连发，是战争中迷失与慌乱的写照，也把全诗从壮烈拉回到琐碎。","“死生契阔，与子成说”中，契阔是聚散，成说是立下的约定。执子之手是约定的具体动作。后面“于嗟阔兮，不我活兮；于嗟洵兮，不我信兮”则说：唉，相隔太远了，我活不到再相聚；唉，约定太远了，我无法守信。约定是否实现已经被战争否定，这才是原诗的重量。"],"notes":[["镗","鼓声"],["踊跃用兵","奋勇练武，准备打仗"],["土国城漕","在国内修土功，在漕邑筑城"],["孙子仲","卫国将领"],["平陈与宋","调停陈国与宋国"],["爰","于是，在何处"],["契阔","离合聚散"],["成说","立下约定"],["偕老","一起到老"],["于嗟","叹词，唉"]],"think":["名句“执子之手，与子偕老”放回原诗，意义会有什么变化？","单独看是浪漫的誓言，放回全诗是战场上的承诺，且很可能无法兑现。誓约与战争并置，使它从甜美变成沉重。这样的变化提醒读者：被后世反复引用的句子，常常在原来的语境里有更复杂的意味。这一点在婚礼上引用，意思已经不同，但无不可。"],"quiz":[["“死生契阔”的“契阔”是什么？",["离合聚散","契约","宽广"],"契阔指分离与聚合，死生契阔即无论生死、聚散。"],["“土国城漕，我独南行”表现什么情绪？",["别人留守，我独自远征的孤独","对筑城的赞美","对南方风景的喜爱"],"“独”字强调被迫远行，与国内修建城邑的人形成对比。"]],"cards":[["“执子之手，与子偕老”的原诗语境？","战场上对爱人或战友的誓约，随后是对约定难以实现的哀叹。"],["“爰丧其马”写什么？","行军中马丢失，写出慌乱与迷失。"]],"line":["执子之手，与子偕老","今天婚礼上引这句话时，可知它的起点是战场，那份誓言带着重量。"],"tags":["征戍","誓约","名句"]},"shijingf_kaifeng":{"intro":"《邶风·凯风》是一个儿子写给母亲的自责诗：母亲养育七个孩子，辛劳一生，而孩子们没有一个能让她安心。全诗用南风、棘树、黄鸟起兴，没有激烈的话，只有一连串的自我检讨。读它要看自然景物怎样替母亲说话。","focus":["首章“凯风自南，吹彼棘心”是兴：温暖的南风吹着棘树的嫩芽，棘心夭夭，母氏劬劳。风是母亲，棘心是孩子，被吹养的孩子刚冒芽，已经是母亲辛劳的结果。二章“棘薪”写树长成了柴，孩子长大了，可是“母氏圣善，我无令人”：母亲是好的，我却不成器。","第三章“爰有寒痊”以下转到泉水：浚地有寒泉可以润泽，七个儿子却没有一个能让母亲安适。这里把泉水之润与儿子之无用并列，是一种对比。","末章以“睍睆黄鸟，载好其音”收：黄鸟尚能发出悦耳的声音，七子却“莫慰母心”。鸟声是愉悦，人的无能更显得刺目。整首诗以自责代替赞美，是以反面写孝思的写法。"],"notes":[["凯风","南风，和暖的风"],["棘心","酸枣树的嫩芽"],["夭夭","茂盛嫩美的样子"],["劬劳","辛苦劳累"],["棘薪","长大的酸枣树，可作柴"],["圣善","明智善良"],["令人","好人"],["浚","地名"],["睍睆","鸟声清和好听"],["黄鸟","黄雀，一种鸟"],["莫慰母心","没有一个能安慰母亲的心"]],"think":["全诗没有一个字直接赞美母亲，却读出了深深的敬爱，这是如何做到的？","靠对比：把母亲的付出与自己的无能放在同一画面。越是自责，越说明母亲的好。这种以自我贬低衬托对方的写法，在后世家书和悼文里很常见，但真诚才是关键：诗里的七个儿子并非没有努力，而是知道努力永远还不完。"],"quiz":[["“凯风”指什么风？",["南风","北风","秋风"],"凯风是南风，温暖的风，比喻母亲的养育。"],["“莫慰母心”的“莫”指？",["没有一个人","不要","不能"],"莫在这里是“没有谁”，意思是七个儿子没有一个能慰藉母亲。"]],"cards":[["“凯风自南，吹彼棘心”比喻什么？","母亲抚养孩子，南风吹着嫩芽，比喻母爱的养育。"],["末章以黄鸟收尾的作用？","鸟声悦耳，反衬儿子无能，加重自责。"]],"line":["有子七人，莫慰母心","年终回家发现父母仍在为自己操心，可以想起“有子七人，莫慰母心”。"],"tags":["孝思","自责","起兴"]},"shijingf_gufengbei":{"intro":"《邶风·谷风》是一个被丈夫抛弃的妻子的自述：新人来了，她被赶走，回想自己如何持家、如何与他共苦。与卫风《氓》同属弃妇诗，但《谷风》更像一份细账：每一章都是一笔“我做了什么”和“你怎么待我”。读它要看这份清单如何逐项摊开。","focus":["首章“习习谷风，以阴以雨”写风雨交加，是情感的天气。“采葑采菲，无以下体”是比喻：采萝卜类菜，不能因为根不好就不要叶子；意思是不能因为我的容貌衰了，就弃我的整个人。这是以日常劳动写日常道理。","中段“就其深矣，方之舟之。就其浅矣，泳之游之”列出她的付出：水深用舟，水浅用泳，不论难易，都为这个家奔波。“凡民有丧，匍匐救之”则说，邻里有难，她也尽力帮忙。这是一笔笔的功劳账。","后段的对比最锋利：“宴尔新婚，以我御穷”——他新婚快乐，却把我当作抵挡贫穷的存粮；“我有旨蓄，亦以御冬”是说我储存的美食，是用来过冬的，现在你却用来待新人。这一句既写储备，也写自己被利用后抛弃。结尾“不念昔者，伊余来塈”，说你不念旧日我给你的安慰。"],"notes":[["习习","和风的声音"],["黾勉","勤勉努力"],["葑","芜菁，一种菜"],["菲","萝卜一类"],["下体","根茎部分"],["荼","苦菜"],["荠","荠菜，味甜"],["宴尔新婚","你们新婚快乐"],["湜湜","水清见底的样子"],["不我能畜","不能好好对待我"],["旨蓄","美味的储备"],["御冬","抵御冬天"],["有洸有溃","暴怒的样子"],["塈","安息，安慰"]],"think":["《谷风》与《氓》都是弃妇诗，你看出两者在“自述方式”上的区别吗？","《氓》是叙事：从相识到婚嫁到被弃，有时间线。《谷风》是算账：把付出一项项摊开，更像申诉。前者抒情更多，后者说理更多。也可以说，《氓》里的女子在回顾过去，《谷风》里的女子在争取一个说法，只是两者都没有得到。"],"quiz":[["“采葑采菲，无以下体”比喻什么？",["不能因为一处缺点而否定整个人","采菜的技巧","种菜的方法"],"葑菲的根茎有时不好，但叶子仍可食，比喻不能因为容貌衰就弃妻。"],["“宴尔新婚，以我御穷”的意思是？",["你们新婚快乐，却把我当作抵御穷困的人","你们新婚，我很高兴","你们新婚，我来帮忙"],"“御穷”是抵挡贫穷，说明他在艰难时依靠她，过上好日子便弃之。"]],"cards":[["“就其深矣，方之舟之”写什么？","水深就用舟，水浅就游泳，写她为家庭不论难易地努力。"],["“我有旨蓄，亦以御冬”的含义？","我储备的食物原为过冬，如今被你拿来待新人，暗指自己被利用。"]],"line":["宴尔新婚，以我御穷","合作伙伴在困难时依靠你，顺境时就换了新的，可以说这是“宴尔新婚，以我御穷”。"],"tags":["弃妇","清单式","比喻"]},"shijingf_shiwei":{"intro":"《邶风·式微》只有两章，二十来个字，却是《诗经》里最直白的一声呼喊：天黑了，为什么还不回家？“微君之故，胡为乎中露”，要不是为了您，我何必在露水里；“微君之躬，胡为乎泥中”，要不是为了您自身，我何必在泥里。读它要听出这句问话的对象，与后面的责怪。","focus":["首句“式微，式微，胡不归”，式是语助，微是昏暗；天黑了天黑了，为什么不回家？它既是自问，也是对同伴说，是疲惫的人在日暮时的本能反应。这一问在后世成为“归”主题的起点。","后两句句式严格对应：“微君之故，胡为乎中露”“微君之躬，胡为乎泥中”。“微”是若非，“君”是被问话的对象，整个句子是说：如果不是为了您，我何必在露水里、泥水中受苦。这句话里有怨，也有不得不服从的无奈。","传统解释说是黎侯寓居卫国，臣下劝他归国，也有读成劳役者向主人的怨语，存疑。两种读法都靠“君”字：对象是国君，还是役主。文字这样简短，才使这首诗几百年来一直是怀归的象征。"],"notes":[["式","语助词"],["微","昏暗，一说衰微"],["胡不归","为什么不回家"],["微君之故","若不是为了您的缘故"],["胡为乎","为什么要"],["中露","在露水中，一说地名"],["躬","自身"],["泥中","在泥泞中"]],"think":["为什么说“胡不归”是《诗经》里最有力的一问？","因为它没有任何装饰，只是一句最基本的人类要求：该回家了。越是平实，越能引起共鸣。它也可以读成对不合理劳役的无声抗议：用一个看似天真的问句，表达不能公开说的不满。读古诗，朴素往往比华丽更有力。"],"quiz":[["“微君之故”的“微”是什么意思？",["若不是","微小","微笑"],"“微”在此是“若非、要不是”，整句即“若不是为了您的缘故”。"],["“式微”最常被后世引申为？",["衰落","升起","盛大"],"“式微”本是天黑，后引申为势力衰败，是后世的常用义。"]],"cards":[["“式微，式微，胡不归”的含义？","天黑了天黑了，为什么还不回家？"],["“微君之躬”的“微”？","若不是，表示假设否定。"]],"line":["式微，式微，胡不归","加班到深夜，在群里发一句“式微，式微，胡不归”，同事都会懂。"],"tags":["归","劳役","简短"]},"shijingf_paoyouku":{"intro":"《邶风·匏有苦叶》以济水涉渡写人事：河水深，要根据深浅选择渡法；而婚配之事，也要等对的人、对的时间。诗的后半写雁鸣旭日、冰未化，以及舟子招手而“我”不上船，因为要等“我友”。读它要看涉水的生活经验怎样被转为情感与选择。","focus":["首章“深则厉，浅则揭”是一句生活经验：水深就连衣服一起涉水，水浅就提起衣服。它后世成为随机应变的成语。放在婚恋里，意思是要因时因地行事，不能一概而论。","第二章“有弥济盈，有鷕雉鸣。济盈不濡轨，雉鸣求其牡”：济水大涨，车轴不会被淋湿，是对水位的判断；雉鸟鸣叫是求偶。这一段把渡水与求偶并写，是兴也是比。","后两章由“士如归妻，迨冰未泮”转到“招招舟子，人涉卬否”。舟子招手，别人都上了船，我却不上，“卬须我友”：我等的是我的朋友。传统读作女子等待心上人，不愿随便上别人的船。这是一个关于不凑合的选择：不是没机会，是不愿将就。"],"notes":[["匏","葫芦"],["济","济水"],["涉","涉水"],["厉","连衣涉水"],["揭","提起衣裳涉水"],["弥","大水满溢"],["鷕","雌雉的叫声"],["牡","雄性"],["雍雍","雁的和鸣声"],["泮","融化"],["招招","招手的样子"],["舟子","船夫"],["卬","我，一说古代第一人称"]],"think":["“深则厉，浅则揭”被后世当作处世名言，放回诗里看，是否也有婚恋的含义？","有。诗中紧接着写雉鸣求偶、士迎娶妻，说明渡水之喻就是对婚恋时机与方式的指点：要审时度势，不要蛮干。把它引申为处世智慧并不违背原意，但应当明白：它在原诗里并不是孤立的格言，而是整首诗论婚恋的一环。"],"quiz":[["“深则厉，浅则揭”的意思？",["水深就和衣涉水，水浅就提起衣裳","水深就游泳，水浅就坐船","水深不要渡，水浅可渡"],"厉是连衣涉水，揭是提衣涉水，比喻应因势而动。"],["末章“卬须我友”表现女子怎样的态度？",["宁可等候所爱的人，不随便上船","急于渡河","讨厌船夫"],"舟子招手，别人都上了船，她仍在等朋友，是不凑合的态度。"]],"cards":[["“深则厉，浅则揭”现在常被当作什么用？","随机应变、因时制宜的成语。"],["末章“人涉卬否”意思？","别人都过河，我不过，因为我在等我的朋友。"]],"line":["深则厉，浅则揭","面对复杂局面不要一刀切，“深则厉，浅则揭”，水位决定办法。"],"tags":["涉渡","婚恋","成语"]},"shijingf_jingnv":{"intro":"《邶风·静女》是一首约会情诗：女子约男子在城角相见，男子到了却找不到人，急得搔头徘徊；后来她送他一支红色的“彤管”，又送一把从郊野带回的荑草，他觉得这些东西特别美。读它要看细节的趣味：藏起来的女孩、挠头的男孩，还有送的礼物为什么美。","focus":["首章是一个小场景：“静女其姝，俟我于城隅。爱而不见，搔首踟蹰”。“爱”通“薆”，隐藏之意，她故意躲起来；他来了找不到，只好搔头徘徊。一个“搔首踟蹰”，动作鲜活，幽默感十足。","二章“静女其娈，贻我彤管。彤管有炜，说怿女美”，彤管是什么，说法不一，存疑。无论是笔还是红色的草，重点是“有炜”（鲜红有光）和“说怿女美”（因为是你送的所以我喜欢）。","末章“自牧归荑，洵美且异。匪女之为美，美人之贻”：这荑草是你从郊野带回来的，我觉得它很美，很特别。真正的美，并不是荑草本身，而是“美人之贻”。礼物之美，在于送礼的人。这两句道破了一切小礼物的心理。"],"notes":[["静女","娴静的女子"],["姝","美好"],["俟","等候"],["城隅","城角"],["爱而不见","躲着不见，爱通“薆”"],["搔首踟蹰","挠头徘徊"],["娈","美好"],["贻","赠送"],["彤管","红色的管状物，说法不一"],["说怿","喜悦"],["荑","初生的白茅，嫩芽"],["洵美且异","确实美好而且特别"]],"think":["“匪女之为美，美人之贻”为什么被后世看作爱情心理的总结？","因为它揭示了物的价值来自关系：同一把草，别人给与她给，分量不同。商业中叫品牌，爱情中叫心意。这句话也提醒我们，礼物的意义不在物本身，赠送者的身份与心意才是关键。"],"quiz":[["“爱而不见”的“爱”是什么意思？",["通“薆”，隐藏","喜爱","爱护"],"“爱”通“薆”，隐藏，意思是故意躲起来不见。"],["末章“匪女之为美”说明什么？",["礼物本身并不美，美在送礼的人","荑草是名贵的","女子长得丑"],"诗人说荑草的美，不在它本身，而在是她送的。"]],"cards":[["“搔首踟蹰”形容什么？","着急、不知所措地挠头徘徊。"],["“匪女之为美，美人之贻”的意思？","不是荑草本身美，是美人送的才美。"]],"line":["匪女之为美，美人之贻","别人收下我们送的小礼物时，可以想到“匪女之为美，美人之贻”，重要的是心意。"],"tags":["约会","情诗","细节"]},"shijingf_beimen":{"intro":"《邶风·北门》是一个小官吏的抱怨：出自北门，忧心殷殷，既穷且贫，没人知道他的艰难。公家的事压给他，政事又添给他，回到家里，家人还轮番责备。每章的结尾都是一句“已焉哉！天实为之，谓之何哉！”读它要看这种“内外夹击”怎样落成一声叹息。","focus":["首章写出门：“出自北门，忧心殷殷。终窭且贫，莫知我艰”。窭是穷得没有礼数的穷，贫是穷，莫知是没有人知道。这里还没有说到事，先说到心，是一个自觉被忽视的人。","二、三章是具体的两层压力：外面“王事适我，政事一埤益我”，公事摊给我，政事加给我；回到家，“室人交遍谪我”“摧我”，家里人轮着责备。“王事敦我，政事一埤遗我”则用“敦”“遗”换了说法，意思一样，层层加重。","每章末句“已焉哉！天实为之，谓之何哉”，是认命的叹息：算了吧，这是天意，还能说什么。这句话不是不愤怒，而是知道愤怒无用。这首诗是对基层小官吏处境最早的描写之一，读到这里，大概许多职场人会有共鸣。"],"notes":[["殷殷","忧虑深重的样子"],["终窭且贫","既窘迫又贫穷"],["莫知我艰","没有人知道我的艰难"],["已焉哉","算了吧"],["王事","君王交办的差事"],["政事","政务"],["埤益","增加"],["室人","家里人"],["交遍谪我","轮番责备我"],["敦","迫使"],["摧","折磨，挫伤"]],"think":["为什么说“已焉哉！天实为之，谓之何哉”是比愤怒更深的情绪？","愤怒还有对象和希望，认命则是知道无路可走。把一切推给“天”，是因为现实里找不到可以问责的具体对象：公事压我，家人怪我，谁都有理由。这是一种结构性困境，而不是某个人的错。读来像一声长叹，也像一份无力的申诉。"],"quiz":[["“王事适我”的意思是？",["公家的差事摊给我","国王赞美我","国王远行"],"“适”是推给、加给，“王事适我”即公事都推给我。"],["每章结尾“已焉哉”表达？",["无可奈何的认命","对未来的期待","对君王的赞美"],"“已焉哉”是“算了吧”的意思，带着无奈与认命。"]],"cards":[["“终窭且贫，莫知我艰”写出什么？","既穷又没人理解自己的艰难，是被忽视的小官吏形象。"],["“天实为之，谓之何哉”的含义？","这是天意，还有什么好说。"]],"line":["已焉哉！天实为之，谓之何哉","项目临时加了第三次需求变更，群里发一句“已焉哉”，彼此都懂。"],"tags":["小官吏","认命","职场"]},"shijingf_beizhouyong":{"intro":"《鄘风·柏舟》与《邶风·柏舟》同题，内容却不同：这首是一个女子坚定地誓言“之死矢靡它”，而母亲不体谅她。传统说是共姜誓守不再嫁而与母意冲突，存疑。读它要看两章的重复里，什么在变、什么不变，以及“母也天只”的呼唤。","focus":["起兴“泛彼柏舟，在彼中河”，柏木船漂在河中央，到第二章“在彼河侧”，漂到岸边，位置在变，却始终没有靠岸，是一种悬而未决的象征。","核心句“髧彼两髦，实维我仪”：那个垂着两髦发式的少年（髦是未成年人的发式），是我的配偶。第二章改为“实维我特”，仪、特都是配偶之意，更有“唯一”的意味。这一句确立了对象，也透露这是少年时期的婚约。","“之死矢靡它”“之死矢靡慝”：至死我立誓不改变心意。紧接着“母也天只，不谅人只”，母亲啊天啊，为什么不体谅我？两章结尾一字不改，是呼天抢地的号呼。誓言与呼喊，一个对内，一个对外，构成全诗的张力。"],"notes":[["泛","漂浮"],["髧","头发下垂的样子"],["两髦","少年两边垂下的头发"],["仪","配偶"],["特","配偶，一说匹偶"],["之死矢靡它","至死发誓不改变心意"],["矢","发誓"],["靡慝","没有邪心，没有改变"],["母也天只","母亲啊，老天啊"],["不谅","不体谅"]],"think":["这首诗里的“母亲”并没有被描写为恶人，你怎么看这场冲突？","诗里只有女子的声音，母亲不在场，也不辩解。所以我们只能知道她“不谅”，不知道她为何不谅。从社会背景看，母亲可能出于生计、门当户对等考虑。冲突的实质是个人意愿与家庭安排，两方都有各自的理由，读诗要承认单方叙述的局限。"],"quiz":[["“髧彼两髦”指什么？",["少年的发式，代指少年","女子的发式","老人的发式"],"髦是未成年男子垂在两边的头发，代指年轻的未婚夫。"],["“母也天只，不谅人只”的意思？",["母亲啊老天啊，为什么不体谅我","母亲呀，我来了","老天呀，请保佑母亲"],"“只”是语气词，女子向母亲与天呼喊，希望被理解。"]],"cards":[["“之死矢靡它”意思？","至死发誓不改变心意。"],["两篇《柏舟》的区别？","邶风写忧愤的人，鄘风写女子的守誓，同题异趣。"]],"line":["之死矢靡它","谈到对长期事业的承诺，可以说“之死矢靡它”，一旦认定，不再改变。"],"tags":["誓言","婚姻","同题"]},"shijingf_sangzhong":{"intro":"《鄘风·桑中》每章只换采的植物、地点与女子的姓：唐、麦、葑；沬之乡、沬之北、沬之东；孟姜、孟弋、孟庸。结尾三句不变：期我乎桑中，要我乎上宫，送我乎淇之上矣。读它要看这个“公式化”的结构如何把一次次约会写成固定的仪式，以及这首诗在历代评价上的分歧。","focus":["每章开头“爰采唐矣？沬之乡矣。云谁之思？美孟姜矣”，用问答式：在哪里采？在沬的乡野。想念谁？是美丽的孟姜。重复结构里，唐、麦、葑只是采集的由头，真正要说的是“云谁之思”。","后三句“期我乎桑中，要我乎上宫，送我乎淇之上矣”：在桑林中约会，在上宫迎接，淇水边相送。这是约会的完整流程：相约、相迎、相送，写得干净利落。对于桑中、上宫的所指，说法不一，存疑。","后世常把这首诗看作“淫奔之诗”，也有说它是对统治阶层的讽刺，还有读作民间情歌的。对这样的诗，应当把“如何读”与“诗是什么”分开：原文只有叙述，没有评判，评判是后人加上去的。"],"notes":[["爰","于是，在哪里"],["唐","蒙菜，一种野菜，一说菟丝子"],["沬","卫国地名"],["云谁之思","想念的是谁呢"],["孟姜","姜姓长女，泛指美女"],["孟弋","弋姓长女"],["孟庸","庸姓长女"],["期我乎桑中","约我在桑林中相会"],["要我乎上宫","在上宫迎接我"],["淇","淇水"]],"think":["同一首诗，既被指为“淫诗”，又可读作民间情歌，我们判断的标准应是什么？","先看文本说了什么：这里只有约会与送别的叙述，没有评价性的词语，“淫”的结论来自后世伦理。其次看文类：《国风》中大量男女相约的诗，是民间歌谣的常态。因此可以把它读作写男子夸耀自己有三位相约的女子，一种带夸张的民歌口吻。保留存疑即可。"],"quiz":[["“期我乎桑中，要我乎上宫，送我乎淇之上矣”的含义？",["约会、迎接、相送的完整过程","采桑的劳动","出征的送别"],"期、要、送三个动词组成一个约会流程。"],["每章变化的内容是？",["植物、地点与女子的姓","动词","结尾"],"每章换采的植物、方位和孟姜、孟弋、孟庸，结尾三句不变。"]],"cards":[["《桑中》全诗的结构特点？","每章只换植物、地点和女子名，结尾三句固定，像仪式。"],["“云谁之思”是什么句式？","设问，自问想念谁，再回答。"]],"line":["云谁之思","在谈到真正在乎的对象时，可以反问自己“云谁之思”，答案往往一目了然。"],"tags":["情歌","重章","存疑"]},"shijingf_xiangshu":{"intro":"《鄘风·相鼠》是《诗经》里骂得最狠的一首：看那老鼠还有皮，人却没有威仪；人没有威仪，不死还干什么？它用最日常的动物来对照人，用最直接的话骂人。读它要看三个对象，皮、齿、体，怎样一步步推到“不死何为”。","focus":["三章起句是“相鼠有皮”“相鼠有齿”“相鼠有体”：皮、齿、体，是老鼠的外在、咬合、全身，层层深入。接下来的“人而无仪”“人而无止”“人而无礼”，从仪表，到举止，到礼，由外而内。","每章的结尾是“不死何为”“不死何俟”“胡不遄死”，三种说法都是要他快点死。《诗经》里少有如此直白的詈词，它没有修辞缓冲，也没有委婉，是民间愤怒的直接发泄。","所谓“无仪”“无止”“无礼”究竟指什么，诗里没说，传统认为是讽刺统治者，也可能是对违背礼义的某个具体人物的怒斥，存疑。重要的是，它说明周人把“礼”看作做人的底线：连老鼠都有皮，人却没有，说明连动物都不如。"],"notes":[["相鼠","看那老鼠"],["仪","威仪，仪表"],["止","容止，举止"],["体","身体，一说礼"],["人而无仪","人却没有威仪"],["不死何为","不死去还做什么"],["何俟","还等什么"],["遄","迅速"],["胡不遄死","为什么不快点死"]],"think":["这首诗骂得这么重，为什么仍然被收入《诗经》并长期流传？","因为它体现了周代礼乐文化的一个核心：礼是做人的基本条件。把“无礼”看作比死更不可接受，说明当时的价值观。同时，直接的愤怒也有价值，它保留了民间的声音。今天读，也提醒我们，礼的底线不是形式，而是对他人的尊重。"],"quiz":[["“相鼠有皮”是用来对照什么的？",["人而无仪","老鼠的毛","人的皮肤"],"以老鼠尚有皮，对比人却没有威仪，一个比较的写法。"],["三章“皮、齿、体”的顺序大致是？",["从外在到内在","从大到小","从北到南"],"皮齿体由外到身，对应仪、止、礼的由外向内。"]],"cards":[["《相鼠》的核心手法？","以动物对比人，层层推进，直接诅咒。"],["“人而无仪，不死何为”的意思？","人没有威仪，不死去还有什么用。"]],"line":["人而无仪，不死何为","这是极重的话，现实里不用，但可以让人体会礼在古人心中的分量。"],"tags":["讽刺","礼","直白"]},"shijingf_zaichi":{"intro":"《鄘风·载驰》是一位诸侯夫人在国家危亡时的奔走与辩白。传统认为作者是许穆夫人，卫国被狄人攻破，她想回国吊唁、求援，却被许国大夫阻拦。全诗有行动（载驰载驱）、有争辩（许人尤之）、有宣言（百尔所思，不如我所之）。读它要看一个女子怎样在男性官员群里说自己的话。","focus":["首章“载驰载驱，归唁卫侯”开门见山：策马疾驰，回去吊唁卫侯。“大夫跋涉，我心则忧”写大夫追来阻止，行动一开始就带着冲突。","二、三章是辩论：“既不我嘉，不能旋反”，你们既然不赞成，我无法回头；“视尔不臧，我思不远”，我看你们的主张并不好，我想得不是不远。紧接着“女子善怀，亦各有行”，女子多思虑，也各有道理；“许人尤之，众稚且狂”，许国人责怪我，真是幼稚且狂妄。语气已经毫不客气。","末章“控于大邦，谁因谁极”是实际的筹划：我想向大国求援，可依靠谁、到哪里？接着“大夫君子，无我有尤”，你们这些人不要再责怪我；“百尔所思，不如我所之”，你们想一百次，也不如我亲自去一趟。这是《诗经》中最有气势的一句。"],"notes":[["载驰载驱","边奔跑边驱车"],["唁","吊唁，慰问遭遇丧乱的人"],["漕","卫国的地名"],["跋涉","翻山涉水赶路"],["不臧","不好"],["閟","闭塞，止"],["蝱","贝母，一种药草"],["善怀","善于思虑，多情"],["有行","有自己的道理，一说有去处"],["许人尤之","许国人责怪我"],["控于大邦","向大国求援"],["百尔所思","你们所有的思虑"]],"think":["“百尔所思，不如我所之”这句话为何被视为中国古代女诗人的名句？","因为它在男性官员占主导的话语场里，用最短的话表达了“行动胜于议论”的态度，并以女性之身说出。它也是一个具体情境里的辩白，而非抽象感叹。读它时要注意作者身份：传统认定为许穆夫人，这是对女诗人的早期记录，但具体细节仍有存疑处。"],"quiz":[["“归唁卫侯”的“唁”是什么意思？",["吊唁、慰问遭遇灾难的人","宴请","争吵"],"唁指对遭遇丧乱的人进行慰问或吊唁。"],["“女子善怀，亦各有行”是什么态度？",["为女子的思虑与主张辩护","批评女子","赞美男子"],"“善怀”指多思，“有行”指有自己的道理，是对阻拦者的反驳。"]],"cards":[["《载驰》最著名的一句？","百尔所思，不如我所之，意思是你们想一百次，不如我去一趟。"],["“控于大邦，谁因谁极”是什么意思？","向大国求援，可依靠谁、到哪里去，是实际的筹划。"]],"line":["百尔所思，不如我所之","在会议室讨论了无数方案，不如亲自去客户那里一趟，“百尔所思，不如我所之”。"],"tags":["女诗人","辩白","家国"]},"shijingf_qiyu":{"intro":"《卫风·淇奥》以淇水边的绿竹赞美一位君子，三章用的是同一个提问：这样的人怎样才算好？答案是玉：如切如磋，如琢如磨；如金如锡，如圭如璧。后世用“切磋琢磨”形容修养，用绿竹形容君子，都出自这里。读它要看比喻怎样从自然（竹）到工艺（骨玉）再到品质（金玉）。","focus":["首章“瞻彼淇奥，绿竹猗猗”：看淇水弯处，绿竹茂盛。接着“有匪君子，如切如磋，如琢如磨”：切磋原指加工骨角，琢磨原指加工玉石，合起来说这位君子的修养是反复打磨出来的，不是天生的。","次章写外在：“充耳秀莹，会弁如星”，耳饰是美石，皮帽缝里缀玉如星。再次回到“瑟兮僴兮，赫兮咺兮”，瑟是庄重，僴是威严，赫咺是光明盛大。外表华贵，却不让人只记住华贵，所以最后还要说“终不可谖兮”（终不能忘）。","末章“如金如锡，如圭如璧”把人比作金锡与圭璧：金锡是炼得精纯，圭璧是礼器的贵重。紧接着一句出人意料：“善戏谑兮，不为虐兮”，善于说笑，却不伤人。把一位贵人的形象最后落在幽默分寸上，是整首诗最有人味的一笔。"],"notes":[["淇奥","淇水弯曲之处"],["猗猗","美盛的样子"],["匪","通“斐”，有文采"],["如切如磋","像加工骨角那样反复切磨"],["如琢如磨","像加工玉石那样反复雕琢"],["瑟","庄重矜持"],["僴","威严"],["赫兮咺兮","光明盛大"],["谖","忘记"],["充耳","垂在耳边的玉饰"],["会弁","缀玉的皮帽"],["如箦","像竹席一样密集"],["重较","车厢两侧高出的扶手"]],"think":["“善戏谑兮，不为虐兮”为什么放在赞美一位君子的诗的最后？","因为前面写的外表、威仪、修养都容易让人觉得严肃疏远，而“善戏谑”补上亲和，“不为虐”补上分寸。它说明理想的君子不只是庄重，还要有幽默的人情味，同时知道玩笑的边界。这对领导者尤其适用：有幽默，不刻薄。"],"quiz":[["“如切如磋，如琢如磨”原指什么？",["加工骨角与玉石","耕田与织布","战争与狩猎"],"切磋原指治骨角，琢磨原指治玉石，比喻学问道德的反复修炼。"],["末章最后两句“善戏谑兮，不为虐兮”说明君子？",["幽默而有分寸","严肃冷酷","懒散随便"],"善戏谑是爱说笑，不为虐是不伤人，是亲和而有分寸。"]],"cards":[["“有匪君子，如切如磋”比喻什么？","君子的修养像骨玉加工，是反复打磨的结果。"],["淇奥的绿竹象征什么？","君子挺拔清雅的品质。"]],"line":["如切如磋，如琢如磨","谈到团队里的互相提升，可以用“如切如磋，如琢如磨”，强调长期打磨。"],"tags":["君子","比喻","赞美"]},"shijingf_kaopan":{"intro":"《卫风·考槃》写一位隐者独居山涧：独睡醒来自言自语，发誓不忘此乐。三章换的是地点——涧、阿、陆，对应的是“宽”“薖”“轴”，最后三个誓词“弗谖”“弗过”“弗告”。读它要看一个人的自足怎样一步步升级成不愿与外人说。","focus":["首句“考槃在涧，硕人之宽”写的是地点与心境：山涧边，高人心中宽广。第二章“在阿”，阿是弯曲的丘陵，第三章“在六”，原文作“六”，可通“陆”，高而平的地方。三个地点由低到高，从涧到阿到陆，仿佛隐者越走越高。","每章第三句“独寐寤言”“独寐寤歌”“独寐寤宿”：独自睡醒后，先自言自语，再唱歌，再干脆留宿。一个人，一个动作比一个动作悠闲，是自得其乐的递进。","最后一句“永矢弗谖”“永矢弗过”“永矢弗告”：永远发誓不忘记，不过问（外面的事），不告诉别人。从内心不忘，到不理他人，到不对外说，是隐逸越来越彻底。“考槃”本身是什么，存疑：或指敲击器具，或指建造居所。"],"notes":[["考槃","一说敲击器具作乐，一说建造居所，存疑"],["涧","山间的溪水"],["阿","弯曲的山陵"],["硕人","身材高大的人，这里指隐者"],["宽","心胸宽广，一说舒展"],["薖","宽大自得的样子"],["轴","一说盘桓不去"],["独寐寤言","独自醒来自言自语"],["永矢弗谖","永远发誓不忘"],["弗过","不过问，一说不再经过"],["弗告","不告诉别人"]],"think":["隐士为什么要三次发誓“弗谖”“弗过”“弗告”？这三个誓言的次序有什么逻辑？","从内到外：先是不忘（对自己），再是不再理会（对世界），最后是不告诉（对他人）。隐逸不只是离开，更是逐步切断外部的联系。同时也有一种矛盾：既然誓不告人，诗又是怎样流传下来的？这一点常被读者忽视，也许说明隐者的“不告”并不绝对。"],"quiz":[["“考槃在涧”的“涧”指？",["山间溪流","大海","城墙"],"涧是山间的小溪流，写隐者所居之地。"],["三章最后的“弗谖”“弗过”“弗告”共同表现？",["隐者的自足与不愿被打扰","对君王的怨恨","战争的恐惧"],"都是誓词，内容是不忘、不过问、不告人，表现隐居的自得。"]],"cards":[["“独寐寤言”写什么？","独自睡醒，自言自语，写隐居的自得。"],["三章地点“涧、阿、陆”的变化？","从低到高，仿佛隐者越走越远。"]],"line":["独寐寤言，永矢弗谖","周末关掉手机，一个人待着，“独寐寤言，永矢弗谖”，是对自己的誓言。"],"tags":["隐逸","自得","誓言"]},"shijingf_shuoren":{"intro":"《卫风·硕人》是《诗经》里描写美人最著名的一首：写齐国公主庄姜嫁到卫国。第二章的“手如柔荑，肤如凝脂，领如蝤蛴，齿如瓠犀，螓首蛾眉，巧笑倩兮，美目盼兮”被后世反复引用。读它要看全诗的四层：出身、容貌、入门场面、送亲队伍，容貌只占一层。","focus":["首章写出身：“齐侯之子，卫侯之妻。东宫之妹，邢侯之姨，谭公维私”，一连串的亲属关系，说明她是齐国太子的妹妹，邢侯的姨妹，谭公的姨夫。这是周代贵族婚姻的“族谱式”赞美，先写身份，再写人。","第二章是公认的名段：手、肤、领、齿、首、眉，六个比喻都用静物来写（嫩芽、凝脂、蝤蛴、瓠子的籽、螓的额头、蛾的触须）。最后两句“巧笑倩兮，美目盼兮”换成动态，写笑与眼神，用“倩”“盼”二字让静物般的画像活了过来。前面是形，后面是神。","三、四章写场景：“四牡有骄，朱幩镳镳”写车马之盛，“河水洋洋，北流活活”写水势浩荡，“庶姜孽孽，庶士有朅”写陪嫁的姜姓女子与随从的士，场面铺开。整首诗也说明：《诗经》对美的写法，不只是容貌，而是人、家、礼与风景的整体。"],"notes":[["硕人","身材高大的美人"],["颀","身材修长"],["褧衣","罩在外面的麻纱衣"],["东宫","太子"],["柔荑","柔嫩的白茅芽"],["凝脂","凝固的油脂"],["蝤蛴","天牛的幼虫，白而长"],["瓠犀","瓠瓜的籽，整齐洁白"],["螓首","螓的额头，宽而方"],["蛾眉","蛾的触须，细长弯曲"],["倩","笑得好看"],["盼","眼睛黑白分明"],["镳镳","盛大的样子"]],"think":["为什么“巧笑倩兮，美目盼兮”被认为是点睛之笔？前面的六个比喻有什么不足？","前面六个比喻都是“像某物”，是静态的拼贴，读者可以想到各个部位，却合不成一个活人。“巧笑”“美目”写的是动作和神态，需要人的表情来支撑，因此一下子把画像变成了真人。这也是中国画论“以形写神”的早期例子。"],"quiz":[["“手如柔荑”的“荑”指什么？",["初生的白茅芽","树皮","玉石"],"荑是初生的白茅嫩芽，柔嫩洁白，用来比手指。"],["第二章前六个比喻与最后两句有什么不同？",["前面写形，后面写神态","前面写神态，后面写形","都在写服饰"],"手肤领齿首眉是静态形象，笑与目是动态神情。"]],"cards":[["“巧笑倩兮，美目盼兮”的意思？","笑得好看，眼睛黑白分明，传神。"],["《硕人》的结构？","出身、容貌、入门、送亲队伍四个层次。"]],"line":["巧笑倩兮，美目盼兮","形容一位气质亲和的同事，可以用“巧笑倩兮，美目盼兮”，注意不能用在正式文件里。"],"tags":["美人","比喻","庄姜"]},"shijingf_heguang":{"intro":"《卫风·河广》只有八句，是《诗经》中夸张最大胆的一首：谁说黄河宽？一片芦苇就能渡过；谁说宋国远？踮起脚就能看到。传统认为是宋襄公的母亲（卫女）被出嫁回国后思念宋国，存疑。读它要看夸张怎样反衬思念：越说容易，越说明回不去。","focus":["首章“谁谓河广？一苇杭之”是反问：谁说黄河宽，一束芦苇就能渡过。“谁谓宋远？跂予望之”：谁说宋国远，踮起脚就能望见。这是故意说反话，极度缩小距离，目的是说“我想回去”。","第二章把夸张再推一步：“曾不容刀”，河窄得容不下一艘小船（刀，一说小船）；“曾不崇朝”，宋国近得走不到一个早晨。两章叠句，都是越说越小，越小越显出现实中的阻隔：不是路远，而是回不去。","全诗没有一个字直说思念，但读者能感到一个被阻隔的人在河边踮脚张望。这种以否定距离来写距离的写法，后世王维等人的诗中常见；而此诗是起点，语言极简，感情极重。"],"notes":[["河","黄河"],["一苇杭之","用一束芦苇渡过，杭同“航”"],["宋","宋国"],["跂予望之","踮起脚来望"],["曾不容刀","连一只小船都容不下，一说“刀”为小船"],["崇朝","一个早晨"],["谁谓","谁说"],["杭","渡过"]],"think":["全诗用夸张写“近”，为什么却读出“远”的感觉？","因为读者会本能地问：既然这么近，为什么不去？答案是现实的阻隔，不是地理的距离。诗人说得越轻，阻隔越重。这种反向表达在中文里很常见，如“近在咫尺，远在天涯”，都是用反差制造力量。"],"quiz":[["“一苇杭之”的“杭”通？",["航","行","航海"],"“杭”通“航”，意思是渡过。"],["全诗的核心修辞手法是？",["夸张与反问","排比与对偶","拟人与借代"],"通过反问和夸张，把河说得极窄、国说得极近，以反衬思归之切。"]],"cards":[["“谁谓河广？一苇杭之”的意思？","谁说黄河宽，一束芦苇就能渡过。"],["《河广》说“近”的目的？","夸张地缩短距离，反衬回不去的痛苦。"]],"line":["谁谓河广？一苇杭之","面对看似遥远实则可及的目标，可以用“谁谓河广？一苇杭之”给自己打气。"],"tags":["思归","夸张","反问"]},"shijingf_boxi":{"intro":"《卫风·伯兮》写一位女子思念远征的丈夫。她先夸他英武：朅兮、桀兮、执殳为王前驱；然后转到自己的日常：“自伯之东，首如飞蓬”，头发像乱草。最动人的是“岂无膏沐？谁适为容”，不是没有润发油，而是为谁打扮。读它要看夸与思如何一并写出。","focus":["首章“伯兮朅兮，邦之桀兮。伯也执殳，为王前驱”：她为丈夫骄傲，他是国家的豪杰，手持兵器走在王的前面。这一章没有一句抱怨，只有自豪，所以后文的思念更显得沉重。","二章“自伯之东，首如飞蓬。岂无膏沐？谁适为容！”是全诗的核心：自从你东去，我的头发像飞蓬一样乱，难道没有润发的东西，为谁打扮呢？“谁适为容”是一句反问，既是怨，也是爱：我的容貌，只是给你看的。","三、四章写相思的各种症状：“愿言思伯，甘心首疾”，我心甘情愿头痛；想找一株“谖草”（萱草，传说可以忘忧）种在屋北，却仍然“愿言思伯”，结果是“使我心痗”（心病）。忘忧的草也无用，是全诗最悲的一笔。"],"notes":[["朅","威武的样子"],["桀","杰出的人"],["殳","一种长兵器"],["前驱","在前面开路的先锋"],["首如飞蓬","头发像飞散的蓬草"],["膏沐","润发的油"],["谁适为容","为谁打扮"],["杲杲","明亮的样子"],["愿言思伯","一心思念伯"],["首疾","头痛"],["谖草","萱草，传说可忘忧"],["痗","心病"]],"think":["“岂无膏沐？谁适为容”为什么被认为是女子思念的经典表达？","因为它把思念转化为一个具体行为：不打扮。不打扮既是自我放弃，也是对爱的坚持，因为容貌的意义依赖于有人欣赏。这句话在后世诗词里多次被化用，如“女为悦己者容”的类似意思。也提醒我们，情绪不需要大声说出，细节就足够。"],"quiz":[["“首如飞蓬”形容？",["头发散乱","头发整齐","头发花白"],"飞蓬是随风飘散的草，形容头发散乱，无心梳理。"],["“焉得谖草，言树之背”的含义是？",["想找忘忧草种在屋后，以求忘忧","想种蔬菜","想找药草治病"],"谖草即萱草，传说可以忘忧，她想种在屋北，但仍无济于事。"]],"cards":[["“岂无膏沐，谁适为容”的意思？","不是没有润发油，而是为谁打扮。"],["全诗的情感节奏？","先夸丈夫，再写自己思念，最终忘忧之草也无效，终成心病。"]],"line":["岂无膏沐？谁适为容","连续加班没有心思打理生活，可以自嘲说“岂无膏沐？谁适为容”。"],"tags":["思妇","细节","忘忧"]},"shijingf_mugua":{"intro":"《卫风·木瓜》是投报往来的诗：你送我木瓜，我回你美玉。三章换了三种水果（木瓜、木桃、木李）和三种玉（琼琚、琼瑶、琼九），而结尾一直是同一句：“匪报也，永以为好也！”读它要看回礼为什么远重于来礼，以及这句话怎样给了人情往来一种优雅的说法。","focus":["三章前两句换物不换意：投我以木瓜，报之以琼琚。木瓜、木桃、木李是常见水果，琼琚、琼瑶、琼玖是美玉。以常物换美玉，差距悬殊，而不是等价交换。","最后一句“匪报也，永以为好也”是全诗的意义所在：这不是报答，是希望永远交好。它把回礼提升为表达长期情谊的方式，而不是了结人情债。这样的说法很细致：既让对方没有亏欠感，又让自己的心意明确。","原诗的背景，传统说是卫人感谢齐桓公帮助复国，是否如此，存疑。读它时不必拘泥于此，重要的是它体现的礼：别人给小礼物，我回大礼，同时说明目的不在抵偿，而在结好。"],"notes":[["投","投赠，赠送"],["木瓜","一种水果"],["报","回报，回赠"],["琼琚","美玉，琚是佩玉"],["匪报也","不是为了报答"],["永以为好","永远相好"],["木桃","一种水果"],["琼瑶","美玉"],["木李","一种水果"],["琼九","通“琼玖”，美玉"]],"think":["“匪报也，永以为好也”给了人情往来什么启示？","它提示一个交往原则：回礼的目的不是还账，而是延续关系。如果只想“扯平”，关系到此为止；如果想“永好”，回礼就要超出对等。这也是今天商务关系里“礼尚往来”的分寸：回得要有诚意，同时不能让对方觉得被压迫。"],"quiz":[["“匪报也”的意思是？",["并不是为了报答","不是报纸","不要回报"],"“匪”是“非”，“匪报也”即“不是为了回报”。"],["“投我以木瓜，报之以琼琚”的特点是？",["回礼远重于来礼","回礼与来礼等价","来礼重于回礼"],"木瓜是常见水果，琼琚是美玉，回礼比来礼贵重得多。"]],"cards":[["“匪报也，永以为好也”的意思？","这不是报答，而是希望永远交好。"],["三章里变化的是什么？","水果与玉的名称，结尾不变。"]],"line":["投我以木瓜，报之以琼琚","接受朋友的小帮忙，回礼不要斤斤计较，可以说“投我以木瓜，报之以琼琚”。"],"tags":["礼尚往来","友好","叠句"]},"shijingf_junziyuyi":{"intro":"《王风·君子于役》是《诗经》里最朴素的思夫诗，没有一句抒情的大话，只写黄昏时候的农村：鸡回到窝，牛羊下山，而丈夫仍未回家。读它要看“日之夕矣，羊牛下来”这句景语怎样让思念变得有画面、有声音、有温度。","focus":["开头“君子于役，不知其期。曷至哉”就是一句平白的话：丈夫去服役，不知什么时候回来。问到哪天回得了，没有答案。接着不是抒情，而是景物：“鸡栖于埘。日之夕矣，羊牛下来。”","景物的选择非常精准：鸡进窝、牛羊下山，都是“回”的动作。万物归巢，反衬人不归；这里没有一个“思”字，但“如之何勿思”紧接着出现，水到渠成。这是《诗经》中以景托情、不动声色的典型。","二章把“鸡栖于埘”改为“鸡栖于桀”，“羊牛下来”改为“羊牛下括”，埘是墙洞里的鸡窝，桀是木桩，括是聚集。换字很少，意思不变。末句从“如之何勿思”转为“苟无饥渴”，从思念转到担忧：他在外面，不要挨饿受渴吧。思念落在最实际的关心上。"],"notes":[["君子","这里指丈夫"],["于役","去服役"],["曷至哉","什么时候才能回来"],["埘","墙壁上挖的鸡窝"],["桀","木桩，鸡栖息处"],["日之夕矣","太阳落山的时候"],["下来","从山坡走下来"],["括","聚集，一说至"],["佸","相会，见面"],["苟无饥渴","但愿他不饥不渴"]],"think":["这首诗没有一个“苦”字，为何读起来很哀伤？","因为哀伤藏在对比里：万物按时回家，唯独那个人没有回。把日常的秩序写足，缺席的人就变得格外明显。这种写法几乎不用形容词，靠场景完成情绪，后世陶渊明、王维的田园诗，很大程度继承了它。"],"quiz":[["“鸡栖于埘”中的“埘”是什么？",["墙洞做的鸡窝","鸡的粮食","鸡蛋"],"埘是在墙壁上凿出来的鸡窝。"],["“苟无饥渴”表达的是？",["对丈夫饥渴的担忧","对丈夫的责备","对粮食的渴望"],"在不知道归期的情况下，妻子最挂心的只是他不挨饿受渴。"]],"cards":[["“日之夕矣，羊牛下来”的作用？","以万物归家反衬丈夫不归。"],["“苟无饥渴”表达什么？","对丈夫在外的饮食冷暖的牵挂。"]],"line":["日之夕矣，羊牛下来","傍晚下班路上，看见一路归家的人，可以想起“日之夕矣，羊牛下来”。"],"tags":["思夫","景语","日常"]},"shijingf_yangzhishuiwang":{"intro":"《王风·扬之水》是戍边士兵的怨歌：三章只换“束薪、束楚、束蒲”和“申、甫、许”，其余一字不改，“怀哉怀哉，曷月予还归哉”。读它要看起兴的“扬之水，不流束薪”：连一捆柴都冲不走的水，是缓慢、无力、令人焦灼的。","focus":["起兴“扬之水，不流束薪”：缓缓流淌的水，连一捆柴也漂不走。这个画面可以比喻两种东西：一是自己被困住，哪怕想走也走不了；二是时间的迟缓，日子像这水一样推不动。柴、楚、蒲三种捆束之物，替换而不变意。","“彼其之子，不与我戍申”：他们那些人，不和我一起去戍守申国。这里有怨气：不平等的派遣，使人觉得不公。申、甫、许都是与周王室关系密切的姜姓之国，所以有传统说法认为是周平王时期的情形，存疑。","三章末句不变：“怀哉怀哉，曷月予还归哉”：想啊想啊，哪个月我才能回家。重复本身就是焦灼的表现：每一章都在问，没有一次得到回答。这类“求归期”的诗，是后世征戍诗的母题。"],"notes":[["扬之水","缓缓流动的水，一说激扬之水"],["束薪","一捆柴"],["束楚","一捆荆条"],["束蒲","一捆蒲草"],["彼其之子","那些人"],["戍","驻守边疆"],["申","申国"],["甫","甫国"],["许","许国"],["怀哉怀哉","想念啊想念啊"],["曷月","哪个月"],["还归","回家"]],"think":["“扬之水，不流束薪”为什么能引出戍卒的怨愤？","因为这个画面是“不动”。水尚且推不动一捆柴，人更无法摆脱派遣。读者能体会到一种无能为力的压抑。并且这个“不动”是缓慢的，不是剧烈的，所以怨愤也是日积月累的，不是爆发式的。"],"quiz":[["“不与我戍申”表达士兵的什么情绪？",["对不平等派遣的不满","对申国的向往","对战争的渴望"],"“彼其之子”不和我一起去，暗含派遣不公的怨气。"],["三章变化的是？",["束薪、束楚、束蒲与申、甫、许","全部内容","最后一句"],"每章只换捆束之物与戍守之国，末句不变。"]],"cards":[["“怀哉怀哉，曷月予还归哉”意思？","想家啊想家啊，哪个月才能回去。"],["“扬之水，不流束薪”的象征？","水推不动柴，象征困在原地，无力脱身。"]],"line":["怀哉怀哉，曷月予还归哉","异地项目驻场的人，加班到深夜可以说“怀哉怀哉，曷月予还归哉”。"],"tags":["戍边","叠句","归期"]},"shijingf_zhonggu":{"intro":"《王风·中谷有蓷》写一位被抛弃的女子：山谷中的益母草都枯干了，她与丈夫分离，叹息、长啸、哭泣。三章写情绪由叹到啸再到泣，层层加深，最后“何嗟及矣”，叹也来不及了。读它要看草的枯萎怎样与人的被弃相呼应。","focus":["起兴“中谷有蓷，暵其干矣”：山谷里的益母草被晒干。蓷本来喜欢湿润，现在干枯，象征女子失去了应有的滋养。二章“暵其修矣”，修是枯萎，三章“暵其湿矣”，“湿”字解释不一，存疑，有说是将干未干，也可能是传抄的异文。","“有女仳离”是全篇的主线：女子被离弃。三章的反应分别是慨叹、长啸、啜泣：“慨其叹矣”“条其歗矣”“啜其泣矣”，由内心叹息，到出声号啕，再到抽噎，是一条完整的悲伤弧线。","每章后半句“遇人之艰难矣”“遇人之不淑矣”“何嗟及矣”，把原因从“艰难”推到“不淑”，再到“何嗟及矣”。艰难是处境，不淑是对方人品，最后是反思：叹息也晚了。三句话是一个女子对自己婚姻的分析。"],"notes":[["蓷","益母草"],["暵","干枯"],["仳离","离别，特指妇人被弃"],["慨","叹息"],["修","干枯，一说长"],["歗","长啸，号叫"],["啜","抽泣"],["不淑","不善，不幸"],["何嗟及矣","叹息又哪里来得及"],["艰难","困苦"]],"think":["三章中从“艰难”到“不淑”再到“何嗟及矣”，反映女子怎样的认知过程？","先是把原因归于外部环境（艰难），再是归于对方人品（不淑），最后承认事已至此（何嗟及矣）。这是受伤者常见的心理过程：解释、归因、放下。诗里没有指责，但每一步都在重新理解自己的遭遇。"],"quiz":[["“有女仳离”的“仳离”是？",["别离，特指妇人被弃","结婚","生育"],"“仳离”指妇人离开夫家，多指被丈夫抛弃。"],["三章“慨、歗、泣”的变化说明什么？",["悲伤逐渐加深","悲伤逐渐消除","心情由悲转喜"],"从叹息到长啸到啜泣，情绪由内到外。"]],"cards":[["起兴“中谷有蓷，暵其干矣”象征？","益母草干枯，象征女子失去滋养。"],["“何嗟及矣”意思？","叹息也来不及了，事已无可挽回。"]],"line":["何嗟及矣","事后复盘发现问题早就有苗头，可以叹一句“何嗟及矣”。"],"tags":["弃妇","起兴","情绪层次"]},"shijingf_tuyuan":{"intro":"《王风·兔爰》写一个生逢乱世的人，把自己比作被网住的雉鸡，而兔子却悠闲自在。“我生之初，尚无为；我生之后，逢此百罹。”最后一句是“尚寐无吪”：宁愿睡过去不再醒来。读它要看小人得意、君子遭难的对照怎样写成了乱世的叹息。","focus":["起兴“有兔爰爰，雉离于罗”用两个动物作对照：兔子爰爰，悠然自在；雉鸟落进了网。兔狡而雉耿，兔自由而雉受困，这是诗人对时代的判断：该受难的逍遥，不该受难的被困。","“我生之初，尚无为；我生之后，逢此百罹”是一个人的时间对比：我小时候世界还太平，没有这些事；我长大了，就碰上这百般忧患。三章把“无为”改为“无造”“无庸”，把“百罹”改为“百忧”“百凶”，同一意思，不断增大程度。","末句“尚寐无吪”“尚寐无觉”“尚寐无聪”：宁愿睡着，不动、不觉、不闻。这是一种彻底的退缩，不是反抗，也不是认命，而是想在睡眠中关闭对世界的感知。传统认为这首诗对应周室东迁之后的乱世，存疑。"],"notes":[["爰爰","悠闲自在的样子"],["雉","野鸡"],["罗","捕鸟的网"],["罦","一种捕鸟网"],["罿","一种捕鸟网"],["无为","没有事端，一说没有徭役"],["无造","没有劳作，一说没有造作"],["无庸","没有劳役，一说没有用处"],["百罹","许多忧患"],["尚寐无吪","宁愿睡着不动"],["无觉","不觉醒"],["无聪","不听见"]],"think":["“尚寐无吪”“无觉”“无聪”表达的是怎样的态度？是消极还是无奈？","是极度的无奈，而不是简单的消极。因为诗人已经说明原因：生逢百罹。愿睡不醒，是对现实无力改变的表达。诗中没有说“我要逃避”，而是说“愿我不醒来”。这种语气比愤怒更沉重，也更接近真实的绝望。"],"quiz":[["“有兔爰爰，雉离于罗”形成怎样的对照？",["兔子逍遥，野鸡落网","兔子被捕，野鸡逍遥","两者都被抓住"],"兔爰爰是自在，雉离于罗是被网住，象征小人得意、君子受困。"],["“我生之初，尚无为”表达的意思？",["我出生时还没有这些忧患","我出生时很穷","我出生时家族显赫"],"诗人把“生之初”的平安与“生之后”的忧患对照。"]],"cards":[["《兔爰》的核心对照？","兔的自在对照雉的被困，生之初对照生之后。"],["“尚寐无吪”意思？","宁愿睡着，不要动。"]],"line":["我生之初，尚无为","回想刚入行时一切简单，可以说“我生之初，尚无为”。"],"tags":["乱世","对照","无奈"]},"shijingf_caige":{"intro":"《王风·采葛》只有十八个字有效：采葛，一日不见，如三月；采萧，一日不见，如三秋；采艾，一日不见，如三岁。三个采的对象，三个时间尺度，成就了“一日不见，如三秋”这个成语。读它要看时间怎样被主观拉长，而采集的植物又怎样悄悄递进。","focus":["三章结构完全对称：“彼采X兮，一日不见，如三Y兮”。X是葛、萧、艾，Y是月、秋、岁。时间从三个月，到三个秋（九个月），再到三年，以三倍三倍的方式递增，把一天的分离写成漫长。","葛、萧、艾三种植物各有用处：葛织布、萧作祭祀香草、艾可入药。从衣服，到祭祀，到治病，从生活到信仰到健康，隐约构成人的需要的层次，当然这是读者的联想，原诗并未点明。","这首诗的特点是几乎不写“我”，只写“他”采集的动作和“我”的时间感：一个动作，一个数字，足以让全诗成立。这种极简的写法，使它成为后世表达相思的典范，一日如三秋成了日常语言。"],"notes":[["彼采葛兮","那个人在采葛"],["萧","蒿的一种，可作祭祀"],["艾","艾草，可入药"],["三月","三个月"],["三秋","三个秋季，一说三季"],["三岁","三年"],["一日不见","一天不见"],["如","好像"]],"think":["如果把“如三月、如三秋、如三岁”改成同样的“如三月”，会失去什么？","会失去递进。三章的时间尺度不同，读者的感觉会越来越强烈。这是形式承担内容的例子：重复中有变化，才有力量。同时也提醒：“一日不见，如三秋”是日常中的夸张，而不是精确的计算，诗的真实是情感上的真实。"],"quiz":[["“一日不见，如三秋”最早出自？",["《诗经·王风·采葛》","《论语》","《楚辞》"],"这是《采葛》三章的名句，后成为成语。"],["三章中“月”“秋”“岁”的顺序体现？",["时间尺度逐渐变大","时间尺度逐渐变小","季节循环"],"三月、三秋、三岁，一章比一章长，表达思念愈深。"]],"cards":[["“彼采葛兮，一日不见，如三月兮”的意思？","那个采葛的人，一天不见，就像过了三个月。"],["《采葛》的结构特点？","三章对称，只换植物与时间，递进表达思念。"]],"line":["一日不见，如三秋兮","对远方的朋友说一句“一日不见，如三秋兮”，亲切而有分寸。"],"tags":["相思","时间","递进"]},"shijingf_ziyi":{"intro":"《郑风·缁衣》是一首以衣服为线索的诗：黑色朝服很合身，破了我再为你改做，你到你的馆舍去，回来我再把新衣送给你。全诗没有一句“情”字，只有一件衣服的往来，却把一种慷慨又贴心的关系写得很清楚。读它要看这件衣服怎样变成情谊的载体。","focus":["首章“缁衣之宜兮，敝予又改为兮”：黑色的朝服很适合你，破了我再给你改做。后两章换成“好”与“席”：好是合心，席是宽大舒适，三个形容词依次从合身到喜爱到舒服，是对衣服的评价，也是对人的评价。","“敝予又改为”“改造”“改作”：三个动词，为、造、作，都是做的意思，反复强调“我会为你一直做”。这里没有说“我爱你”，却是一种持续的承诺：衣坏了就改，改坏了就做。","“适子之馆兮，还予授子之粲兮”：你到馆舍去，回来我送你新衣。“粲”说法不一，有说是新衣，有说是饭食，存疑。传统说是郑人赞美郑武公好贤，也有读作妻子送丈夫、主人款待客人，诗里没有明说，可以保持开放。"],"notes":[["缁衣","黑色的衣服，一说朝服"],["宜","合适"],["敝","破旧"],["改为","改做，重新做"],["好","合意"],["席","宽大舒适，一说安适"],["适","去，往"],["馆","馆舍，客舍"],["授","给予"],["粲","新衣，一说饭食，存疑"]],"think":["全诗只写衣服，没有一句情话，为什么仍被认为是情意深厚的诗？","因为照顾的细节比情话更可信：量体、改衣、再做新衣，每一步都是需要时间和心力的事。同时“又”字隐含重复：不只是一次。这是用持续的行为证明关心，比用语言宣布更有说服力。读后可以想起，今天职场里能被长期信任的，也往往是这种“默默改衣”的人。"],"quiz":[["“缁衣”指什么？",["黑色的衣服","白色的衣服","红色的衣服"],"缁是黑色，缁衣是黑色朝服或常服。"],["“敝予又改为兮”中“又”字的作用？",["强调反复为对方做衣","表示新旧","表示颜色"],"“又”字表示不止一次，体现长期的关心。"]],"cards":[["“缁衣之宜兮”的意思？","黑色的衣服很合适。"],["三章里“改为、改造、改作”的共同点？","都是为你重做的意思，强调反复。"]],"line":["缁衣之宜兮，敝予又改为兮","同事的工作总是有人帮忙兜底，可以说是“缁衣之宜兮，敝予又改为兮”。"],"tags":["衣","情谊","细节"]},"shijingf_jiangzhongzi":{"intro":"《郑风·将仲子》是一个女子对情人的劝阻：请你不要翻我的里墙，不要折我的杞树，不是舍不得树，而是怕父母。三章里，怕的对象逐章扩大：父母、诸兄、人之多言。读它要看“仲可怀也”与“亦可畏也”两句并列，怎样把爱与怕写在同一个句子里。","focus":["开头“将仲子兮”是一句请求：将是请，仲子是男子排行的称呼。“无逾我里，无折我树杞”：别翻我的里门，别折我的杞树。杞、桑、檀三种树依次出现，是被折的对象，同时也构成越来越深入的空间：里、墙、园，从外到内一步步逼近。","“岂敢爱之？畏我父母”：我哪里是舍不得树，是怕父母。这句话把表面的拒绝转成真实的恐惧，也泄露她心里的在乎。接着“仲可怀也，父母之言亦可畏也”：你值得我思念，但父母的话也值得怕。“可怀”与“可畏”并列，是她内心的两股力量。","三章怕的对象依次是父母、诸兄、人之多言，由近到远，由亲人到舆论。最后“人之多言亦可畏也”，是最真实的：真正的压力，常常不是家人，而是外人的议论。这一点在今天仍然成立。"],"notes":[["将","请，请求"],["仲子","排行第二的男子"],["逾","翻越"],["里","里门，乡里"],["杞","杞柳"],["爱","吝惜"],["可怀","值得思念"],["可畏","值得畏惧"],["诸兄","哥哥们"],["园","菜园，园圃"],["檀","檀树"],["多言","流言蜚语"]],"think":["三章“畏我父母”“畏我诸兄”“畏人之多言”，为什么越来越远？这反映了怎样的恐惧？","说明这个女子最怕的不是亲人的责罚，而是社会的议论。亲人是熟悉的，他们的反应可预测；而“人之多言”不可控，也没有边界。顺序上最后才说，是因为它最难对付。这种对舆论的恐惧，在任何社会都有，尤其对女性。"],"quiz":[["“岂敢爱之”的“爱”是什么意思？",["吝惜","喜爱","爱情"],"“爱”在这里是吝惜、舍不得，意思是不是舍不得树。"],["三章“里、墙、园”的变化是？",["由外到内逐步逼近","由大到小","由低到高"],"里是外围，墙是边界，园是内庭，一步步靠近她的住所。"]],"cards":[["“仲可怀也，父母之言亦可畏也”意思？","你值得我思念，但父母的话也让我害怕。"],["《将仲子》里最让她害怕的是什么？","人之多言，即外界的闲话。"]],"line":["仲可怀也，人之多言亦可畏也","在公司内部恋情或敏感话题上，可以体会“人之多言亦可畏也”。"],"tags":["情诗","矛盾","舆论"]},"shijingf_nvyuejiming":{"intro":"《郑风·女曰鸡鸣》是一对夫妻清晨的对话：妻子说鸡叫了，丈夫说天刚亮，妻子说起来看看夜色，明星已经灿烂；于是计划去射猎，打下的野鸭和雁，用来做菜，一起喝酒，一起到老。末章男子赠杂佩，表示感激。读它要看对话怎样把爱情写成日常的生活安排。","focus":["首章是一问一答：“女曰鸡鸣，士曰昧旦”。妻子催，丈夫赖床，这是任何一个家庭清晨的场景。接着“子兴视夜，明星有烂”，妻子叫他起来看天，星星还很亮。写得干净、有画面。","二章“弋言加之，与子宜之。宜言饮酒，与子偕老。琴瑟在御，莫不静好”：射中了，我为你烹调，边喝酒边说白头到老。“莫不静好”四个字写出一切都安稳。这里把爱情落在日常的打猎、做饭、喝酒与弹琴，是《诗经》里最温馨的家庭图景。","末章“知子之来之，杂佩以赠之”，说话者换成了丈夫：知道你来了，用杂佩相赠；知道你和顺，用杂佩相问；知道你爱我，用杂佩相报。三个“知子之”，每次换一个动词，层层递进。这是一首让双方都有声音的诗。"],"notes":[["昧旦","天将亮未亮"],["子兴视夜","你起来看看夜色"],["明星有烂","星星灿烂"],["将翱将翔","将要出去飞翔，指出去射猎"],["弋","射猎"],["凫","野鸭"],["宜之","烹调食物"],["偕老","白头到老"],["琴瑟在御","琴瑟在身边弹奏"],["静好","安宁美好"],["杂佩","各种佩玉"]],"think":["“琴瑟在御，莫不静好”被后世常用来祝福婚姻，放回诗里是什么场景？","是一个打猎归来、烹食饮酒、间有琴瑟的家居场景，并不是想象中的“相敬如宾”。可见“静好”最初指的是日常生活的安稳，不是一种静止的理想。引用时可以保留这个生活感，更贴近本意。"],"quiz":[["“昧旦”的意思是？",["天将亮的时候","傍晚","深夜"],"“昧旦”指天将亮未亮，是清晨的时间。"],["末章三个“知子之”的作用是？",["丈夫表达感谢的层层递进","描写打猎","表示怀疑"],"丈夫一连用三次“知子之”，说明他知道妻子的来、顺、好，所以以杂佩回报。"]],"cards":[["“与子偕老”的语境？","打猎归来烹饪饮酒时对妻子的承诺。"],["《女曰鸡鸣》的特别之处？","对话体，写夫妻日常，双方都有声音。"]],"line":["琴瑟在御，莫不静好","祝福新婚夫妇可以写“琴瑟在御，莫不静好”。"],"tags":["夫妻","对话","日常"]},"shijingf_younvtongche":{"intro":"《郑风·有女同车》写与一位同车女子的相遇：她的脸像木槿花，走路时佩玉叮当响，名叫孟姜，不只美，还“德音不忘”。两章只换了几个字：舜华变舜英，琼琚变将将，“洵美且都”变“德音不忘”。读它要看赞美怎样从外形升到声名。","focus":["首章“有女同车，颜如舜华”：舜华是木槿花，朝开暮落，美而短暂。“将翱将翔，佩玉琼琚”写她行走时玉佩作响。“彼美孟姜，洵美且都”是总评：确实美且闲雅。“都”是闲雅得体，不只是好看。","二章“有女同行，颜如舜英”，同车换成了同行，华换成英；“佩玉将将”，把玉的质地换成玉的声音。最后一句从“洵美且都”换成“德音不忘”，美从可见的转到可闻的、可记的：她的言语声名值得记住。","传统说这首诗是讽刺郑国太子忽不娶齐女而失去大国之援，存疑。读诗本身，只有对一位同车女子的赞美，没有任何政治暗示。有学者把二者分开读，这也是读《诗经》的一种态度：先读诗，再看解释。"],"notes":[["同车","同乘一辆车"],["舜华","木槿花，一说舜是木槿"],["将翱将翔","行走轻盈如飞"],["琼琚","美玉制成的佩饰"],["孟姜","姜姓长女，美女的代称"],["洵美","确实美"],["且都","而且闲雅"],["舜英","木槿花"],["将将","玉佩相碰的声音"],["德音","美好的声誉"]],"think":["赞美的重点由“洵美且都”变到“德音不忘”，说明周人怎样看美？","说明美不只是容貌，也包括言语与声誉。颜如舜华的美只存在于视线里，而“德音不忘”才是长期的。把后者放在末尾，是把美的价值放在持久性上。这与前面《硕人》的“巧笑倩兮”相比，是另一种赞美维度：不是传神，而是传名。"],"quiz":[["“颜如舜华”的“舜华”是什么？",["木槿花","桃花","荷花"],"舜华即木槿花，朝开暮落，用来形容容颜。"],["第二章为何由“佩玉琼琚”变成“佩玉将将”？",["由写玉的质地转为写玉的声音","换了一块玉","玉碎了"],"“将将”是玉佩相碰的声音，由视觉转为听觉。"]],"cards":[["“颜如舜华”什么意思？","容颜像木槿花一样美丽。"],["“德音不忘”表达什么？","她美好的声誉让人难忘。"]],"line":["彼美孟姜，德音不忘","夸一位表达得体的同事，可以说“德音不忘”。"],"tags":["赞美","美人","叠字"]},"shijingf_shanyoufusu":{"intro":"《郑风·山有扶苏》是一首打情骂俏的诗：山上有扶苏，洼地有荷花；我要找的是子都那样的美男，却碰上你这个狂徒。第二章换成“乔松”“游龙”“子充”“狡童”，同一个结构。读它要看反话怎样表达亲昵：骂得越凶，越说明有情。","focus":["起兴先写自然的美好：山上有扶苏，洼地有荷花，各得其所。山上与洼地、乔木与草本，是各有位置的搭配。接着“不见子都，乃见狂且”：没碰到美男子，偏偏遇上这个浑小子。前后形成反差：本来该是美好的搭配，却遇到了对不上的人。","二章“山有乔松，隰有游龙”，换了另一对山与洼地的植物，“子充”替换“子都”，“狡童”替换“狂且”。子都、子充都是当时的美男，狂且、狡童是对情人的昵称式骂法。诗里的“骂”其实是撒娇。","这样的读法不是唯一的：传统说是讽刺所用非人，存疑。但从语气看，“乃见狂且”这类口吻更像爱人间的戏谑。后世《西厢记》中的“冤家”称呼，也有同样的反话传统。"],"notes":[["扶苏","小树，一说桑树，存疑"],["隰","低湿的地方"],["荷华","荷花"],["子都","古代的美男子"],["狂且","轻狂的人，一说“且”为语助"],["乔松","高大的松树"],["游龙","红蓼，一种水草"],["子充","古代的美男子"],["狡童","调皮的少年，对情人的昵称"]],"think":["为什么说这首诗的“骂”其实是爱的表达？","因为骂的对象是“本来想要见到的人”，女子说：我盼着美男子，却见到你这个狂徒。这样的语气里有失望，也有亲近，更有撒娇。若是真正厌恶，就不会写。在民间歌谣中，这类“反语”很常见，是以退为进的表达。"],"quiz":[["“不见子都，乃见狂且”说明？",["本想见美男，却遇到了狂徒，是戏谑的口吻","女子讨厌男子","男子嘲笑女子"],"子都是美男代称，说“乃见狂且”是撒娇式的反话。"],["“狡童”在诗里是怎样的称呼？",["昵称式的骂法","严厉的斥责","官职"],"狡童是调皮少年的意思，用在情人身上带着亲昵。"]],"cards":[["《山有扶苏》的结构？","先写山隰植物起兴，再以“不见……乃见……”表达反差。"],["“狂且”“狡童”的语气？","半骂半爱的昵称。"]],"line":["不见子都，乃见狂且","团队聚餐，等来的不是预期的大咖，而是一个捣蛋鬼，可以半开玩笑说“不见子都，乃见狂且”。"],"tags":["戏谑","反话","情诗"]},"shijingf_jiaotong":{"intro":"《郑风·狡童》只有两章：那个调皮的人，不和我说话，因为你的缘故，我吃不下饭；不和我一起吃饭，因为你的缘故，我睡不安稳。这是《诗经》里最像今天的恋爱闹别扭。读它要看“不与我言”“不与我食”这两个冷战动作，和“不能餐”“不能息”两个身体反应。","focus":["“彼狡童兮，不与我言兮”：那个小冤家，不跟我说话了。狡童，是调皮、狡猾的少年，在这里是爱称。一句话就交代了事件：冷战。","“维子之故，使我不能餐兮”是情绪的落点：因为你，我吃不下饭。第二章换成“不与我食”“不能息”，食是共食，息是安眠。从不说话，到不一起吃饭，再到睡不着，冷战的范围在扩大，影响也从胃到睡眠。","诗里没有责怪，也没有解释。女子既不去追问原因，也不撒狠话，只是如实地说自己吃不下睡不着。这种直接的表达，使它成为民间情歌的范本。传统说是讽刺郑昭公，存疑，实际并无可靠依据。"],"notes":[["彼","那个"],["狡童","调皮的少年，对情人的昵称"],["不与我言","不跟我说话"],["维子之故","因为你的缘故"],["使我","让我"],["不能餐","吃不下饭"],["不与我食","不跟我一起吃饭"],["不能息","不能安眠"]],"think":["这首诗用“吃不下”“睡不着”写爱，与现代人形容恋爱的方式有何异同？","相同的是都依赖身体反应：食欲、睡眠；不同的是现代人更多用“想你”“心疼”这样的情感词，而这首诗只写事实。这种克制，反而使情绪显得真实。可以说古人用身体写感情，今人更爱直接说情绪。"],"quiz":[["“不与我食”的“食”主要指？",["一起吃饭","送礼","买东西"],"“食”是共餐，说明他不肯和她同桌。"],["“不能息”是什么意思？",["睡不安稳","不能呼吸","不能休息工作"],"息是安息，睡眠，说明她夜里也睡不安。"]],"cards":[["“维子之故，使我不能餐兮”的意思？","因为你，我吃不下饭。"],["两章中“言”“食”的变化？","从不说话到不同食，冷战扩大。"]],"line":["维子之故，使我不能餐兮","项目没批下来，吃不下饭，可以半开玩笑说“维子之故，使我不能餐兮”。"],"tags":["恋爱","冷战","身体反应"]},"shijingf_qianchang":{"intro":"《郑风·褰裳》是女子对情人的挑逗：你要是想我，就提起衣裳涉溱水来；你要是不想我，难道没有别的人？末尾“狂童之狂也且”，说你这个傻小子。读它要看这位女子的泼辣，以及一句“岂无他人”如何带着激将。","focus":["开头“子惠思我，褰裳涉溱”：你如果爱我想我，就提起衣裳趟过溱水。“褰”是提起，写出一个具体动作：为了见我，愿意蹚水。她提出的是一个简单的条件，也是一个考验。","接着的反问“子不我思，岂无他人”是激将：你不想我，难道我就找不到别人？第二章换成“涉洧”“他士”，士是男子，说得更明白。这样的话需要底气：她知道自己有选择。","“狂童之狂也且”是结尾的昵骂，与《山有扶苏》的“狂且”“狡童”同类。整首诗里没有一句温情话，却满是亲近：她不愿等，也不愿求，而是用调侃让对方采取行动。这是《郑风》女子形象的特点：主动，直率，有分寸。"],"notes":[["子惠思我","你如果爱我思念我"],["褰裳","提起下裳"],["溱","溱水"],["洧","洧水"],["子不我思","你不思念我"],["岂无他人","难道没有别人"],["他士","别的男子"],["狂童","轻狂的小子"],["也且","语气词，感叹"]],"think":["“子不我思，岂无他人”是威胁，还是玩笑？怎样判断？","语气上更像玩笑加激将。如果是真决绝，后面不会有“狂童之狂也且”这样亲昵的骂。这里的“岂无他人”是给自己壮胆，也给对方施压。另一种可能是她确实有选择，所以在爱情中保持独立。两种读法并存，核心是女子不卑不亢。"],"quiz":[["“褰裳涉溱”描写的是？",["提起衣裳涉水过河","穿上新衣","洗衣服"],"褰是提起，褰裳即提衣，涉溱是蹚过溱水。"],["“岂无他人”的作用是？",["激将与表达自信","诅咒","询问"],"这句话既是玩笑，也是激将，说明女子有自己的选择。"]],"cards":[["“子惠思我，褰裳涉溱”的意思？","你要是爱我想我，就提起衣裳趟过溱水来找我。"],["《褰裳》的女子形象？","直率、泼辣、有底气。"]],"line":["子不我思，岂无他人","在谈判桌上，对方迟迟不表态，可以半开玩笑说“子不我思，岂无他人”。"],"tags":["情诗","主动","激将"]},"shijingf_fengyu":{"intro":"《郑风·风雨》写的是风雨之夜与所爱之人突然重逢。三章都是同一个场景：风雨凄凄，鸡鸣喈喈，见到了君子，心里的忧愁一下子平了。变化的只是描写风雨的词、鸡鸣的词，以及“夷”“瘳”“喜”三个递进的情绪。读它要看恶劣的天气怎样反衬重逢的喜悦。","focus":["首章“风雨凄凄，鸡鸣喈喈，既见君子。云胡不夷”：风雨凄冷，鸡鸣声声，见了你，心怎么能不平静呢。“夷”是平和，是焦虑消解。这个“云胡不……”是反问，意思是怎么可能不……","二章“风雨潇潇，鸡鸣胶胶”，改写雨声和鸡声，“云胡不瘳”，瘳是病愈。思念像一场病，见面就是痊愈。三章“风雨如晦，鸡鸣不已”，天黑如晦，鸡鸣不止，“云胡不喜”：最后一个字落在喜，从平静，到痊愈，到狂喜，情绪是三级递升。","后世“风雨如晦，鸡鸣不已”被用来形容乱世中不改变的节操，意义已不同。就原诗而言，是一首喜悦的诗：风雨是背景，鸡鸣是天将明的信号，见到所爱的人，一切都值得。"],"notes":[["凄凄","寒凉的样子"],["喈喈","鸡鸣声"],["既见君子","已经见到了心上人"],["云胡不夷","怎么能不平静"],["潇潇","风雨急骤的样子"],["胶胶","鸡鸣声"],["瘳","病愈"],["如晦","像夜晚一样昏暗"],["鸡鸣不已","鸡叫个不停"],["云胡不喜","怎么能不高兴"]],"think":["“风雨如晦，鸡鸣不已”后来为何被赋予了节操的意义？","因为在黑暗中仍然鸡鸣，被理解为坚持。这是后世对词句的再解读：原诗说的是喜悦，后世看中的是“风雨中仍不改变”。这个演变本身值得注意：一句诗的意义，会随着使用的场合而改变。引用时要知道原意，也可以保留后来的用法。"],"quiz":[["“云胡不夷”的“夷”是什么意思？",["平静","夷人","夷平"],"夷在这里是心里平静、不再忧愁。"],["三章中“夷”“瘳”“喜”的顺序体现？",["情绪由平静到痊愈到喜悦","情绪越来越悲伤","情绪保持不变"],"夷、瘳、喜是递进的，从心安到病愈到欢喜。"]],"cards":[["“风雨如晦，鸡鸣不已”的原意？","风雨天昏暗，鸡鸣不止，衬托重逢的喜悦。"],["后世引申？","比喻环境恶劣中仍不改变节操。"]],"line":["风雨如晦，鸡鸣不已","在逆境里，团队仍在坚持，可以说“风雨如晦，鸡鸣不已”。"],"tags":["重逢","风雨","引申"]},"shijingf_zijin":{"intro":"《郑风·子衿》是一首女子等待情人的诗，被后世引用最多的是第一章的“青青子衿，悠悠我心”，以及末章“一日不见，如三月兮”。读它要看她怎样责怪对方“纵我不往，子宁不嗣音”：即使我不去，你就不能来个信吗。这是一首带着埋怨的相思。","focus":["首章“青青子衿，悠悠我心”：衿是衣领，青青是颜色，悠悠是心思绵长。她看着那个人的衣领，心思却绵延不断。接着是埋怨：“纵我不往，子宁不嗣音？”就算我没有去找你，你为什么不寄来一个音信？","二章“青青子佩，悠悠我思”，由领子变成玉佩，由“嗣音”变成“来”，她的期待由寄信升级为亲自来。每一章，她对对方的要求都提高一点：先要音信，再要人。","末章换了场景：“挑兮达兮，在城阙兮”，在城楼上往来徘徊。“一日不见，如三月兮”是全诗最熟的一句，与《采葛》相似。后来曹操《短歌行》引用“青青子衿，悠悠我心”，把原来的相思转为对贤才的渴望，是一种意义的迁移。"],"notes":[["青青","颜色青，一说茂盛"],["子衿","你的衣领"],["悠悠","忧思绵长的样子"],["纵我不往","即使我不去找你"],["子宁不嗣音","你难道不寄来音信"],["嗣音","寄音信，一说继续音信"],["子佩","你的佩玉"],["挑兮达兮","来回走动的样子"],["城阙","城门两边的楼"],["一日不见","一天不见"]],"think":["曹操《短歌行》里引用“青青子衿，悠悠我心”，把相思转为求贤，这种用法恰当吗？","从修辞上，是借用，不是误解：句子的情感是“我心中悠悠，等待对方”，用于求贤同样成立。但要知道，原诗是女子责怪情人的诗。引用的用意是借旧句写新情。这类“断章取义”在古代是常见的诗学传统，也是诗句生命力的体现。"],"quiz":[["“纵我不往，子宁不嗣音”的意思？",["即使我不去，你难道不能寄个音信","我不去，你也别来","我已经去过了"],"嗣音即寄音信，这是责怪对方连信也不来。"],["三章期待的变化是？",["从音信到人再到焦急的徘徊","从人到音信","从喜悦到悲伤"],"由“嗣音”到“来”，再到“在城阙”的往来徘徊，期待逐渐升级。"]],"cards":[["“青青子衿，悠悠我心”原本写的是什么？","女子对所爱之人的思念。"],["“一日不见，如三月兮”的意思？","一天不见，像过了三个月。"]],"line":["青青子衿，悠悠我心","招聘人才的时候，用“青青子衿，悠悠我心”表达对好人才的渴望。"],"tags":["相思","埋怨","引用"]},"shijingf_chuqidongmen":{"intro":"《郑风·出其东门》写一个男子走出东门，满眼都是女子，多得像云，像茅花，但“匪我思存”：不是我思念的人。他心里想的，是那个穿着白绢衣、灰绿巾的素朴女子。读它要看一个“专一”的宣言怎样放在众美环绕的背景里。","focus":["开头“出其东门，有女如云。虽则如云，匪我思存”：东门外女子如云，虽然多，都不是我所思念的。“云”是比喻，既言多，也言飘忽，像云一样不可抓。接着“缟衣綦巾，聊乐我员”：只有穿白衣、佩灰绿巾的那位，才让我快乐。","二章“出其闉阇，有女如荼”，闉阇是城门外曲城的门，荼是茅花，白而盛。又一次是众多，却也是“匪我思且”。后一句“缟衣茹藘，聊可与娱”，缟衣配茜草染红的蔽膝，看起来同样朴素，是妻子的形象。","这首诗是《诗经》里关于专一的最有名的表达之一。它不是靠指责别人，而是靠“我的目光不在她们身上”。这是一种不张扬的忠诚：不批评，不炫耀，只是平静地说，谁都不是我所想的。"],"notes":[["东门","城的东门"],["如云","像云一样多"],["匪我思存","不是我所思念的"],["缟衣","白色的绢衣"],["綦巾","灰绿色的佩巾"],["聊乐我员","聊可使我快乐，员为语助"],["闉阇","城门外的曲城门"],["如荼","像茅花一样多而白"],["茹藘","茜草，可染红"],["聊可与娱","聊可与她共乐"]],"think":["“虽则如云，匪我思存”为什么比直接说“我只爱你”更有力？","因为它先摆出诱惑，再否定诱惑。读者能看到他的选择，不只是听到他的宣言。这是“展示”胜过“告诉”的写法。同时，“缟衣綦巾”的朴素，也表明他在意的不是外在的华丽，而是一个人的真实。"],"quiz":[["“有女如云”的“如云”形容？",["数量众多","颜色白","飘忽不定"],"如云指女子众多，如云般聚集。"],["“缟衣綦巾”代表怎样的女子？",["衣着朴素的妻子","贵族小姐","舞女"],"缟衣是白绢衣，綦巾是灰绿佩巾，质朴却令他中意。"]],"cards":[["“虽则如云，匪我思存”的意思？","虽然女子多得像云，却都不是我所思念的人。"],["这首诗表达什么？","专一，不为外界美色所动。"]],"line":["出其东门，有女如云","面对众多合作机会，可以说“出其东门，有女如云”，再补一句“匪我思存”，表达只想做自己认定的事。"],"tags":["专一","对比","东门"]},"shijingf_yeyoumancao":{"intro":"《郑风·野有蔓草》写的是一场偶然的邂逅：野外蔓草上露水圆圆，有位美丽的人，眉目清扬。“邂逅相遇，适我愿兮”：偶然遇见，正合我的心意。读它要看一个不期而遇怎样被写成喜悦，以及“零露”这个起兴的画面。","focus":["起兴“野有蔓草，零露漙兮”：荒野上蔓草蔓延，露水凝成圆珠。这是清晨的画面，清新、湿润，也是一种带着新鲜感的开端。第二章换为“零露瀼瀼”，露水更多，场景更丰盛。","“有美一人，清扬婉兮”：有一位美丽的人，眉目清秀。“清扬”指眉目间的光彩，“婉”是柔美。第二章换成“婉如清扬”，词序倒过来，意思不变，这是《诗经》常见的变化。","最后“邂逅相遇，适我愿兮”与“与子偕臧”，邂逅是没有预约的相遇。偶然的相遇，正合心愿，于是“与子偕臧”：和你一同好。这里没有媒妁，没有礼节，只有两个人遇上。这首诗是《郑风》里最轻盈的一首。"],"notes":[["蔓草","蔓延的草"],["零露","落下的露水"],["漙","露水多而圆"],["清扬","眉目清秀"],["婉","柔美"],["邂逅","不期而遇"],["适我愿兮","正合我的心愿"],["瀼瀼","露水多的样子"],["偕臧","一起好，偕同为善"]],"think":["“邂逅相遇”为什么比“约会相遇”更被人看重？","因为偶然相遇带着“天意”的色彩，也消去了安排与计算。读者感到的是无意中的美好。同时，诗里没有后续，没有结局，使这种美好停在瞬间。这是民歌常见的做法：只截取最亮的时刻，不写后事。"],"quiz":[["“零露漙兮”写的是？",["露水凝成圆珠","大雨","冰雪"],"“零”是落，“漙”是露珠圆而多。"],["“邂逅相遇，适我愿兮”的意思？",["不期而遇，正合我的心愿","约好相遇，不合我愿","遇到仇人"],"邂逅是偶然相遇，适我愿就是称心如意。"]],"cards":[["“野有蔓草，零露漙兮”的作用？","起兴，用清晨的露水写出清新的相遇场景。"],["“邂逅”是什么？","不期而遇。"]],"line":["邂逅相遇，适我愿兮","参加行业会议，遇到一个投缘的伙伴，可以说“邂逅相遇，适我愿兮”。"],"tags":["邂逅","露水","清新"]},"shijingf_zhenwei":{"intro":"《郑风·溱洧》写郑国春天的水边游乐：冰雪融化，溱水洧水涨起来，男女手持兰草，互相问：去看看吗？答：去过了；再去看看吧。洧水外面实在宽广快乐，彼此说笑，赠送芍药。读它要看一个节日的场景怎样被几个动作和一句对话写活。","focus":["首章“溱与洧，方涣涣兮。士与女，方秉蕳兮”：溱水洧水春水涣涣，男女都拿着蕳草（兰草）。涣涣是水盛，蕳是香草，传统说是三月上巳节祓禊（水边祈福除灾）的风俗，具体仪式，存疑。","“女曰观乎？士曰既且。且往观乎”是对话：女孩问，要去看看吗？男孩答，已经去过了。女孩说：再去看看吧。这是一个邀请，也是一个借口：去过了，但还想与你再去一次。全诗最生动的地方就在这里。","“洵訏且乐”写洧水之外开阔而热闹，“伊其相谑，赠之以勺药”写男女说笑，赠以芍药。勺药是定情之物，而“相谑”是玩笑，“将谑”是还在玩笑，不严肃，也不拘谨。读者感到的是节日里人与人之间自然的亲近。"],"notes":[["溱","溱水"],["洧","洧水"],["涣涣","水势盛大的样子"],["秉蕳","手持兰草"],["既且","已经去过了，且通“徂”"],["洵訏","确实宽阔"],["相谑","互相开玩笑"],["勺药","芍药，赠送表示情意"],["浏","水清澈"],["殷其盈矣","人很多的样子"],["将谑","玩笑"],["观乎","去看看吗"]],"think":["“士曰既且。且往观乎”这个细节说明了什么？","说明女子的邀请是借口：已经去过，还要再去，目的不在看，而在同行。这是一个很生活化的细节，把含蓄的心意藏在一句看似普通的话里。读诗时，这类“话里有话”的地方，往往最有价值。"],"quiz":[["“勺药”在这里的作用是？",["赠送表情意","食用","治病"],"勺药（芍药）是赠送给异性表达情意的花。"],["“既且”是？",["已经去过了","就要去","不想去"],"“且”通“徂”，是去的意思，“既且”即已经去过。"]],"cards":[["《溱洧》的场景？","春天溱洧水边，男女持兰草游玩，互赠芍药。"],["“女曰观乎”后面的反转？","男孩说去过了，女孩说再去看看，是借口同行。"]],"line":["赠之以勺药","给合作伙伴送一份小礼物，可以引“赠之以勺药”，既是风雅也是情义。"],"tags":["节日","邀约","民俗"]},"shijingf_jiming":{"intro":"《齐风·鸡鸣》是一场清晨的拉扯：一个人说鸡叫了，朝堂上人都到齐了；另一个人说，那不是鸡叫，是苍蝇的声音。一个人说东方亮了；另一个人说，不是东方亮，是月光。读它要看一问一答之间，一个人怎样用谎话争取多睡一会儿。","focus":["全诗是对话体，没有标明说话人。首章“鸡既鸣矣，朝既盈矣”是催促方，“匪鸡则鸣，苍蝇之声”是回答方。次章“东方明矣，朝既昌矣”再催，“匪东方则明，月出之光”再答。两人每次都只回一句，快速而紧凑。","回答方的借口，逐渐荒诞：把鸡鸣说成苍蝇声，把晨光说成月光。其实他（她）们都知道是什么，只是借口越荒诞，越显出不想起身的情态。这是《诗经》中少有的幽默。","末章“虫飞薨薨，甘与子同梦”，是回答方的真话：虫子飞舞嗡嗡，我愿与你同眠。随后“会且归矣，无庶予子憎”：朝会就要散了，别让别人因为我而憎恨你。传统认为是贤妃催国君早起，或是夫妻之间，存疑。无论如何，诗里的人是温柔的，也是任性的。"],"notes":[["鸡既鸣矣","鸡已经叫了"],["朝既盈矣","朝堂已经人满了"],["匪鸡则鸣","不是鸡在叫"],["苍蝇之声","苍蝇的声音"],["昌","盛，指朝臣多"],["月出之光","月亮的光"],["薨薨","虫群飞舞的声音"],["甘与子同梦","愿意与你同梦"],["会且归矣","朝会快散了"],["无庶予子憎","别让人因我而憎恨你"]],"think":["这首诗中，说话人是夫妻还是君臣，对理解有什么影响？","如果是君臣，诗是写君王好睡、妃子催促；如果是夫妻，诗是写寻常人家的赖床。前一种读法带有政治讽谏色彩，后一种更接近生活。没有证据能确定哪一种，因此不必强求。可以两层并读，体会同一个对话在不同身份里的趣味。"],"quiz":[["“匪鸡则鸣，苍蝇之声”的意思？",["不是鸡在叫，是苍蝇的声音","不是鸡，是狗","不是鸡鸣，是鸟鸣"],"回答方用苍蝇声来否认鸡鸣，是赖床的借口。"],["末章“甘与子同梦”表达什么？",["愿意与对方同眠","不愿意与对方同眠","害怕做梦"],"这句话是回答方的真心话：愿与你共眠。"]],"cards":[["《鸡鸣》的体裁特点？","对话体，一催一拖，充满幽默。"],["“匪东方则明，月出之光”说明什么？","把晨光说成月光，是赖床的借口。"]],"line":["匪鸡则鸣，苍蝇之声","周一早上闹钟响起，可以说“匪鸡则鸣，苍蝇之声”，假装没听见。"],"tags":["对话","幽默","赖床"]},"shijingf_huan":{"intro":"《齐风·还》写两个猎人在山路上相遇，并肩追逐野兽，互相夸奖。三章都是“子之X兮，遭我乎狃之Y兮”：你真敏捷，在峱山中遇到我；你真健壮，在峱山路上；你真好，在峱山南。这是一首男子之间的赞美诗，没有情，只有英气。读它要看互夸的口吻怎样写出齐地的尚武风气。","focus":["首章“子之还兮，遭我乎狃之间兮”：你好敏捷，在峱山之间遇上我。“还”字有地名与敏捷两说，存疑。紧接着“并驱从两肩兮，揖我谓我儇兮”：并驾追赶两头兽，你向我作揖，称赞我身手轻捷。","二、三章把“儇”换成“好”“臧”，把“两肩”（三岁的兽）换成“两牡”“两狼”，随着猎物变换，赞美也越来越高。双方的称赞都是“我夸你，你夸我”，既亲切又谦让。","这首诗没有一句议论，只有场景与对话，很像一段短剧。传统认为是讽刺齐国好田猎，存疑；实际读来，更像对猎手本领的赞美。《国风》中这类男子之间的诗不多，因此值得一读。"],"notes":[["还","敏捷，一说地名"],["遭","相遇"],["狃","山名，一说峱山"],["并驱","一起追逐"],["两肩","三岁的兽，一说两只兽"],["揖","作揖"],["儇","轻捷"],["两牡","两头雄兽"],["两狼","两只狼"],["臧","好，善"]],"think":["互相夸奖的诗，为什么在《诗经》里算少见？","《诗经》里的赞美多对君王、美人，男子间的互夸不多。这首诗说明，在齐地，田猎是一种共同的生活，互夸技艺是一种社交礼仪。它可以看到《国风》里不只有爱情与怨刺，也有这类生活场景。"],"quiz":[["“并驱从两肩兮”的意思？",["并排追逐两头兽","并肩走路","相互打斗"],"“并驱”是并驾追逐，“从两肩”是追赶兽。"],["“揖我谓我儇兮”中的“儇”是？",["轻捷，敏捷","丑陋","年老"],"儇指轻捷敏捷，是猎人对猎人的称赞。"]],"cards":[["《还》的主要内容？","两个猎人在山路相遇，一起追逐猎物，互相称赞。"],["三章变化是？","地点与称赞词，由“儇”到“好”到“臧”。"]],"line":["揖我谓我儇兮","同行相遇，互相夸奖，可以用“揖我谓我儇兮”。"],"tags":["田猎","对话","尚武"]},"shijingf_dongfangweiming":{"intro":"《齐风·东方未明》写役夫被召得太早太急：天还没亮，衣裳穿颠倒了；天快亮，又来催，裳衣又穿反了。三章重复里藏着一种怨：公家的召令没个准点。读它要看“颠倒衣裳”这个细节，以及最后一句“不夙则莫”的牢骚。","focus":["首章“东方未明，颠倒衣裳。颠之倒之，自公召之”：天色未明，衣服穿反了；颠来倒去，是因为公家有令召我。“颠倒”两个字重复叠用，写出慌乱，也写出被折腾的无奈。","二章“东方未晞，颠倒裳衣。倒之颠之，自公令之”，换了词序，颠倒也被颠倒了：衣裳→裳衣，颠之倒之→倒之颠之，连语序都在“颠倒”。这是形式模仿内容的巧思。","末章“折柳樊圃，狂夫瞿瞿”写他们用柳枝做篱笆，瞪着眼的监工。最后两句“不能辰夜，不夙则莫”，是控诉：不会掌握时间，不是太早就是太晚。一个没有时间尺度的管理，是对劳动者最大的折磨。这句话今天读来，依然有力。"],"notes":[["未明","天还没亮"],["颠倒衣裳","衣服穿反"],["自公召之","从公家来召唤"],["未晞","天还没亮透"],["令","命令"],["折柳樊圃","折柳枝围篱笆"],["狂夫","指监工，一说狂妄的人"],["瞿瞿","瞪眼的样子"],["辰夜","掌握夜晚的时辰"],["不夙则莫","不是太早就是太晚"]],"think":["“不能辰夜，不夙则莫”为什么是最有力的控诉？","因为它指向制度的任意性：不是辛苦本身，而是不可预期。人可以忍受劳累，难以忍受没有节奏的差遣。这句话说出了每一个被随时召唤的人的心声，在现代的“随时在线”文化里仍然适用。"],"quiz":[["“颠倒衣裳”是什么情景？",["匆忙中把衣服穿反","舞蹈","买衣服"],"天未亮就被召，慌乱中衣裳穿反。"],["“不夙则莫”的意思？",["不是太早就是太晚","不早不晚","只在早晨"],"夙指早，莫通“暮”，晚，指召令毫无定时。"]],"cards":[["《东方未明》的核心怨言？","公家召令无定时，不是太早就是太晚。"],["“颠之倒之”有什么表达效果？","以字序颠倒模仿慌乱。"]],"line":["不能辰夜，不夙则莫","遇到没有时间规则的随叫随到，可以引“不能辰夜，不夙则莫”。"],"tags":["劳役","细节","怨刺"]},"shijingf_nanshan":{"intro":"《齐风·南山》是《诗经》里直接讽刺国君的诗：传统认为是讽刺齐襄公与他的妹妹文姜的私情。全诗四章，前两章写雄狐、葛屦、冠緌的成双成对，后两章用婚姻礼仪反问：娶妻必告父母，必由媒妁，既然如此，为什么还要放纵？读它要看礼法怎样成为讽刺的武器。","focus":["首章“南山崔崔，雄狐绥绥”：南山高大，雄狐求偶，缓缓而行。以狐的求偶讽刺不检点。“鲁道有荡，齐子由归。既曰归止，曷又怀止”：去鲁国的路平坦，齐国的女子从这里出嫁，既然已出嫁，为何还思念？“怀”这里是私情的婉辞。","二章“葛屦五两，冠緌双止”，鞋要成双，帽带要成对，各有定制，用来引出“鲁道有荡，齐子庸止。既曰庸止，曷又从止”：既然她已由此道出嫁，为什么还有人追随？这是以礼制的“成双”，对照不合礼的“相从”。","三、四章“取妻如之何？必告父母”“取妻如之何？匪媒不得”：娶妻要告知父母，要靠媒人。既然礼已齐备，为何还要“鞠”（放纵）、“极”（无度）？这几句是诗的锋芒，直接质问。传统将讽刺对象指向齐襄公兄妹，这里依从传统，存疑。"],"notes":[["崔崔","山高大的样子"],["绥绥","缓缓行走的样子"],["鲁道有荡","通往鲁国的道路平坦"],["齐子","齐国的女子"],["归","出嫁"],["曷又怀止","为什么又思念"],["葛屦","葛布做的鞋"],["冠緌","帽带"],["蓺麻","种麻"],["衡从","纵横，指田垄整齐"],["匪媒不得","没有媒人就办不成"],["鞠","放纵"]],"think":["为什么说这首诗是“以礼讽刺”，而不是直接指责？","因为它没有说一句骂人的话，只是反复列举正常婚姻所需的礼：告父母、凭媒妁、成双成对。礼仪的完整，反衬行为的失礼。读者自己得出结论。这种“以正衬邪”的讽刺，比直接谩骂更有杀伤力。"],"quiz":[["“取妻如之何？必告父母”体现什么？",["婚姻须经父母同意","婚姻不需要父母","婚姻要花钱"],"这是周代婚礼的基本要求，用来反衬失礼的行为。"],["“雄狐绥绥”的作用是？",["以狐求偶比喻不检点","描写山景","描写动物"],"绥绥是缓行，狐在传统中常用来比喻不正之情。"]],"cards":[["《南山》的讽刺方式？","以婚姻之礼的完备，反衬行为的失礼。"],["“取妻如之何？匪媒不得”意思？","娶妻要怎么办？没有媒人就办不成。"]],"line":["取妻如之何？必告父母","在讲到程序合规的时候，可引用“取妻如之何？必告父母”，说明凡事要按规矩办。"],"tags":["讽刺","礼","婚姻"]},"shijingf_yijie":{"intro":"《齐风·猗嗟》赞美一位射手：他身材修长，神情清朗，步子灵巧，射箭百发百中，舞蹈也合节拍。传统认为是赞鲁庄公，同时暗含讽刺其不能防止母亲文姜，存疑。读它要看一首赞美诗怎样从外貌写到技艺，再写到“以御乱”的功能。","focus":["首章“猗嗟昌兮，颀而长兮”，猗嗟是赞叹词，“昌”是盛美，颀长是高挑。“抑若扬兮，美目扬兮”，抑是额头丰满，扬是眉目飞扬。“巧趋跄兮，射则臧兮”，从容的步伐，出色的射技。外貌、步姿、射箭，三层依次出现。","二章“终日射侯，不出正兮”：整天射靶，都没有出过靶心。“展我甥兮”是点题：确实是我们的外甥。传统认为这个“甥”是指鲁庄公，因为他是齐襄公的外甥，存疑。这里的赞美里，含着一点亲昵的口气。","三章写舞与射：“舞则选兮，射则贯兮，四矢反兮，以御乱兮”：舞蹈合乐，射箭贯靶，四支箭都落在同一处，足以抵御祸乱。最后一句把射技提升为安邦之用，是周代对射礼的价值判断：射不是游戏，是能力与德行的象征。"],"notes":[["猗嗟","赞叹词"],["昌","盛美"],["颀","修长"],["抑若扬","额头丰满而眉目扬起，一说容貌华美"],["巧趋跄","步伐轻巧有节奏"],["臧","好"],["射侯","射靶"],["不出正","没有射偏"],["展我甥兮","确实是我们的外甥"],["选","合乎节拍，一说挑选出众"],["贯","射穿靶"],["四矢反","四支箭落在同一处，一说往复"],["以御乱","足以抵御祸乱"]],"think":["这首诗赞美的是一位射手，为什么最后落到“以御乱兮”？","因为周代的“射”不仅是技艺，也是礼与德的象征。一个人能射中，说明心正体直，也代表能保护国家。所以赞美从外形到技术，最终落在功能。同时有传统读法认为这是讽刺：既然这么能干，为何不能管住母亲？这一层，诗里没有直说，存疑。"],"quiz":[["“不出正兮”的“正”是？",["靶心","正确","正月"],"正是靶心，不出正指箭不离靶心。"],["“展我甥兮”的“甥”传统指？",["鲁庄公","齐襄公","文姜"],"传统认为是鲁庄公，他是齐襄公的外甥，存疑。"]],"cards":[["《猗嗟》的赞美层次？","从外貌、步伐、射技，到舞蹈与安邦。"],["“四矢反兮”意思？","四支箭都落在同一位置，说明箭法精准。"]],"line":["射则贯兮","在评价一位专业能力强的同事时，可以用“射则贯兮”形容其精准。"],"tags":["赞美","射礼","读法争议"]},"shijingf_yuantao":{"intro":"《魏风·园有桃》是一个士人的自白：园里有桃，可以吃；心里有忧，所以歌唱。别人不了解我，说我“士也骄”（太傲慢）；而我这样想，谁又知道？末句“盖亦勿思”，既是别人说的，也是自我安慰：不要再想了。读它要看孤独与无人理解怎样被写成一个“其谁知之”的反复。","focus":["首章“园有桃，其实之肴。心之忧矣，我歌且谣”：桃子可以作菜肴，歌谣是我的抒发。接着“不知我者，谓我士也骄”：不了解我的人，说我是个傲慢的读书人。“骄”是误解，也是标签。","“彼人是哉，子曰何其”：那个人做得对，你问有什么问题。这是在复述别人的话，两种声音交织：我说他不对，别人说他对。“其谁知之，盖亦勿思”：谁理解我呢？算了，不要想了。后面叠一句“其谁知之”，是自问，也是无人回应。","二章把“桃”换成“棘”，“谓我士也骄”换成“谓我士也罔极”：说我没有准则。从傲慢到没有准则，批评的程度加重了。“聊以行国”，姑且走遍国中，是以行走排忧。整首诗是一个人在群体里被误解的内心剧本。"],"notes":[["肴","菜肴，做成菜"],["歌且谣","有曲调的叫歌，无曲调的叫谣"],["不知我者","不了解我的人"],["士也骄","读书人傲慢"],["彼人是哉","那个人是对的"],["子曰何其","你说为什么呢"],["其谁知之","谁能理解我呢"],["盖亦勿思","算了，不要再想"],["聊以行国","姑且走遍国内"],["罔极","没有准则，不守规矩"]],"think":["“其谁知之，盖亦勿思”这种“自我劝退”的情绪，在今天依然常见吗？","非常常见：被误解后，一开始想解释，之后觉得没人会懂，最后劝自己别想了。这首诗把这个心理过程压缩成两句话，且用“歌且谣”的方式处理，而不是对抗。可以说，艺术表达是处理孤独的一种古老方式。"],"quiz":[["“谓我士也骄”是？",["说我这个读书人傲慢","说我很穷","说我很勇敢"],"“骄”指傲慢，“士”是读书人，这是别人对他的评价。"],["“盖亦勿思”的语气是？",["自我劝解的无奈","兴高采烈","严厉命令"],"“盖亦勿思”是“算了别想了”，带着无奈与自我安慰。"]],"cards":[["《园有桃》里的“士”遭遇什么？","被误解，被说成骄傲、没有准则。"],["“其谁知之”的意思？","谁能理解我呢？"]],"line":["心之忧矣，我歌且谣","压力大的时候，写点东西、唱首歌，是“心之忧矣，我歌且谣”。"],"tags":["孤独","被误解","自白"]},"shijingf_zhigu":{"intro":"《魏风·陟岵》写一个征人登上山头，遥望故乡，想象父母兄长对他说的话。每章第一句是“陟彼岵兮”“陟彼屺兮”“陟彼冈兮”，对象是父、母、兄，叮嘱是“上慎旃哉，犹来”，只有最后一个词在变：无止、无弃、无死。读它要看，想象中的叮嘱怎样一步步靠近生死。","focus":["首章“陟彼岵兮，瞻望父兮”：登上有草木的山，远望父亲。随后的话不是诗人说的，而是想象父亲的话：“嗟！予子行役，夙夜无已。上慎旃哉，犹来！无止！”孩子啊，你在服役，早晚不停，要小心，还要回来，别留在那里。","二章“陟彼屺兮，瞻望母兮”，屺是无草木的山，母亲说“予季行役，夙夜无寐”，季是小儿子，母亲担心的是睡眠。三章“陟彼冈兮，瞻望兄兮”，兄说“夙夜必偕”，早晚都要和同伴一起。从父亲的“无止”，到母亲的“无弃”，到兄长的“无死”，叮嘱越来越直接。","全诗最动人的地方是视角：它是别人说的话，但是出现在征人的头脑里。想象中的父母，也许比真实的父母更温柔。这样的“对写”，与《卷耳》类似，是《诗经》中表达思念的成熟手法。"],"notes":[["陟","登"],["岵","有草木的山"],["屺","无草木的山"],["瞻望","远望"],["行役","外出服役"],["夙夜","早晚"],["上慎旃哉","一定要小心啊，旃是“之”的合音"],["犹来","还要回来"],["无止","不要停留在外"],["无弃","不要被抛弃，一说不要丢弃"],["无死","不要死"]],"think":["三章末尾的“无止”“无弃”“无死”顺序，有什么意味？","顺序是越来越直接地触及生死。父亲说“别停留”，是对归期的期待；母亲说“别被抛弃”，是对安危的担忧；兄长说“别死”，是最直白的话。从含蓄到直接，既是亲人身份的差异，也是诗人心里恐惧的逐步显露。"],"quiz":[["“陟彼岵兮”的“岵”是什么？",["有草木的山","没有草木的山","河流"],"岵是有草木的山，屺是无草木的山。"],["全诗中的叮嘱是谁说的？",["征人想象中的亲人","诗人亲耳听到的人","君王"],"这些话是征人在山上遥望时想象的父母兄长所说。"]],"cards":[["“上慎旃哉，犹来”意思？","一定要小心，还要回来。"],["《陟岵》的写法？","想象亲人对自己的叮嘱，视角转换。"]],"line":["上慎旃哉，犹来","出发去外地出差的同事，临行可以送一句“上慎旃哉，犹来”。"],"tags":["征人","思亲","对写"]},"shijingf_shimuzhijian":{"intro":"《魏风·十亩之间》只有两章，是《诗经》里最轻盈的一首：桑园里采桑的人悠闲自在，邀约同伴“行与子还”“行与子逝”：一起回家吧。传统认为是写政治衰败，贤者想隐居，存疑。读它要看这样的短小之作怎样用几个叠字写出一个傍晚的松弛。","focus":["首章“十亩之间兮，桑者闲闲兮，行与子还兮”：十亩桑田之间，采桑人悠然自得，我与你一同回去。“闲闲”是宽裕、从容，没有紧迫的样子，在《魏风》中很特别，因为同篇的《伐檀》《硕鼠》都是沉重的。","二章“十亩之外兮，桑者泄泄兮，行与子逝兮”：十亩之外，采桑者泄泄，和乐。“逝”与“还”同义，是回去、离开。“十亩之间”与“十亩之外”是空间的变换，一内一外，意思上是整个桑园都很安详。","全诗没有任何一个具体的故事，只是一个场景：人们在一天结束时结伴回家。它在《魏风》中成为一个“静”的出口。传统认为这是贤者想离开乱世去隐居，也可以直接读为田园傍晚的歌，不必强加政治意义。"],"notes":[["十亩之间","十亩桑园里"],["桑者","采桑的人"],["闲闲","从容宽裕的样子"],["行与子还","我与你一起回去"],["十亩之外","十亩之外的地方"],["泄泄","和乐自在的样子"],["行与子逝","我与你一起离去"],["还","回去"]],"think":["这首诗为何适合放在《魏风》的《伐檀》《硕鼠》之前？","因为它是前面两篇重压之下的“呼吸”：先有一个轻松的田园场景，再有批判的尖锐诗。这里的“轻”是对“重”的映衬。可以体会《诗经》编排的用心，也可以看到，同一地域的诗并不都是怨刺。"],"quiz":[["“桑者闲闲”的“闲闲”意思？",["从容自得","忙碌","疲倦"],"“闲闲”指宽裕悠闲的样子。"],["“行与子还”与“行与子逝”意思上是？",["都是与你一起回去","一个回去，一个离开","一个去，一个来"],"“还”和“逝”都有回去、离去的含义，变换字面，意思相近。"]],"cards":[["《十亩之间》的整体气氛？","傍晚桑园里的悠闲，结伴回家。"],["“桑者闲闲兮”的含义？","采桑的人从容宽裕。"]],"line":["十亩之间兮，桑者闲闲兮","周五下午大家收工早，可以说“十亩之间兮，桑者闲闲兮”。"],"tags":["田园","傍晚","闲适"]},"shijingf_xishuai":{"intro":"《唐风·蟋蟀》写年终：蟋蟀进了屋，一年快过完了，今天不乐一乐，日子就过去了。可是紧接着诗人自己把话收回：不要过分，要想想本分，快乐也不要荒废，好人要警惕。三章同样的结构：劝乐，自警，立论。读它要看一首“享乐诗”怎样一边享受，一边提醒自己。","focus":["首章“蟋蟀在堂，岁聿其莫”：蟋蟀进堂，是秋深的信号，岁末将至。“今我不乐，日月其除”：现在不及时行乐，日子就要流走了。这个“除”字，带着一点时间的紧迫。","然而下一句立刻转向：“无已大康，职思其居。好乐无荒，良士瞿瞿”：不要过度安乐，要想着自己的本职；喜欢娱乐，但不要荒废，好人总是警惕的。这是对前半句的自我约束，也是全诗的核心：享乐要有边界。","三章的变化是时间：莫→逝→“役车其休”，由岁末到日月流逝，再到役车歇息，是年终农闲的实景。对应的自警也从“职思其居”变成“职思其外”“职思其忧”：本分、分外、忧患。一章比一章远，从守住自己，到想到外面，再到想到可能到来的忧患。"],"notes":[["蟋蟀在堂","蟋蟀入屋，指秋深"],["岁聿其莫","年终将近，莫通“暮”"],["日月其除","时光流逝"],["无已大康","不要过分安乐"],["职思其居","常想着本职"],["好乐无荒","喜欢娱乐而不荒废"],["良士","品德好的人"],["瞿瞿","警惕四顾的样子"],["役车其休","役车歇息，指农闲"],["慆","逝去"],["休休","安闲宽容的样子"]],"think":["为什么说《蟋蟀》是一首“自我节制的享乐诗”？这在今天有何借鉴？","因为它每章都在“享乐”与“警惕”之间拉锯：先说及时行乐，再说不可过度。这种平衡意识，在管理个人时间与资源时仍有价值：不是禁欲，也不是放纵，而是在享受中保留对未来风险的警觉。也可以把“职思其忧”理解为：享乐时也要想到可能到来的困难。"],"quiz":[["“无已大康”的“大康”指？",["过度安乐","大的康复","大丰收"],"“康”是安乐，“大康”是过度安乐，是诗人要避免的。"],["“好乐无荒”想表达？",["享乐要有节制","不要享乐","享乐越多越好"],"诗人并不反对乐，而是强调不荒废。"]],"cards":[["“今我不乐，日月其除”的意思？","现在不享受，日子就过去了。"],["三章“职思其居、外、忧”的递进？","从本职，到分外之事，再到可能的忧患。"]],"line":["好乐无荒，良士瞿瞿","年底聚餐可以放松，但要记住“好乐无荒，良士瞿瞿”。"],"tags":["节制","岁末","自警"]},"shijingf_yangzhishuitang":{"intro":"《唐风·扬之水》写的是一场秘密的投靠：白石在清水里洁白闪亮，穿着绣领红边的白衣，跟你到沃地去。见到了你，怎么不高兴。最后一章忽然压低声音：“我闻有命，不敢以告人”，我听说有命令，不敢告诉别人。传统认为写的是晋国曲沃一系势大而人心归附，存疑。读它要看一首诗里的紧张是怎样藏在“不敢以告人”里的。","focus":["起兴“扬之水，白石凿凿”：水流之下白石鲜明，凿凿是鲜明的样子。水清石白，是一个洁净的画面。接着“素衣朱襮，从子于沃”：白衣，红色的绣领，跟着你去沃地。这是一个人投奔他人的场面，衣着鲜明，心情轻快。","“既见君子，云何不乐”：见到你，怎么会不高兴。二章“云何其忧”，换成“忧”，既然见了就不用忧愁了。两章反复说“乐”与“忧”，是在安慰自己，也是在向对方表达依附。","末章“我闻有命，不敢以告人”突然转向，声音变小：我听到消息，却不敢告诉别人。传统说是晋国人知道曲沃要夺位，不敢说出来。这里有两层：一是对新主的欢迎，二是对旧主的隐瞒。这一章让整首诗从明亮变成暗流，是《唐风》中最有悬念的一首。"],"notes":[["扬之水","缓缓流动的水"],["凿凿","鲜明的样子"],["素衣朱襮","白衣配红领"],["从子于沃","跟随你到沃地"],["既见君子","已见到了你"],["云何不乐","怎么会不高兴"],["皓皓","洁白的样子"],["朱绣","红色刺绣"],["粼粼","水清石现的样子"],["我闻有命","我听到了命令或消息"],["不敢以告人","不敢告诉别人"]],"think":["最后一章为什么要换成“不敢以告人”？对全诗有什么影响？","前两章是公开的欢迎，最后一章是私下的秘密，反差使全诗有了悬念。读者开始想：他听到什么了？为什么不敢说？这一转，让原本平常的欢迎诗变成了政治诗，也让人意识到，真正的情绪常常在不能说的地方。"],"quiz":[["“素衣朱襮”描写？",["白衣红领的礼服","黑衣白领","红衣"],"素衣是白色衣，朱襮是红色的绣领，是贵族的服饰。"],["末章“不敢以告人”的意味是？",["有秘密，不敢说","没有秘密","喜欢告诉别人"],"这是全诗的转折，暗示有不能公开的消息。"]],"cards":[["“扬之水，白石凿凿”的作用？","起兴，用水清石白的画面引出洁净与分明。"],["“我闻有命，不敢以告人”的语气？","压低声音的秘密。"]],"line":["我闻有命，不敢以告人","项目有内部消息，不能外传，可以说“我闻有命，不敢以告人”。"],"tags":["政治","秘密","转折"]},"shijingf_choumou":{"intro":"《唐风·绸缪》是新婚之夜的诗：柴草捆得紧紧的，三星挂在天上。今天是什么夜晚，竟然见到这样好的人。三章中，柴薪的捆束、星的位置、看见的人，都在变化，时间一点点推进，夜越来越深。读它要看一个夜晚怎样在三个意象里慢慢走完。","focus":["首章“绸缪束薪，三星在天”：绸缪是缠绕捆束，束薪是捆好的柴，婚礼常用柴薪，因为柴薪可点火。三星在天，是夜已来临。二章“束刍，三星在隅”，三星偏到一角；三章“束楚，三星在户”，三星正对门户。星位的变化，既写夜深，也暗示时间的推进。","“今夕何夕，见此良人”是诗中最有名的一句，用问句表达惊喜：今天是什么日子，见到这么好的人。“良人”“邂逅”“粲者”依次出现：良人是好人，邂逅是意外遇见，粲者是美丽的人。从对方的品德，到偶遇，再到容貌，赞美的角度在变。","“子兮子兮，如此良人何”是一句娇嗔式的无奈：你呀你呀，对这样好的人我该怎么办。读到这里，已经不是在说“见到”，而是在说“怎么办”，欢喜到不知所措。这是爱情诗里最可爱的一笔。"],"notes":[["绸缪","缠绕捆束"],["束薪","捆好的柴"],["三星","星名，说法不一，存疑"],["今夕何夕","今天是什么夜晚"],["良人","好人，指丈夫"],["束刍","捆好的草"],["邂逅","意外相遇"],["束楚","捆好的荆条"],["粲者","美丽的人"],["子兮子兮","你啊你啊"],["如此良人何","拿这样的好人怎么办"]],"think":["“今夕何夕”后来成为古诗中的常见语，你觉得是为什么？","因为它抓住了人对“特殊时刻”的惊讶感：时间本是平常的，却因为遇到某个人而变得特别。它是对“时间被赋予意义”这一经验的最简表达。后世苏轼、纳兰等人都用过类似的句式，说明这种惊喜的普遍性。"],"quiz":[["“三星在天”“在隅”“在户”表示？",["夜越来越深","天越来越亮","星星消失"],"星位由天到隅到户，表示夜晚逐渐推进。"],["“子兮子兮，如此良人何”是什么语气？",["欢喜得不知所措的娇嗔","愤怒的责备","冷漠"],"“如此良人何”是拿这样的好人怎么办，带着甜蜜的无奈。"]],"cards":[["“今夕何夕，见此良人”的意思？","今晚是什么日子，竟然见到这样好的人。"],["《绸缪》中三星位置变化的意义？","夜渐深，时间在推进。"]],"line":["今夕何夕，见此良人","久别重逢的朋友聚会，可以说“今夕何夕，见此良人”。"],"tags":["新婚","夜","惊喜"]},"shijingf_baoyu":{"intro":"《唐风·鸨羽》是一首被徭役压垮的农民的呼喊：鸨鸟落在丛生的栎树上，公家的事没有尽头，我不能种庄稼，父母靠谁。苍天啊，什么时候才有安居，有尽头，有常道。读它要看起兴的鸨鸟，和三章“所”“极”“常”的递进。","focus":["起兴“肃肃鸨羽，集于苞栩”：鸨鸟振翅，停在丛生的柞树上。古人认为鸨不善于栖树，所以这个画面带着不安和勉强，象征服役者无处安身。三章依次换成苞栩、苞棘、苞桑，鸨在不同的树上，都站不稳。","“王事靡盬，不能蓺稷黍”：公家的差事没有休止，我不能种庄稼。接着“父母何怙”“何食”“何尝”，依次是依靠、吃的、尝的：父母靠什么活？吃什么？连尝一口的东西都没有了。三个动词由抽象到具体，让人看到一个家庭怎样被徭役拖垮。","最后“悠悠苍天，曷其有所”“有极”“有常”：苍天啊，什么时候能安居？什么时候有尽头？什么时候恢复常态？所、极、常，是对一个正常秩序的三个要求：有归宿，有终点，有规律。这是一个劳动者最低限度的愿望。"],"notes":[["鸨","一种大型鸟"],["苞栩","丛生的柞树"],["王事靡盬","公家的差事没有止息"],["蓺","种植"],["稷黍","小米与黍"],["怙","依靠"],["悠悠苍天","遥远的老天"],["曷其有所","什么时候能有安居之处"],["有极","有尽头"],["有常","恢复常规"]],"think":["“曷其有所”“有极”“有常”为什么能构成对徭役的完整控诉？","因为它们列出了劳动者最基本的三个需求：居所、期限、规律。徭役夺走了三者：没有地方安身，没有结束的时间，也没有稳定的生活节奏。读者可以看出：压迫不只是劳累，还在于不确定与无序。"],"quiz":[["“王事靡盬”是什么意思？",["公家的差事没有休止","国王生病","国家安宁"],"盬是止息，靡盬是没有止息。"],["“父母何怙”表达？",["父母没有依靠","父母很富有","父母外出"],"怙是依靠，因为儿子服役，父母失去依靠。"]],"cards":[["《鸨羽》的核心？","徭役使农民不能耕种，父母无以为生。"],["“悠悠苍天，曷其有所”意思？","老天啊，什么时候才能有安居？"]],"line":["王事靡盬，不能蓺稷黍","项目不断，没时间做长期规划，可以叹一句“王事靡盬”。"],"tags":["徭役","农民","呼天"]},"shijingf_wuyitang":{"intro":"《唐风·无衣》与《秦风·无衣》同题，内容完全不同。秦风是“岂曰无衣，与子同袍”的战友情，而唐风说的是：难道我没有衣服七件吗？不如你的衣服，穿得安适又吉祥。传统认为这是晋武公贿赂周王，求封为诸侯的诗，存疑。读它要看这个“不如子之衣”里的谦与求。","focus":["首章“岂曰无衣七兮？不如子之衣，安且吉兮”：不是没有衣，我有七件，但不如你给的那一件，穿着安适又吉利。“七”可能指七章之衣，是诸侯的礼服规格，存疑。重点是对比：自己有很多，却不如你给的好。","二章“岂曰无衣六兮”，数字从七降到六，“安且吉”换成“安且燠”，燠是暖和。第一章说吉利，是礼的层面；第二章说暖，是人的层面。从象征，到体感，是由抽象到具体。","整首诗没有多余的话，只是一个自我降低的姿态：我什么都有，却想要你给的。这既是请求，也是恭维。若放在晋武公的背景下，那件“衣”，就是周王的册命。在没有背景的情况下，读作朋友赠衣的诗，同样成立，可以读出赠与受之间的感情。"],"notes":[["岂曰","难道说"],["无衣","没有衣服"],["七","七件，一说七章之服"],["不如子之衣","不如你给的衣服"],["安","安适"],["吉","吉祥"],["六","六件"],["燠","温暖"]],"think":["同题的唐风、秦风《无衣》在气质上有什么不同？","秦风的“无衣”是共同穿一件袍子，是平等的同袍；唐风的“无衣”是我有衣却想要你的衣，是不对等的请求。一个是战场上的集体情谊，一个是礼仪中的个体附带。题目相同，说明“衣”在周人生活里既是物，也是关系的符号。"],"quiz":[["“岂曰无衣七兮”的“岂曰”是？",["难道说","因此说","曾经说"],"“岂曰”是反问，意思是难道说没有衣服。"],["“安且燠兮”的“燠”是？",["温暖","寒冷","漂亮"],"燠指暖和，与上章的“吉”对应，由礼到体感。"]],"cards":[["唐风《无衣》的特点？","以自己有衣与对方给衣对照，表达对对方恩赐的看重。"],["两首《无衣》的差异？","秦风是战友共袍，唐风是请求赐衣。"]],"line":["不如子之衣，安且吉兮","收到前辈送的小礼物，可以说“不如子之衣，安且吉兮”，表达心意。"],"tags":["同题","衣","请求"]},"shijingf_gesheng":{"intro":"《唐风·葛生》是一首悼亡诗：葛藤爬满荆树，蔹草蔓延在野，我的爱人葬在这里，谁与你同在？我独自一人。三章结尾的“独处”“独息”“独旦”，加上末二章“夏之日，冬之夜。百岁之后，归于其居”，是《诗经》中最动人的悼亡之作。读它要看孤独怎样由空间走到时间，再走到死后。","focus":["首章“葛生蒙楚，蔹蔓于野”：葛藤覆盖着荆条，蔹草蔓延在野外。这是荒草中的墓地景象，藤蔓缠绕，反衬孤独。“予美亡此，谁与？独处”：我的爱人死在这里，谁和你在一起？只有我独自一人。“谁与”一词，把活者与死者的孤独并置。","第三章“角枕粲兮，锦衾烂兮”：角枕、锦被是随葬品，也是旧日生活的遗物，色彩鲜明。读者可以看到：物品仍然华美，人已不在。“独旦”是独自到天亮，写出长夜无眠。这里从空间（处、息）进入时间（旦）。","最后两章“夏之日，冬之夜。百岁之后，归于其居”：夏天的长日，冬天的长夜，是难熬的两种时间；等我百年之后，再回到你的居所。“居”“室”是墓穴。这是对死后同穴的承诺，不是浪漫，而是漫长孤独之后的唯一出路。"],"notes":[["葛生蒙楚","葛藤覆盖荆条"],["蔹","一种蔓草"],["予美","我的爱人"],["亡此","死在这里，葬在这里"],["谁与","谁与你同在"],["独处","独自居住"],["独息","独自安歇"],["角枕","用兽角装饰的枕头"],["锦衾","锦缎被子"],["独旦","独自等到天亮"],["百岁之后","我百年之后"],["归于其居","回到你的住所，指同穴"]],"think":["“夏之日，冬之夜”为什么被认为是《诗经》里最沉重的时间表达？","因为夏天日长、冬天夜长，是一年中最难熬的两类时间。把这两种时间放在一起，等于说“无论白天黑夜，无论春夏秋冬，我都在等”。这样的写法不需要夸张，只需列出最难的时段，就足以说明时间的漫长。"],"quiz":[["“予美亡此”的“美”指？",["我所爱的人","我的美貌","美好的事"],"“予美”是我的爱人，这里指已故的亲人。"],["“归于其居”是什么意思？",["死后同穴","回家","搬家"],"“居”指墓穴，是对死后同葬的期望。"]],"cards":[["《葛生》的类型？","悼亡诗，写失去爱人的孤独。"],["“夏之日，冬之夜”的意思？","夏天的白昼和冬天的夜晚，是最漫长的时间。"]],"line":["夏之日，冬之夜","形容一段难熬的漫长时期，可以说“夏之日，冬之夜”。"],"tags":["悼亡","时间","孤独"]},"shijingf_xiaorong":{"intro":"《秦风·小戎》是一位妻子在家里想念出征的丈夫，却用了大量篇幅描写战车、兵器、甲马。每章前半是装备的细节，后半是“言念君子”，把铠甲之硬与君子之温放在一起。读它要看尚武的秦风怎样在军备描写里嵌入深情。","focus":["首章“小戎俴收，五楘梁辀。游环胁驱，阴靷鋈续。文茵畅毂，驾我骐馵”：一连串车上的部件，从车厢、辕、环、引绳、车垫、车毂，到驾车的马，像一份战车清单。这些词今天难懂，但读者能感到：她知道丈夫的车，一件一件都清楚。熟悉本身就是感情。","后半句“言念君子，温其如玉。在其板屋，乱我心曲”：想到我的君子，温润如玉；他在板屋里（板屋是西戎一带的房屋形式，说明此处的西部风土），我的心为之乱。装备的冷硬与“温其如玉”的柔软，形成对照。","三章装备更重：龙盾、虎韔、厹矛，是兵器的细节；而对君子的描写也在变：温其如玉、温其在邑、载寝载兴，“厌厌良人，秩秩德音”：安静的好人，有条理的好声音。她的思念，从形象，到处境，到夜里的辗转，也在加深。"],"notes":[["小戎","小型兵车"],["俴收","浅的车厢"],["楘","缠在辕上的皮条"],["梁辀","弯曲的辕"],["游环","活动的环"],["文茵","虎皮车垫"],["骐馵","青黑色、后左脚白的马，一说骏马"],["言念君子","想到我的君子"],["温其如玉","温润像玉"],["板屋","木板盖的房屋"],["龙盾","画有龙纹的盾"],["厹矛","三棱矛"],["厌厌","安静的样子"],["秩秩德音","有条理的好声音"]],"think":["《小戎》为什么要用这么多篇幅写战车？这对表达思念有什么帮助？","因为战车是丈夫的“在场”：妻子无法描写他的脸，却能描写他驾驭的东西。装备的细节也是对丈夫身份的骄傲，秦人尚武，妻子并不因丈夫出征而羞，反而自豪。这样，思念里带着骄傲，与一般的怨妇诗不同。"],"quiz":[["“温其如玉”形容？",["君子温润","战车坚固","马匹健壮"],"以玉的温润比喻丈夫的人品。"],["“在其板屋”体现了什么？",["西部风土的特点","南方的雨","北方的雪"],"板屋是西戎地区常见的房屋，说明秦地风俗。"]],"cards":[["《小戎》的特点？","大量描写战车兵器，同时表达妻子对君子的思念。"],["“言念君子，温其如玉”？","想到丈夫，他温润如玉。"]],"line":["言念君子，温其如玉","形容一位专业能力强又温和的同事，可以说“言念君子，温其如玉”。"],"tags":["尚武","思夫","对比"]},"shijingf_zhongnan":{"intro":"《秦风·终南》是秦人对来朝国君的赞美：终南山上有条（树）有梅，君子到了，穿着锦衣狐裘，脸色红润如丹。传统认为是秦襄公被封为诸侯的时候，存疑。读它要看一首赞美诗怎样借山与衣写出一位新君的气象。","focus":["开头“终南何有？有条有梅”：终南山有什么？有条（树名）有梅。这是自问自答的起兴，终南山高大，树木繁盛，象征君子有德。二章“有纪有堂”，纪是山的边角，堂是山中平坦之处，是山貌的变化。","“君子至止，锦衣狐裘。颜如渥丹，其君也哉”：君子到来，锦衣狐裘，脸色像刚涂的红色。渥丹是润泽的红，是健康与威仪的象征。“其君也哉”是赞叹：真像一位君主。这里写的是外在形象。","二章写“黻衣绣裳，佩玉将将，寿考不忘”：黻衣是绣有花纹的礼服，佩玉叮当，愿他长寿不忘。从颜色，到服饰，再到声音，最后是祝福。这是一首典型的礼仪诗，适合在仪式场合吟唱。在《秦风》里，它与《小戎》的刚劲相比，显得雍容。"],"notes":[["终南","终南山"],["条","树名，一说山楸"],["君子至止","国君来到"],["锦衣狐裘","锦缎外衣，狐皮袍子"],["渥丹","润泽的红色"],["其君也哉","真像一位君主啊"],["纪","山的边角"],["黻衣","绣有花纹的礼服"],["绣裳","绣花的下裳"],["佩玉将将","佩玉叮当作响"],["寿考不忘","愿长寿而不被忘记"]],"think":["这首诗用山、衣、颜、玉来赞美国君，没有一句写政绩，这合适吗？","在礼仪场合，赞美的重点是形象与气度，而不是政绩，因为政绩需要时间检验。形象是当下可见的，也是礼的一部分。读者可以体会：礼乐文化重视“仪”，因为仪表被看作德行的外显。当然，这也有局限，后来的《相鼠》就是对“仪”与实际不符的反讽。"],"quiz":[["“颜如渥丹”形容？",["脸色红润","衣服红","酒红"],"渥丹是润泽的红色，形容气色红润。"],["“终南何有”的作用是？",["自问自答的起兴","真正的问题","描写战争"],"这是起兴，用山上的树木引出君子。"]],"cards":[["《终南》是什么性质的诗？","赞美来朝的国君的礼仪诗。"],["“佩玉将将”写什么？","佩玉相碰的声音，增加威仪感。"]],"line":["颜如渥丹，其君也哉","夸一位气色很好、气场十足的领导，可以说“颜如渥丹，其君也哉”。"],"tags":["礼仪","赞美","国君"]},"shijingf_huangniaoqin":{"intro":"《秦风·黄鸟》是为三位殉葬的良臣写的哀歌。《左传》文公六年记载，秦穆公去世，以子车氏的三个儿子奄息、仲行、针虎殉葬，国人哀悼，为他们作了《黄鸟》。三章结构一样，只换人名与评价。读它要看诗里一句“如可赎兮，人百其身”，是怎样的呼号。","focus":["起兴“交交黄鸟，止于棘”：黄鸟鸣叫，停在棘树上。棘与“急”“戚”谐音，这是后世的一种读法，原诗未明说。三章换为桑、楚，都是难以安身的树。黄鸟本应自在，在这里却停得不安。","“谁从穆公？子车奄息。维此奄息，百夫之特”：谁跟着穆公殉葬？是子车奄息。这个奄息，是百人中的杰出者。第二章“百夫之防”，第三章“百夫之御”，特、防、御，从杰出到可以抵挡百人，再到可以抗御百人，对三位的评价逐步加高。","最关键的是“临其穴，惴惴其栗。彼苍者天，歼我良人！如可赎兮，人百其身”：走到墓穴边，战栗恐惧。老天啊，你杀了我们的好人！若是可以赎，我们愿用一百人换他一人。这句话直接质问天，也是对殉葬制度的控诉。这是《诗经》里最少的、直接的“反人殉”声音。"],"notes":[["交交","鸟鸣声，一说往来飞翔"],["黄鸟","黄雀"],["棘","酸枣树"],["穆公","秦穆公"],["子车奄息","人名，子车氏之子"],["百夫之特","百人中杰出的"],["防","抵挡"],["御","抗御"],["惴惴其栗","战栗恐惧"],["歼","杀灭"],["良人","好人，指三位良臣"],["如可赎兮","如果可以赎回"],["人百其身","愿以百人换其一人"]],"think":["“如可赎兮，人百其身”为什么说是一种罕见的声音？","因为在殉葬制度被视为合法的时代，这句话把个人的价值置于集体仪式之上：一个好人的生命，值一百个人。它不是反对国君，而是对“谁该死”的追问。这种以人为本的声音，在后世的人道主义里才逐渐成为主流。《左传》的记载也说明，当时的国人确实为此作了诗，是有史可征的。"],"quiz":[["《黄鸟》的创作背景？",["哀悼被殉葬的三位良臣","庆祝胜利","送别友人"],"《左传》文公六年记载国人为三良作《黄鸟》。"],["三章中“特”“防”“御”的递进说明？",["对三人评价逐渐加高","三人能力相同","批评三人"],"从杰出，到抵挡，再到抗御，评价一层高过一层。"]],"cards":[["“如可赎兮，人百其身”的意思？","如果可以赎回，愿以百人换他一人。"],["《黄鸟》说的是哪位国君的殉葬？","秦穆公。"]],"line":["如可赎兮，人百其身","对于失去一位不可替代的人才，可以引“如可赎兮，人百其身”。"],"tags":["殉葬","哀歌","人道"]},"shijingf_chenfeng":{"intro":"《秦风·晨风》是一个女子被忘的哀叹：晨风鸟疾飞，北林茂盛，我没有见到君子，忧心忡忡，怎么办啊怎么办，你忘了我这么多。三章变化的是山林树木与忧愁的程度：钦钦、靡乐、如醉，而“如何如何，忘我实多”一字不改。读它要看这句叠问。","focus":["起兴“鴥彼晨风，郁彼北林”：晨风是一种猛禽（即鹯），疾飞入林；北林茂盛。猛禽归林是“归”的意象，反衬人不归。二、三章“山有苞栎，隰有六駮”“山有苞棣，隰有树檖”，写山上低地的树木，每一对都是各得其所，而她没有。","忧愁的程度逐章加深：“忧心钦钦”是忧念，“忧心靡乐”是没有快乐，“忧心如醉”是像醉酒一样昏乱。三个形容依次是想、不乐、昏，层层加重。","“如何如何，忘我实多”是全诗的叠句：怎么办啊怎么办，你忘记我太多了。这句话既不是怒，也不是求，是一种无奈的反复。读到这里，你能听出一个人把同一句话说了无数遍，却没有答案。"],"notes":[["鴥","鸟疾飞的样子"],["晨风","鸟名，一种猛禽"],["郁","茂盛"],["北林","北面的树林"],["钦钦","忧念不止的样子"],["如何如何","怎么办啊"],["忘我实多","忘记我太多了"],["苞栎","丛生的栎树"],["六駮","梓榆，一说兽名"],["树檖","野梨树"],["如醉","像醉酒一样"]],"think":["“如何如何”的叠用，为什么比单独说一次更有力量？","因为重复是无力感的证明：说一次是询问，说两次是沮丧，说三章则是长期的无奈。叠句还让诗成为可以反复咏叹的歌，把个人的情绪变成可以共享的情感。对读者来说，这是一个能够共鸣的节奏。"],"quiz":[["“忘我实多”是什么意思？",["你忘记我太多了","我忘记你太多了","你想起我很多"],"“实”是确实、很，“忘我实多”是你很久没想起我。"],["三章忧愁的变化是？",["钦钦、靡乐、如醉，逐步加深","由悲转喜","没有变化"],"从忧念到不乐再到如醉，逐渐加深。"]],"cards":[["“鴥彼晨风”的作用？","起兴，以猛禽归林反衬人不归。"],["“如何如何，忘我实多”的情感？","无奈的反复追问。"]],"line":["如何如何，忘我实多","久未联系的朋友，玩笑地说“如何如何，忘我实多”。"],"tags":["弃妇","叠句","无奈"]},"shijingf_weiyang":{"intro":"《秦风·渭阳》是一首送行诗：我送舅父，到渭水的北岸，用什么相赠？路车和四匹黄马；又用什么相赠？琼瑰玉佩。传统认为这是秦康公为太子时送舅舅重耳返晋的诗，存疑。读它要看一首短短的送别诗里，亲情与政治的重叠。","focus":["首章“我送舅氏，曰至渭阳”：我送舅舅，一直送到渭水之北。渭阳即渭水北岸。“何以赠之？路车乘黄”：路车是国君所乘之车，乘黄是四匹黄马，赠礼很重，像是国家级的礼物。","二章“我送舅氏，悠悠我思”，换成了思：我心中绵长地想念。“何以赠之？琼瑰玉佩”，琼瑰是美玉，佩是玉佩。从“路车乘黄”这类实用大礼，到“琼瑰玉佩”这类精致的物品，是从政治礼物转到私人礼物。","全诗只有八句，却是外甥送舅父，同时也是秦国太子送晋国流亡公子回国。传统注意到，舅舅的身份既是亲属，也是即将成为晋国国君的人。也有读法不涉及政治，只当作亲情送别，存疑。无论哪一种，诗里的“悠悠我思”都是真挚的。"],"notes":[["舅氏","舅父"],["渭阳","渭水的北岸"],["何以赠之","用什么赠送他"],["路车","诸侯乘的大车"],["乘黄","四匹黄马"],["悠悠我思","我的思念绵长"],["琼瑰","美玉"],["玉佩","玉做的佩饰"]],"think":["这首诗没有一句政治，为什么传统要读成政治诗？","因为“送舅”和“路车乘黄”这类礼物，规格很高，与秦、晋两国的关系相联系。《左传》也记载过秦送重耳回国之事（僖公二十三、二十四年）。但诗中的“太子”身份没有出现，因此这只是一种推测。读者可以保留两种解读：亲情，或亲情与政治的叠加。"],"quiz":[["“乘黄”是什么？",["四匹黄马","黄色的车","黄金"],"乘黄是驾车的四匹黄色马。"],["“渭阳”指？",["渭水北岸","渭水南岸","渭城"],"阳指水的北面，渭阳即渭水之北。"]],"cards":[["《渭阳》的情感？","外甥送舅，亲情真挚。"],["两章赠礼的变化？","从车马的大礼到玉佩的私礼。"]],"line":["我送舅氏，曰至渭阳","送别长辈或前辈，可用“我送舅氏，曰至渭阳”形容一直送到分手处。"],"tags":["送别","亲情","秦风"]},"shijingf_wanqiu":{"intro":"《陈风·宛丘》是《陈风》的开篇：一个人在宛丘上舞蹈，击鼓、击缶，无论冬夏，手持鹭羽。旁观者说：你确实有情，可是没有指望。读它要看这个“洵有情兮，而无望兮”的复杂：是爱而不得，还是对一个沉迷巫舞的人的叹惜？","focus":["首章“子之汤兮，宛丘之上兮”：你在宛丘之上舞动。汤是荡，是舞姿。“洵有情兮，而无望兮”：你确实有情，却没有希望。“无望”一词，说法不一：一说无威仪可望，一说爱而无望，存疑。","二、三章写的是舞与乐：“坎其击鼓，宛丘之下”，“坎其击缶，宛丘之道”：坎是鼓声，缶是瓦器，也能敲击。“无冬无夏，值其鹭羽”：无论冬夏，手里都拿着白鹭羽毛做的舞具。这是巫舞或祭舞的写照，陈国风俗信巫，所以多此类诗。","全诗没有评价的词，只有“有情”“无望”。读者可以读成旁观者对舞者的爱慕与叹息，也可读成对一个沉迷享乐者的批评。无论怎样，一个人在高丘上反复舞蹈，无论冬夏，是《陈风》最鲜明的画面。"],"notes":[["子","你"],["汤","通“荡”，摇动，指舞动"],["宛丘","陈国的山丘名"],["洵有情兮","确实有情"],["无望","没有希望，一说没有威仪可望，存疑"],["坎其击鼓","咚咚地击鼓"],["缶","瓦器，可敲击"],["无冬无夏","不论冬夏"],["值","持"],["鹭羽","白鹭羽毛做的舞具"],["鹭翿","用鹭羽做的羽伞"]],"think":["“洵有情兮，而无望兮”为什么说法不一？","因为“无望”可以解释为“没有希望”（爱而无果）或“没有威仪”（无可观瞻）。前者是情诗，后者是讽刺。诗的字面没有给出答案，只能根据上下文判断：全篇写舞蹈，没有出现对方的回应，也没有对错的评价。可以并存两读，把这种不确定看作诗的魅力。"],"quiz":[["“鹭羽”是？",["舞者手中的羽毛道具","鹭鸟","羽毛笔"],"鹭羽是用白鹭羽毛做的舞具。"],["“无冬无夏”表现？",["长年舞蹈不辍","冬夏温差","冬夏换衣"],"不分季节，一直舞蹈，表现其沉迷。"]],"cards":[["《宛丘》的主要意象？","舞者在高丘上击鼓、持鹭羽舞蹈。"],["“洵有情兮，而无望兮”的两种读法？","爱而无望，或无威仪可望。"]],"line":["洵有情兮，而无望兮","对于一个充满热情却难有结果的项目，可以说“洵有情兮，而无望兮”。"],"tags":["陈风","舞蹈","无望"]},"shijingf_dongmenzhifen":{"intro":"《陈风·东门之枌》写陈国的集会：东门的白榆，宛丘的柞树，子仲家的女儿在树下起舞。好日子里大家挑好地方聚在一起，她不纺麻了，到集市上跳舞。结尾她送他一把花椒。读它要看一个节日的集体舞怎样变成两个人的赠答。","focus":["首章“东门之枌，宛丘之栩。子仲之子，婆娑其下”：东门外有白榆，宛丘上有柞树，子仲家的姑娘在树下婆娑起舞。婆娑是舞姿旋转。地点（东门、宛丘）、树木（枌、栩）、人物（子仲之子）依次出现，像镜头从远到近。","二章“谷旦于差，南方之原”：选个好日子，聚到南边的平原。“不绩其麻，市也婆娑”：她不纺麻了，到集市上跳舞。这句说明节日里，她放下日常劳动，参与集体活动。一句话就把节日对生活的“打断”写出来了。","末章“谷旦于逝，越以鬷迈”：好日子里，大家聚在一起出发。“视尔如荍，贻我握椒”：看你像锦葵一样美，送我一把花椒。荍是锦葵，花椒是定情之物，因为多子。这是一首节日里的群众舞蹈诗，热闹、轻快，也有私人的小插曲。"],"notes":[["枌","白榆"],["栩","柞树"],["子仲之子","子仲家的女儿"],["婆娑","旋转起舞的样子"],["谷旦","好日子"],["于差","选择好"],["不绩其麻","不再纺麻"],["市","集市"],["鬷","众，聚集"],["迈","行，前往"],["荍","锦葵"],["握椒","一把花椒"]],"think":["“不绩其麻，市也婆娑”这一句说明了什么？","说明节日对日常生活的“暂停”：平常织麻劳动，节日来了就去跳舞。它也说明陈风重视歌舞，和其他国风不同。这类句子的价值，是留下了当时人民生活的细节：女子的工作是绩麻，节日的活动是集会、跳舞、赠椒。"],"quiz":[["“谷旦于差”的“谷旦”是？",["好日子","谷子","早晨"],"谷旦是良辰吉日。"],["“贻我握椒”的“椒”是？",["花椒，象征情意","辣椒","胡椒"],"周代没有辣椒，这里的椒是花椒，常作定情的礼物。"]],"cards":[["《东门之枌》的场景？","陈国节日里集会舞蹈，男女以椒相赠。"],["“不绩其麻，市也婆娑”？","不纺麻了，到集市上起舞。"]],"line":["不绩其麻，市也婆娑","节日放假就别想着工作，可以说“不绩其麻，市也婆娑”。"],"tags":["节日","舞蹈","陈风"]},"shijingf_hengmen":{"intro":"《陈风·衡门》是一首安贫乐道的诗：用横木做的简陋的门，也可以歇息；泌水汩汩流淌，也可以疗饥。接着是两句有名的反问：吃鱼难道一定要黄河的鲂鱼？娶妻难道一定要齐国的姜姓女子？读它要看一个人怎样用日常的比较把自己的知足说得毫不寒酸。","focus":["首章“衡门之下，可以栖迟。泌之洋洋，可以乐饥”：衡门是横木做成的门，简陋；“栖迟”是游息，在这里安闲；泌是泌水，洋洋是水流缓缓，可以让人忘饥。注意“乐饥”，可以解为以水为乐而忘饥，也可读作“疗饥”，存疑。","“岂其食鱼，必河之鲂”是一个反问：吃鱼，难道一定要吃黄河的鲂鱼？鲂鱼是名贵的。接着“岂其取妻，必齐之姜”：娶妻，难道一定要娶齐国的姜姓女子？齐姜是大国贵女的代称。他把“食鱼”和“取妻”并列，说明他的态度是一致的：适合就好，不必求高。","二章“必河之鲤”“必宋之子”，换成鲤和宋国的子姓女子，说明他并不是否定名贵，而是否定“必须”。这一点很重要：知足不是排斥更好，而是不被“必须”绑架。这样的态度，对今天的人仍有启发。"],"notes":[["衡门","横木做成的简陋之门"],["栖迟","游息，休息"],["泌","泌水"],["洋洋","水流盛大的样子"],["乐饥","以乐忘饥，一说疗饥"],["岂其食鱼","难道吃鱼"],["河之鲂","黄河的鲂鱼"],["取妻","娶妻"],["齐之姜","齐国的姜姓女子"],["河之鲤","黄河的鲤鱼"],["宋之子","宋国的子姓女子"]],"think":["“岂其取妻，必齐之姜”被当作知足的名句，你认为它是真正的知足还是自我安慰？","两者都有可能。如果他是真的不需要名贵，那是知足；如果是买不起而这样说，那是自我安慰。诗里无法判断，但“岂其”这个反问语气更像是主动的选择，而不是被动的接受。关键是“必”字：反对的不是名贵，而是“必须名贵”。"],"quiz":[["“衡门”是什么？",["横木做的简陋门","大门","城门"],"衡门是用一根横木做的门，形容居所简陋。"],["“岂其食鱼，必河之鲂”的含义？",["吃鱼不一定要吃名贵的鲂鱼","必须吃鲂鱼","不吃鱼"],"这是反问，表达对名贵的“必须”的否定。"]],"cards":[["《衡门》表现怎样的人生态度？","安贫知足，不必追求名贵。"],["“岂其取妻，必齐之姜”意思？","娶妻难道一定要娶齐国的美女？"]],"line":["岂其食鱼，必河之鲂","选供应商不必非选最大牌的，可以说“岂其食鱼，必河之鲂”。"],"tags":["知足","隐逸","反问"]},"shijingf_dongmenzhichi":{"intro":"《陈风·东门之池》是一首极简的情歌：东门的池水，可以用来沤麻；那位美好的姑娘，可以与她对歌。三章换的是沤的植物（麻、纻、菅）和“晤”的方式（歌、语、言）。读它要看一首诗怎样把劳动场景与情感交往放在一起，没有一个“爱”字。","focus":["起兴“东门之池，可以沤麻”：池水可以浸泡麻，制作纤维，是女性的日常劳动。这是一个具体的、有气味的场景：浸泡麻的池塘并不浪漫，却是诗的出发点。","“彼美淑姬，可与晤歌”：那位美好的姬姓女子，可以与她对唱。晤是面对面。二章“晤语”，三章“晤言”，从歌，到语，到言，交流从唱和，到说话，再到交谈，是关系逐步深入。","三章的“麻”“纻”“菅”是三种纤维植物，由栽培到野生，由精细到粗糙。这是一个由劳动连成的情感网络：因为一起劳动，所以可以对话。整首诗清淡，不抒情，却把情感藏在日常里。"],"notes":[["东门之池","东门外的池塘"],["沤","长时间浸泡"],["麻","麻，纤维植物"],["彼美淑姬","那位美好的姬姓女子"],["晤","面对面交谈"],["晤歌","对唱"],["纻","苎麻"],["晤语","对谈"],["菅","一种草"],["晤言","交谈"]],"think":["为什么说劳动场景是情歌的好背景？","因为劳动提供了共同的时间和空间，让人可以自然地交流，没有仪式感的压力。沤麻是一个需要等待的活，等待之间可以对歌。这样的情歌从生活中长出来，比刻意的约会更真实。这也解释了为什么《国风》中劳动与爱情常常交织。"],"quiz":[["“沤麻”是？",["长时间浸泡麻以取纤维","烧麻","种麻"],"沤是长时间浸泡，使麻的纤维分离。"],["“晤歌”“晤语”“晤言”的变化是？",["从对唱到对谈，关系深入","从说话到唱歌","都是一样"],"从歌到语到言，是交流方式逐步深入。"]],"cards":[["《东门之池》的背景？","东门池塘边沤麻，与女子对歌。"],["“晤”是什么意思？","面对面交谈。"]],"line":["彼美淑姬，可与晤歌","团建时找到志趣相投的人，可以说“彼美淑姬，可与晤歌”。"],"tags":["劳动","情歌","陈风"]},"shijingf_yuechu":{"intro":"《陈风·月出》是中国诗里最早以月写美人的作品：月出皎皎，美人俊俏，步态从容窈窕，我忧心忡忡。三章只换形容词：皎、皓、照；僚、懰、燎；窈纠、忧受、夭绍；悄、慅、惨。读它要看一首诗怎样靠叠韵与双声词的音响，写出月光中的恍惚。","focus":["首章“月出皎兮，佼人僚兮。舒窈纠兮，劳心悄兮”：月亮出来，皎洁明亮；美人俊美；走起路来舒缓而婀娜；我心忧愁。四句每句都以“兮”结尾，节奏缓慢，像月光下的脚步。","全诗最特别的是用词：窈纠、忧受、夭绍，都是形容女子步态的联绵词，意思相近，读音相近，是中国古典诗里“声音即意义”的早期例子。月光的“皎、皓、照”，是由明到亮的递进；佼人的“僚、懰、燎”，也是以美、媚、明亮形容。","“劳心悄兮”“劳心慅兮”“劳心惨兮”，是对美人的忧心。不是怨，而是被美触动之后的惆怅。这首诗里没有故事，只有月、人、心三者，是后来中国诗里“月下怀人”的源头。"],"notes":[["皎","明亮"],["佼人","美人，佼通“姣”"],["僚","美好"],["舒","舒缓"],["窈纠","女子行走时姿态曲折柔美"],["劳心","忧心"],["悄","忧愁的样子"],["皓","洁白明亮"],["懰","美好"],["忧受","形容步态舒缓"],["慅","忧愁不安"],["夭绍","形容步态婀娜"],["燎","明亮"]],"think":["为什么说《月出》是“月下怀人”的源头？","因为它把月、人、心三个要素放在一起：月光让人显得朦胧，人的美触动了心，心的忧愁使月光更冷。后世李白“明月出天山”、张九龄“海上生明月，天涯共此时”，都继承了这个结构。这首诗的价值在于，它第一次让月成为感情的容器。"],"quiz":[["“窈纠”形容？",["女子步态的柔美","月亮的形状","水流的声音"],"窈纠是联绵词，形容女子行走时曲折柔美的样子。"],["三章“皎、皓、照”体现？",["月光由明到亮的变化","月亮逐渐变暗","颜色变化"],"三个形容词同为月光的明亮，用词变化而意思递进。"]],"cards":[["《月出》的内容？","月光下一位美人，诗人忧心。"],["“舒窈纠兮”？","从容而婀娜的步态。"]],"line":["月出皎兮。佼人僚兮","月夜里与友人谈起往事，可以引“月出皎兮，佼人僚兮”。"],"tags":["月","美人","联绵词"]},"shijingf_gaoqiuhui":{"intro":"《桧风·羔裘》写一个人看着穿着羔裘、狐裘的在位者闲游，朝堂也好、庙堂也好，心里是担忧：难道我不想你吗，只是劳心忉忉。三章分别写逍遥、翱翔、如膏，与“忉忉”“忧伤”“悼”三个情绪词一一对应。读它要看一个旁观者怎样用衣服的光鲜写出国事的暗淡。","focus":["首章“羔裘逍遥，狐裘以朝”：穿着羔裘悠闲游走，穿着狐裘上朝。逍遥是闲游，以朝是去上朝，都是在位者的日常。接着“岂不尔思？劳心忉忉”：难道我不想你吗，我心中忧愁不安。","二章“羔裘翱翔，狐裘在堂”，动词由“逍遥”变成“翱翔”，场所由“朝”变成“堂”，说明在位者无所事事、在朝堂中也像在游玩。“我心忧伤”，是忧愁加深。","末章“羔裘如膏，日出有曜”：羔裘像油脂一样光滑，太阳出来闪闪发亮。衣服越来越华美，对比越来越强烈。“中心是悼”：心中悲痛。三章以衣服的华丽层层推进，以忧愁的深度层层推进，一边是光，一边是暗，是“以乐景写哀”的写法。传统说是讽刺桧国国君不理政事，存疑。"],"notes":[["羔裘","羔羊皮袍"],["逍遥","悠闲地游走"],["狐裘","狐皮袍"],["以朝","用来上朝"],["岂不尔思","难道不想你吗"],["劳心忉忉","忧心忡忡"],["翱翔","自由游走，闲游"],["在堂","在朝堂"],["如膏","像油脂一样润泽"],["日出有曜","太阳出来闪闪发光"],["中心是悼","心中悲痛"]],"think":["这首诗没有指责在位者，为什么仍然被理解为讽刺？","因为它的对比：你如此光鲜，而我如此忧愁。读者不需要诗人说“你错了”，就能感受到差距。这种以“不说”表达批评的写法，在《诗经》里常见，也是后世“怨而不怒”的一个例子。"],"quiz":[["“羔裘如膏”的“膏”指？",["油脂，形容皮毛润泽","膏药","食物"],"如膏是像油脂一样光滑润泽，形容衣服华美。"],["全诗如何形成对比？",["衣服的光鲜与心情的忧愁","贫与富","老与少"],"三章以衣服的华丽对比诗人的忧愁。"]],"cards":[["《羔裘》的情感？","对在位者闲游、国事不理的忧心。"],["“岂不尔思，劳心忉忉”的意思？","难道我不想你吗？只是忧愁不安。"]],"line":["羔裘逍遥，狐裘以朝","对表面光鲜、实际不干事的领导的婉转讽刺，可以引“羔裘逍遥，狐裘以朝”。"],"tags":["讽刺","对比","桧风"]},"shijingf_xiyoucuchu":{"intro":"《桧风·隰有苌楚》是一首绝望的诗：低洼地里长着苌楚，枝条柔美，嫩叶茂盛，我羡慕你什么都不知道、没有家、没有室。《诗经》中少有这样的直接表达：羡慕草木的无知。读它要看三章“无知”“无家”“无室”怎样把绝望从精神推到现实。","focus":["起兴“隰有苌楚，猗傩其枝”：低湿处长着苌楚，枝条柔美。苌楚是一种蔓生植物，说法不一，有说是羊桃（猕猴桃一类）。三章依次写其枝、其华、其实：枝条、花、果实，是植物生长的完整过程。","“夭之沃沃”形容嫩而润泽，是生机的象征。然后是转折：“乐子之无知”：我羡慕你什么都不知道。第二章“乐子之无家”，第三章“乐子之无室”。从无知，到无家，到无室，从精神层面的无忧，到现实层面的无牵挂。","这首诗的特别在于，它把人生的负担写成了不如草木：草木自由无忧，人则有知、有家、有室，却因此痛苦。传统说是桧国政乱，人民困苦，故羡慕草木，存疑。这个“羡慕无知”的想法，后来庄子、陶渊明也有类似的表达。"],"notes":[["隰","低湿的地方"],["苌楚","一种蔓生植物，说法不一"],["猗傩","柔美的样子"],["夭之沃沃","嫩而润泽"],["乐子之无知","羡慕你没有知觉"],["华","花"],["实","果实"],["无家","没有家累"],["无室","没有妻室"]],"think":["“乐子之无知”为什么是一种极端的羡慕？","因为它把“知”看作痛苦的来源：知道得越多，痛苦越多。羡慕草木，是对自己处境的最彻底的否定。可以看出，这位作者并不是不想生活，而是被生活压到极致。这样的情绪，在后世的“难得糊涂”里有较温和的版本。"],"quiz":[["“乐子之无知”的“子”指？",["苌楚","诗人自己","国君"],"“子”是对苌楚的称呼，诗人羡慕草木无知。"],["三章“无知”“无家”“无室”的变化是？",["由精神到现实的无牵挂","由现实到精神","没有变化"],"从无知（精神）到无家、无室（现实），羡慕的内容越来越具体。"]],"cards":[["《隰有苌楚》的情感？","羡慕草木无知无家，是绝望之语。"],["“夭之沃沃”形容？","草木嫩润有生机。"]],"line":["乐子之无知","项目压力太大时，可以自嘲一句“乐子之无知”。"],"tags":["绝望","草木","桧风"]},"shijingf_feifeng":{"intro":"《桧风·匪风》是一个远行人望着故国的路，心里悲伤：不是风在吹，不是车在疾驰，我回头看着周道，心里悲痛。末章用烹鱼的比喻，谁能烹鱼，我愿为他洗锅；谁将回西方，请带给我好消息。读它要看“匪风”“匪车”的否定句怎样写出“风与车都与我无关”的失落。","focus":["首章“匪风发兮，匪车偈兮。顾瞻周道，中心怛兮”：不是风在吹，不是车在疾驰，是我心里的感受。偈是疾驰，怛是悲伤。风与车是外界的动，而诗人的心是内里的震动，也是一种“否定外物，肯定内心”的写法。","“顾瞻周道”是关键动作：回头看周道，即通往周室的大道。周道在这里既是一条路，也是对周王室的怀念。三章里“怛”“吊”（悲伤）依次出现，感情是固定的，只是风车的形容在变：发、偈，飘、嘌。","末章“谁能亨鱼？溉之釜鬵。谁将西归？怀之好音”：谁能烹鱼，我愿为他洗锅；谁将西归，请送去一个好消息。烹鱼、洗锅是日常的好意，西归、好音是对故国的牵挂。全诗到这里，从悲伤转到对他人的善意，这是一个远行者收束情绪的方式。"],"notes":[["匪风","不是风"],["发","吹动"],["偈","疾驰的样子"],["顾瞻","回头看"],["周道","通往周京的大道"],["中心怛兮","心中悲伤"],["飘","风吹的样子"],["嘌","疾驰的样子"],["吊","悲伤"],["亨鱼","烹鱼，亨同烹"],["釜鬵","锅"],["好音","好消息"]],"think":["为什么末章写“烹鱼”和“洗锅”？这与前面的悲伤有什么关系？","烹鱼洗锅是最日常的家务，诗人用它表达愿意为人效力、温暖他人的心意。在前面的悲伤之后，这是一种出口：不再只是望，而是愿意做点什么。同时，“谁将西归”的询问，也让这首诗带有一点希望：有人回去，就有人捎信。"],"quiz":[["“匪风发兮，匪车偈兮”的意思？",["不是风吹，不是车跑，是心在动","风很大，车很快","风停了，车停了"],"用否定外物的方式，强调悲伤来自内心。"],["“顾瞻周道”中“周道”指？",["通往周京的大道","周围的道路","周朝的法律"],"周道是通往周王室的大路，有对故国的怀念。"]],"cards":[["《匪风》的情感？","对故国与周道的思念。"],["“谁将西归，怀之好音”？","谁要向西回去，请给我带个好消息。"]],"line":["谁将西归？怀之好音","同事回总部时，可以说“谁将西归，怀之好音”，托他带个口信。"],"tags":["思乡","否定句","周道"]},"shijingf_fuyou":{"intro":"《曹风·蜉蝣》是一首关于生命短暂的诗：蜉蝣的翅膀，衣裳鲜明；蜉蝣的羽翼，彩衣光亮；蜉蝣钻出泥土，白衣如雪。而诗人心里忧愁：我的归处在哪里。三章只换衣饰与“归处、归息、归说”。读它要看一个微小的昆虫怎样映出人的存在之问。","focus":["起兴“蜉蝣之羽，衣裳楚楚”：蜉蝣是朝生暮死的小虫，翅膀像华丽的衣裳。“楚楚”是鲜明整洁，说明短暂的生命也有美的光彩。“心之忧矣，于我归处”：我心忧愁，我的归宿在哪里？这是以蜉蝣的短暂，映出人的无常。","二章“蜉蝣之翼，采采衣服”，三章“蜉蝣掘阅，麻衣如雪”：掘阅是从泥土里钻出来，麻衣如雪是白色的丧服般的外衣。三种衣饰：楚楚、采采、如雪，也是蜉蝣的三种姿态，色泽越来越素，似乎在暗示由盛向衰。","三章末句“于我归处”“于我归息”“于我归说”：处是居所，息是休息，说是歇息，三个词依次变化，是诗人对“归宿”的三种想象。短暂的生命也需要一个“归”。传统认为这是讽刺曹国国君沉溺奢华，存疑，这首诗最直接的解读是对生命有限的叹息。"],"notes":[["蜉蝣","朝生暮死的昆虫"],["衣裳楚楚","衣服鲜明整洁"],["心之忧矣","我心忧愁"],["于我归处","我的归宿在哪里"],["采采","色彩鲜明"],["掘阅","从土中钻出，一说穿穴"],["麻衣如雪","白色麻衣像雪"],["归息","归去安息"],["归说","归去休息，说通“税”"]],"think":["“蜉蝣”在后世诗文中成为什么象征？这首诗与后世的联系是什么？","成为短暂生命的象征，如苏轼《赤壁赋》中的“寄蜉蝣于天地”。这首诗是起点：它把一只小虫的美与短暂并置，让人联想到自己的有限。不同的是，这首诗最后落在“归处”，而不是接受或超越，保留了一种尚未解决的忧愁。"],"quiz":[["“蜉蝣”象征什么？",["生命短暂","永生","勇敢"],"蜉蝣朝生暮死，常用来象征生命短暂。"],["“于我归处”表达？",["对归宿的追问","对住房的要求","对旅行的计划"],"诗人由蜉蝣的短暂联想到自己的归宿。"]],"cards":[["《蜉蝣》的主题？","生命短暂，对归宿的忧愁。"],["“衣裳楚楚”描写什么？","蜉蝣翅膀像衣服一样鲜明整洁。"]],"line":["蜉蝣之羽，衣裳楚楚","看到一个光鲜却短命的项目，可以感叹“蜉蝣之羽，衣裳楚楚”。"],"tags":["生命","象征","曹风"]},"shijingf_houren":{"intro":"《曹风·候人》是一首讽刺诗：那位拿着戈和祋的候人（路上迎送宾客的小官），与穿着赤芾的三百位大夫，形成强烈对比。鹈鹕站在鱼梁上，却不沾湿翅膀，那些人，配不上他们的服饰。读它要看四章怎样把“小官苦、贵人闲”写成一幅对照图。","focus":["首章“彼候人兮，何戈与祋”：那个候人扛着戈与祋，是低级的差役。接着“彼其之子，三百赤芾”：那些人，有三百个穿着赤芾（红色蔽膝）的大夫。赤芾是大夫的服饰，三百人，说明冗员之多。小与大，苦与闲，在第一章就完成对照。","二、三章用鹈鹕起兴：“维鹈在梁，不濡其翼”，鹈鹕站在鱼梁上，却不沾湿翅膀，也就是不捕鱼，占着位置而不做事。接着“彼其之子，不称其服”：那些人，配不上他们的服饰；“不遂其媾”，不称其宠幸（媾的解释不一，存疑）。这是对尸位素餐的直接讽刺。","末章“荟兮蔚兮，南山朝隮。婉兮娈兮，季女斯饥”：南山上云雾蒸腾，早晨有虹；年幼的女孩，却饿着肚子。这一章转入对弱者的怜悯，画面细腻，与前面的讽刺形成对照：高处是虹，低处是饥饿。这一句最有力的是“斯饥”二字。"],"notes":[["候人","在路上迎送宾客的小官"],["何戈与祋","扛着戈和殳"],["彼其之子","那些人"],["赤芾","红色的蔽膝，大夫的服饰"],["鹈","鹈鹕，一种水鸟"],["不濡其翼","不沾湿翅膀"],["不称其服","配不上他的服饰"],["不遂其媾","不能称其宠幸，存疑"],["荟兮蔚兮","云雾蒸腾的样子"],["朝隮","早晨的虹"],["季女斯饥","年幼的女孩在挨饿"]],"think":["“维鹈在梁，不濡其翼”为什么是尸位素餐的好比喻？","因为鹈鹕站在鱼梁上，本是捕鱼的最佳位置，却不下水，等于占着位置不做事。这是一个形象的“占位不干活”画面。放到今天，也可以用来形容拥有资源却不创造价值的人：不是没有条件，而是没有行动。"],"quiz":[["“不称其服”的意思？",["配不上他穿的服饰","衣服不合身","没有衣服"],"称是相称，不称其服是才德与地位不相称。"],["末章“季女斯饥”的作用？",["以弱者之饥对照上层之闲","描写天气","表扬官员"],"小女孩挨饿，与三百赤芾形成强烈对比。"]],"cards":[["《候人》的核心对比？","一个低级候人与三百位穿赤芾的大夫。"],["“维鹈在梁，不濡其翼”的含义？","占着位置却不做事。"]],"line":["彼其之子，不称其服","形容德不配位的人，可以说“彼其之子，不称其服”。"],"tags":["讽刺","对比","尸位素餐"]},"shijingf_shijiu":{"intro":"《曹风·鸤鸠》是一首赞美君子的诗：布谷鸟在桑树上，养着七只小鸟，君子的仪表始终如一，心像打了结，不改变。传统认为是赞美在上者用心均平，也有读作讽刺，存疑。读它要看以鸟喻人的写法，与“其仪不忒，正是四国”的政治理想。","focus":["首章“鸤鸠在桑，其子七兮。淑人君子，其仪一兮”：布谷在桑树上，有七只幼鸟。古人认为布谷喂养幼鸟，早晨自上而下，傍晚自下而上，均平不偏，这是一种传统的说法，是否合于实际，存疑。“其仪一兮”：君子的仪态始终如一，“心如结兮”：心意坚固不变。","二、三章“其子在梅”“其子在棘”“其子在榛”，幼鸟的位置从桑、梅、棘、榛不断变化，而君子的“仪”则不变：“其带伊丝，其弁伊骐”，带是丝带，弁是皮帽上缀的玉；“其仪不忒”，没有差错。外在的服饰与内在的“仪”都有一定之规。","“正是四国”“正是国人”，是把君子的仪态提升为国家的表率：仪态正，就能正四方。末句“胡不万年”是祝福。这首诗是礼乐文化里“以仪正人”的理想表达：个人的稳定与专一，是国家秩序的基础。"],"notes":[["鸤鸠","布谷鸟"],["其子七兮","它的幼鸟有七只"],["淑人君子","善良的君子"],["其仪一兮","他的仪态始终如一"],["心如结兮","心意坚固不变"],["其带伊丝","他的腰带是丝带"],["其弁伊骐","他的帽子缀青黑色玉，说法不一"],["其仪不忒","他的仪态没有差错"],["正是四国","可以匡正四方"],["胡不万年","怎么不祝他万年"]],"think":["“其仪一兮”这样的“专一”，作为统治者的美德，今天还有意义吗？","有意义，但要区分形式的“一”与原则的“一”。仪态一致、言行一致、对待下属一视同仁，是建立信任的基础。但如果“一”变成僵化，就失去了对变化的回应。这首诗里的“一”，指的是内在的稳定与对外的均平，而不是死板，所以读时要抓住“心如结兮”的坚定。"],"quiz":[["“其仪一兮”的意思？",["仪态始终如一","仪态很奇怪","仪态只有一种"],"“一”是专一、始终如一。"],["“正是四国”的意思？",["可以匡正四方","正好有四个国家","正在四国"],"“正”是匡正，“四国”指四方诸侯，意为君子可以作为四方的表率。"]],"cards":[["《鸤鸠》的主题？","赞美君子仪态专一，可正四方。"],["“其仪不忒”？","他的仪态没有差错。"]],"line":["淑人君子，其仪不忒","评价一位言行一致的管理者，可以说“淑人君子，其仪不忒”。"],"tags":["君子","仪态","均平"]},"shijingf_xiaquan":{"intro":"《曹风·下泉》是《曹风》的最后一篇：寒冷的泉水浸润着丛生的稂草，我叹息着醒来，思念那个周京。三章分别写稂、萧、蓍，末章以黍苗被雨水滋润、四方诸侯有王、郇伯慰劳，回忆一个王室庇护天下的时代。读它要看“冽彼下泉”的寒冷怎样引出怀旧，又怎样与“芃芃黍苗”的温润形成对照。","focus":["首章“冽彼下泉，浸彼苞稂”：冷冷的泉水，浸润着一丛丛稂草。稂是童梁草，是一种杂草。泉水冰冷，草被浸润，是弱者在寒冷中的处境。接着“忾我寤叹，念彼周京”：我叹息着醒来，想起那个周京。寤是醒来，叹息是夜里睡不着，所想的是周王室的都城。","二、三章把“稂”换成“萧”“蓍”，“周京”换成“京周”“京师”，是同一个对象的不同称呼：周京、京周、京师。都是指周王室，诗人反复称呼，像是不停地呼唤一个失去的中心。","末章“芃芃黍苗，阴雨膏之。四国有王，郇伯劳之”：黍苗茂盛，阴雨滋润它；四方有王，郇伯慰劳。这是一个理想的画面：王室像雨，四国像黍苗，有人来安抚。是回忆也是对现实缺失的控诉。传统认为这首诗与周王室衰弱有关，具体史事，存疑。"],"notes":[["冽","寒冷"],["下泉","地下涌出的泉水"],["苞稂","丛生的稂草"],["忾","叹息"],["寤叹","醒来叹息"],["周京","周的京城"],["苞萧","丛生的蒿"],["苞蓍","丛生的蓍草"],["京师","京城"],["芃芃","茂盛的样子"],["阴雨膏之","阴雨滋润它"],["四国有王","四方有王"],["郇伯劳之","郇伯慰劳他们"]],"think":["这首诗用“泉水”与“阴雨”两种水，构成了怎样的对照？","前面的泉水是冷的，是下面涌出来的，浸润的是杂草，象征人民在现实中的寒冷；后面的阴雨是从天上来的，滋润的是黍苗，象征王室的恩泽。两种水的温度与方向相反，一个是被动的浸，一个是主动的润。这个对比，说明了诗人对现实的失望和对理想的向往。"],"quiz":[["“念彼周京”表达？",["对周王室的思念","对旅行的向往","对家庭的思念"],"周京是周王室的京城，诗人醒来叹息，思念往日的天下秩序。"],["“芃芃黍苗，阴雨膏之”比喻？",["王室的恩泽滋润四方","庄稼丰收","天气转好"],"黍苗象征诸侯与人民，阴雨比喻王室的恩泽。"]],"cards":[["《下泉》的情感？","在衰败中怀念往日周王室的庇护。"],["“冽彼下泉”的作用？","起兴，以寒冷的泉水象征弱者的处境。"]],"line":["冽彼下泉，浸彼苞稂","形容在寒冷环境中仍然坚持的人，可以引“冽彼下泉，浸彼苞稂”。"],"tags":["怀旧","起兴","曹风"]},"shijingf_chixiao":{"intro":"《豳风·鸱鸮》是一首以鸟的口吻写成的诗：鸱鸮啊鸱鸮，你已经抓了我的孩子，不要再毁我的家。《尚书·金縢》记载，周公作诗送给成王，叫作《鸱鸮》。全诗以母鸟的口吻，诉说筑巢的艰辛、风雨的飘摇。读它要看这首诗怎样用一只鸟，把一个人的处境说完。","focus":["首章“鸱鸮鸱鸮，既取我子，无毁我室”：对象是猛禽鸱鸮，它已经抓走了我的孩子，请不要再毁坏我的家。“恩斯勤斯，鬻子之闵斯”：我辛勤养育孩子，是多么可怜啊。这一章的语气是哀求。","二章“迨天之未阴雨，彻彼桑土，绸缪牖户”：趁着天还没下雨，取桑根的皮，缠绕窗和门。这是母鸟的预防：未雨绸缪。这个成语出自这里。接着“今女下民，或敢侮予”：你们下面的人，谁敢欺负我。这一句，有反击的强硬。","三、四章写辛劳与危机：“予手拮据，予所捋荼”：我的手累病了，还在采茅草；“予羽谯谯，予尾翛翛，予室翘翘。风雨所漂摇，予维音哓哓”：我的羽毛稀疏，尾巴枯焦，我的家高高悬着，风雨中飘摇，我只有不停地尖叫。全诗是一个弱者在强敌与风雨之间的自白。《金縢》说这是周公所作，是传统的说法，今天不能完全证实，存疑。"],"notes":[["鸱鸮","猫头鹰一类的猛禽"],["既取我子","已经抓了我的孩子"],["恩斯勤斯","恩情与勤劳啊"],["鬻子之闵斯","养育孩子很可怜啊"],["迨天之未阴雨","趁天没下雨"],["彻彼桑土","取桑根的皮"],["绸缪牖户","缠紧门窗"],["予手拮据","我的手累得酸痛"],["捋荼","采茅草的花穗"],["予羽谯谯","我的羽毛稀疏"],["予尾翛翛","我的尾巴枯焦"],["予室翘翘","我的家高悬"],["予维音哓哓","我只是不停地尖叫"]],"think":["“迨天之未阴雨，彻彼桑土，绸缪牖户”后来成为成语“未雨绸缪”，原诗的用意与今天的用法一致吗？","基本一致，但原诗的“绸缪”是母鸟为自己的巢做防护，既有预防，也有保护孩子的情感。今天的“未雨绸缪”多用于理性的风险管理，少了情感成分。读到原诗，会发现这个词语最初是一个带着焦虑和辛劳的动作，而不只是一个“聪明的做法”。"],"quiz":[["“未雨绸缪”出自哪里？",["《豳风·鸱鸮》","《论语》","《楚辞》"],"“迨天之未阴雨，彻彼桑土，绸缪牖户”是成语的出处。"],["全诗用了什么口吻？",["母鸟的口吻","猎人的口吻","诗人旁观"],"全诗以母鸟的第一人称，向鸱鸮诉说。"]],"cards":[["“迨天之未阴雨”后面是什么？","彻彼桑土，绸缪牖户，趁没下雨先修好巢。"],["《鸱鸮》的写法？","以鸟自述，借喻人的处境。"]],"line":["迨天之未阴雨，彻彼桑土","在行业寒冬来临前，可以说“迨天之未阴雨，彻彼桑土”，提醒要提前准备。"],"tags":["未雨绸缪","寓言","周公"]},"shijingf_dongshan":{"intro":"《豳风·东山》是《诗经》里最完整的叙事诗：一个战士在东山服役三年，终于在细雨中踏上归途，一路想象家里的样子：果树的藤蔓爬上屋檐，潮虫在房里，蜘蛛结网在门上；妻子在家里叹息，打扫房屋，等他回来。最后写新婚的往事：“其新孔嘉，其旧如之何”。读它要看四章同一开头怎样把一场归途拉成长镜头。","focus":["每章都以同一句开头：“我徂东山，慆慆不归。我来自东，零雨其蒙”：我去东山，久久不回；我从东边回来，细雨蒙蒙。四次重复，像一个长镜头里的雨声。第一章“我东曰归，我心西悲”是全诗的情感轴：说要回家，却满心悲伤。","二、三章是想象：家里“果臝之实，亦施于宇”，瓜藤爬上屋檐；“伊威在室，蟏蛸在户”，潮虫在屋里，蜘蛛在门上；“町畽鹿场，熠耀宵行”，空地成了鹿场，夜晚有萤火虫。一连串荒废的景象，却以“不可畏也，伊可怀也”收束：不可怕，反而让人怀念。这是整首诗最动人的一句。","后半转入妻子：“鹳鸣于垤，妇叹于室。洒扫穹窒，我征聿至”：鹳鸟在土堆上叫，妻子在家叹息；她打扫屋子，等我回来。末章回到新婚之时：“仓庚于飞，熠耀其羽”，黄鹂飞翔；新娘“皇驳其马”，结缡礼仪繁多。“其新孔嘉，其旧如之何”：新婚那么美好，如今又是什么样子呢？这是一个轻轻的疑问，也是一个深深的牵挂。"],"notes":[["徂","往，去"],["东山","地名，在东方"],["慆慆","时间长久的样子"],["零雨其蒙","细雨蒙蒙"],["勿士行枚","不再衔枚行军"],["蜎蜎","虫蠕动的样子"],["蠋","桑树上的青虫"],["果臝","一种蔓生植物，栝楼"],["伊威","潮虫"],["蟏蛸","一种长脚蜘蛛"],["町畽","空地"],["熠耀宵行","萤火虫夜里发光"],["鹳鸣于垤","鹳鸟在土堆上叫"],["穹窒","堵塞鼠洞"],["仓庚","黄鹂"],["皇驳","黄白、红白相杂的马"],["九十其仪","礼仪繁多"]],"think":["“不可畏也，伊可怀也”为什么是全诗最动人的一句？","因为荒废的景象本应让人害怕，战士却说“可怀”，说明他在乎的不是屋子，而是家。破败的屋子、虫子、蜘蛛，都是时间留下的痕迹，也是等待的证明。他不怕这些，是因为这些是“家”的一部分。这是一句看似平淡的话，却写出了对家的全部感情。"],"quiz":[["“零雨其蒙”的意思是？",["细雨蒙蒙","大雨倾盆","雨停了"],"零雨是细雨，其蒙是蒙蒙。"],["末章“其新孔嘉，其旧如之何”意思？",["新婚时那么美好，如今怎么样了呢","新衣很美，旧衣怎么办","新朋友很好，旧朋友很差"],"新指新婚，旧指分别三年之后的现在，是带着牵挂的疑问。"]],"cards":[["《东山》的结构？","四章同一开头，写归途、想象家里、妻子等待、新婚回忆。"],["“不可畏也，伊可怀也”？","荒废的景象不可怕，反而让人怀念。"]],"line":["我徂东山，慆慆不归","长期出差后回家，可以说“我徂东山，慆慆不归”。"],"tags":["征人","归乡","叙事诗"]},"shijingf_pofu":{"intro":"《豳风·破斧》是东征将士赞美周公的诗：我的斧头破了，我的斨也缺了，周公东征，四方的国家都得到了匡正。可怜我们这些人，也算是大幸。三章只换兵器（斨、锜、銶）和评价（皇、遒；将、嘉、休）。读它要看一个战士怎样把“伤亡与损耗”和“荣幸”写在同一首诗里。","focus":["首章“既破我斧，又缺我斨”：斧头已经破了，斨（方孔的斧）也缺了。这是战争的损耗，不加修饰。二章换成锜（凿子类工具），三章换成銶（独头斧），三种兵器都在受损，说明战争的长久与激烈。","“周公东征，四国是皇”：周公东征，四方的国家得到匡正。“皇”的解释说法不一，有匡正、有辉煌，存疑。第二、三章换成“四国是遒”，遒是巩固，说明东征的结果是稳固。这是对统帅的颂扬，用语克制，没有夸张。","“哀我人斯，亦孔之将”“亦孔之嘉”“亦孔之休”：怜惜我们这些人，也很幸运，很好，很美。将、嘉、休，三个词依次递进，是对幸存的庆幸，也是对将士的慰劳。“哀我人斯”是一种带着泪的自我怜惜，却用“亦孔之嘉”完成了对战争的肯定。"],"notes":[["斧","斧头"],["斨","方孔的斧"],["周公东征","周公领兵向东征伐"],["四国","四方的诸侯国"],["皇","匡正，一说辉煌"],["哀我人斯","怜惜我们这些人"],["亦孔之将","也很幸运，将，大"],["锜","凿子一类的工具"],["遒","巩固，坚固"],["嘉","美好"],["銶","独头斧"],["休","美好，吉庆"]],"think":["这首诗把“破斧缺斨”的损耗与“亦孔之嘉”的庆幸并置，你怎么理解？","战争的代价是真实的，诗人没有回避，但他选择把“活下来”视为最大的幸运。这种并置是平民对战争的感受：荣光属于统帅，幸运属于幸存者。诗里的颂扬，与其说是对战争的肯定，不如说是对结束的感谢。读者不应把它简单读成歌颂战争。"],"quiz":[["“既破我斧，又缺我斨”写什么？",["战争中兵器损耗","制作工具","农活"],"斧与斨的破缺，是战争激烈的写照。"],["“亦孔之嘉”表达什么？",["对幸存的庆幸","对战争的批评","对工具的赞美"],"“哀我人斯，亦孔之嘉”是将士对幸存的感慨。"]],"cards":[["《破斧》写什么？","东征将士赞美周公，同时写自己的损耗与幸运。"],["“哀我人斯”意思？","怜惜我们这些人。"]],"line":["哀我人斯，亦孔之嘉","项目艰难交付后，可以感叹“哀我人斯，亦孔之嘉”。"],"tags":["东征","周公","幸存"]},"shijingf_ike":{"intro":"《豳风·伐柯》只有八句：砍斧柄怎么办？没有斧头不行；娶妻怎么办？没有媒人不行。握着斧柄去砍斧柄，样子就在眼前；我见到这位女子，笾豆整齐陈列。这首诗以劈柴比婚姻，朴素而精准。读它要看“其则不远”这个比喻的巧妙。","focus":["首章“伐柯如何？匪斧不克。取妻如何？匪媒不得”：伐柯是砍斧柄，匪斧不克是没有斧头无法砍成。两个问句的结构完全对应：伐柯要斧，取妻要媒。这是以工具喻媒妁，说明在周代婚姻中，媒人是必须的环节。同样的句式出现在《齐风·南山》，说明这是当时通行的说法。","二章“伐柯伐柯，其则不远”：砍斧柄砍斧柄，样子就在不远处，因为你手里拿的斧柄，就是新斧柄的样子。这一句非常巧妙：以柄伐柄，范本就在手边。比喻媒人说合的婚事，也有现成的规范。","末句“我觏之子，笾豆有践”：我见到了这位女子，笾豆（祭祀、宴会用的器皿）整整齐齐。笾豆有践，既是婚礼的陈设，也是秩序的象征。全诗不到三十字，从一个日常劳动，推到婚礼的规范，是《诗经》中少见的“说理”小诗。"],"notes":[["伐柯","砍斧柄"],["匪斧不克","没有斧头不能成功"],["取妻","娶妻"],["匪媒不得","没有媒人不能成"],["其则不远","榜样不远"],["我觏之子","我见到这位女子"],["笾豆","盛食物的竹器和木器"],["有践","整齐陈列的样子"]],"think":["“伐柯伐柯，其则不远”后来被当作什么道理？它的道理在哪里？","后来被引申为“以人治人”：以现成的榜样去规范人，因为规范就在人身上，不需要远求。《中庸》里引用过类似的说法。这首诗的比喻本身很朴素：用手中的斧柄来比量新斧柄。它说明，最好的参照物往往就在手边。"],"quiz":[["“匪斧不克”的意思是？",["没有斧头就不能砍成","不是斧头也能砍","斧头不够用"],"“匪”是没有，“克”是能，意思是没有斧头不行。"],["“笾豆有践”描写？",["婚礼器皿陈列整齐","田野丰收","战争的兵器"],"笾豆是祭祀宴会器皿，有践是整齐陈列。"]],"cards":[["《伐柯》的比喻？","砍斧柄需要斧头，娶妻需要媒人。"],["“其则不远”？","榜样就在手边。"]],"line":["伐柯伐柯，其则不远","培训新人时，最好的榜样就在身边，可以说“伐柯伐柯，其则不远”。"],"tags":["婚姻","比喻","媒妁"]},"shijingf_jiuyu":{"intro":"《豳风·九罭》是一首挽留诗：细眼的渔网里有鳟鱼和鲂鱼，我见到这位穿着衮衣绣裳的公子。鸿雁沿着水边飞，公要回去，没有归宿；鸿雁沿着陆地飞，公回去不再回来，请你多住几晚。末章“无以我公归兮，无使我心悲兮”，是请求不要让公回去。传统认为是周公东归，豳人挽留，存疑。读它要看一首挽留诗怎样用鱼、鸿雁、衮衣三个意象，完成对一位大人物的珍惜。","focus":["首章“九罭之鱼，鳟鲂。我觏之子，衮衣绣裳”：九罭是细眼的渔网，网里有鳟鱼和鲂鱼，是好的收获。接着“我见到这位公子，穿着衮衣绣裳”：衮衣是绘有龙纹的礼服，是上公的礼服。以渔获起兴，是说“有幸遇到这样的贵人”。","二章“鸿飞遵渚，公归无所，于女信处”：鸿雁沿着水边飞，公要回去却没有一个归宿，在你这里多住两夜吧。三章“鸿飞遵六，公归不复，于女信宿”：鸿雁沿陆地飞，公回去后不会再来，在你这里再住两夜。信处、信宿，都是再住两夜，是一种小小的恳求。","末章“是以有衮衣兮，无以我公归兮，无使我心悲兮”：我们这里有衮衣，请别把公带回去，别叫我们心里悲伤。这一章把衣服作为挽留的理由，衮衣在这里，请公留下。全诗的语气柔软，没有强求，只有一遍遍的“再住几晚”，是民间对一位德高者的朴素依恋。"],"notes":[["九罭","细眼的渔网"],["鳟","一种鱼"],["鲂","鳊鱼"],["我觏之子","我见到这位公子"],["衮衣绣裳","绣有龙纹的礼服"],["鸿飞遵渚","鸿雁沿着水边飞"],["公归无所","公回去没有归处"],["于女信处","在你这里再住两夜"],["遵六","沿着陆地，六通“陆”"],["公归不复","公回去不会再来"],["于女信宿","在你这里再住两晚"],["无以我公归兮","不要带我们的公回去"]],"think":["为什么一首挽留诗全篇都没有出现“请留下”这样直接的话，却更有力量？","因为“于女信处”“于女信宿”已经是最具体的恳求：再住两夜。不需要“请留下”，因为每一个细节都在说。这是以小挽留代替大挽留：不求永远，只求多留两夜。这样的请求更容易被接受，也更真实。"],"quiz":[["“信处”“信宿”的意思？",["连住两夜","一夜","三夜"],"《诗经》里“再宿为信”，信处、信宿即再住两夜。"],["“衮衣”是什么？",["绘龙的上公礼服","渔网","鱼"],"衮衣是上公穿的绘龙纹的礼服。"]],"cards":[["《九罭》的情感？","挽留一位德高者再多住几晚。"],["“于女信处”意思？","在你这里再住两夜。"]],"line":["是以有衮衣兮，无以我公归兮","挽留一位离职的领导，可以说“是以有衮衣兮，无以我公归兮”。"],"tags":["挽留","周公","意象"]},"shijingf_langba":{"intro":"《豳风·狼跋》是《豳风》的最后一篇：狼踩着自己的下巴肉，又被尾巴绊倒；而公孙，却身形硕美，赤色的鞋子稳重安详。传统认为是赞美周公在遭谗言时仍然从容，存疑。读它要看这首诗怎样以“狼”的狼狈，对比“公孙”的从容。","focus":["首章“狼跋其胡，载疐其尾”：狼往前走踩着自己下巴垂下的肉，往后退又被尾巴绊倒。进退都不行，写得生动。这是一个有画面感的、近乎滑稽的形象，狼的“凶”在这里变成了“窘”。","“公孙硕肤，赤舄几几”：公孙身体硕美，穿着赤色的鞋，步子稳重。几几是安重的样子。一句话，就把从容写出来了。狼的进退失据，与公孙的步履稳健，形成强烈对比。","末句“德音不瑕”是一个反问或肯定：他的声誉没有瑕疵。传统认为“狼”指进谗者，“公孙”指周公，存疑。无论如何，这首诗的写法是先写一个狼狈的形象，再写一个从容的形象，不需要多余的话，对比已经说明一切。"],"notes":[["狼跋其胡","狼踩着自己下巴的垂肉"],["载疐其尾","又被尾巴绊倒"],["公孙","公的孙辈，贵族子弟"],["硕肤","身体硕美，一说肤色美"],["赤舄","红色的鞋"],["几几","安稳庄重的样子"],["德音不瑕","德行与声誉没有瑕疵"],["疐","被绊倒"]],"think":["为什么说“狼跋其胡，载疐其尾”是《诗经》里最有画面感的比喻之一？","因为它抓住了一个具体的动作：向前踩下巴，向后绊尾巴。这是一个可以想象的、有喜剧感的画面，不需要解释就能被理解。它说明“进退两难”这个抽象的状态，可以被一个具体的形象表达，这是文学的本领。"],"quiz":[["“狼跋其胡，载疐其尾”形容？",["进退两难、狼狈","狼的凶猛","狼的奔跑"],"向前踩住下巴，向后绊倒尾巴，是进退两难。"],["“赤舄几几”形容公孙？",["稳重从容","狼狈","匆忙"],"几几是安稳庄重的样子，与狼形成对比。"]],"cards":[["《狼跋》的对比？","狼的狼狈与公孙的从容。"],["“狼跋其胡，载疐其尾”的成语？","进退两难，后世写作“狼跋”类的表达。"]],"line":["狼跋其胡，载疐其尾","遇到进退两难的局面，可以说“狼跋其胡，载疐其尾”。"],"tags":["对比","进退两难","周公"]}});
